
/* ===== Les 22 arcanes majeurs : textes originaux ===== */
const CARDS = [
{ id:"mat", n:0, nom:"Le Mat",
  mots:["Liberté","Aventure","Élan"],
  symb:"Un voyageur marche avec son baluchon, un animal à ses trousses : il avance sans plan, mais il avance.",
  up:"Le Mat est l'énergie pure du voyage. Liberté, spontanéité, envie d'ailleurs : tu sors du cadre, et c'est peut-être exactement ce qu'il fallait.",
  rev:"Retourné, Le Mat parle de fuite ou d'imprudence. Tu pars sans savoir où, ou tu évites une responsabilité. Garde ton élan, mais regarde où tu mets les pieds.",
  noyau:["un élan de liberté et l'appel de l'aventure","une fuite en avant et un peu d'imprudence"],
  amour:["En amour, une relation libre et spontanée, ou une rencontre en voyage. Pas de plan, juste l'envie.","En amour, peur de l'engagement ou relation instable. Demande-toi ce que tu fuis."],
  travail:["Côté travail, un changement de voie, un projet atypique, une liberté retrouvée.","Côté travail, manque de sérieux ou départ précipité. Prépare ta sortie avant de claquer la porte."],
  argent:["Pour l'argent, une dépense pour un voyage ou une expérience qui en vaut la peine.","Pour l'argent, insouciance et dépenses sans compter."],
  conseil:["Pars, même sans tout savoir.","Garde l'élan, mais fais un plan."] },

{ id:"bateleur", n:1, nom:"Le Bateleur",
  mots:["Initiative","Talent","Commencement"],
  symb:"Un jeune homme devant une table couverte d'outils : il a tout pour commencer, il lui reste à choisir.",
  up:"Le Bateleur ouvre le jeu. C'est le moment de te lancer avec ce que tu as déjà sous la main : tes idées, ton énergie, ta débrouille. Rien n'est parfait, mais tout est possible.",
  rev:"Retourné, Le Bateleur parle d'un départ brouillon. Tu t'éparpilles, tu doutes de tes capacités ou tu bluffes un peu. Avant d'agir, choisis un seul outil et apprends à t'en servir.",
  noyau:["un élan neuf et l'envie de tenter ta chance","un départ hésitant et des talents mal employés"],
  amour:["En amour, une rencontre, un premier pas ou une relation qui repart avec légèreté. Ose engager la conversation.","En amour, les intentions manquent de clarté : promesses faciles, séduction sans suite. Vérifie que les actes suivent les mots."],
  travail:["Côté travail, un projet démarre ou une compétence peut enfin servir. Bonne période pour proposer, postuler, créer.","Côté travail, tu t'agites sans avancer, ou on te vend quelque chose de trop beau. Structure ton projet avant de le présenter."],
  argent:["Pour l'argent, une petite rentrée ou une idée qui peut rapporter si tu la lances vraiment.","Pour l'argent, attention aux combines et aux dépenses sur un coup de tête."],
  conseil:["Commence aujourd'hui, même petit.","Concentre-toi sur une seule chose à la fois."] },

{ id:"papesse", n:2, nom:"La Papesse",
  mots:["Savoir","Patience","Intériorité"],
  symb:"Une femme assise, un livre ouvert sur les genoux : la connaissance se mûrit en silence.",
  up:"La Papesse invite au recul. Les réponses viennent de l'étude, de l'observation et de ton intuition, pas de l'agitation. Ce qui se prépare dans l'ombre aboutira.",
  rev:"Retournée, La Papesse signale une fermeture. Trop de réserve, des non-dits ou des secrets freinent la situation. Il est temps de partager ce que tu sais.",
  noyau:["une période de réflexion et une sagesse qui se forme en silence","des non-dits et une réserve qui finit par isoler"],
  amour:["En amour, des sentiments discrets mais profonds. La relation gagne à prendre son temps.","En amour, la froideur ou le silence s'installent. Un sujet évité mérite d'être mis sur la table."],
  travail:["Côté travail, formation, études, lecture de dossiers : tout ce qui demande de la rigueur est favorisé.","Côté travail, une information t'échappe, ou tu gardes trop tes idées pour toi. Montre ce que tu sais faire."],
  argent:["Pour l'argent, gestion prudente et économies réfléchies. Ce n'est pas le moment de spéculer.","Pour l'argent, lis bien les petites lignes : un détail caché peut coûter cher."],
  conseil:["Renseigne-toi avant de décider.","Dis à voix haute ce que tu gardes pour toi."] },

{ id:"imperatrice", n:3, nom:"L'Impératrice",
  mots:["Créativité","Expression","Fécondité"],
  symb:"Une souveraine couronnée tient son sceptre : l'intelligence qui s'exprime et fait grandir.",
  up:"L'Impératrice apporte de l'élan créatif et de la confiance. Tes idées prennent forme, tu sais convaincre et séduire. Une belle période pour t'exprimer.",
  rev:"Retournée, L'Impératrice parle d'une créativité bloquée ou d'un ego qui prend trop de place. Tu peux avoir l'impression que personne ne t'écoute, ou vouloir tout contrôler.",
  noyau:["une énergie créative et une parole qui porte","une créativité bloquée et un besoin de plaire trop fort"],
  amour:["En amour, séduction, complicité et projets à deux. La relation s'épanouit.","En amour, jalousie ou besoin d'être admiré prennent le dessus sur l'échange sincère."],
  travail:["Côté travail, communication, création et prise de parole sont tes atouts. Une idée peut être très bien reçue.","Côté travail, tu manques d'inspiration ou tes idées ne passent pas. Reformule-les plus simplement."],
  argent:["Pour l'argent, une période favorable aux projets qui grandissent : ventes, créations, petites réussites.","Pour l'argent, des dépenses pour l'image ou le paraître pèsent sur ton budget."],
  conseil:["Exprime tes idées, elles méritent d'être entendues.","Crée pour toi avant de créer pour plaire."] },

{ id:"empereur", n:4, nom:"L'Empereur",
  mots:["Stabilité","Autorité","Concret"],
  symb:"Un souverain assis de profil, appuyé sur son trône : le pouvoir qui construit et protège.",
  up:"L'Empereur apporte du solide. Les choses se posent, les décisions se prennent, les bases se construisent. Tu as l'autorité pour faire avancer la situation.",
  rev:"Retourné, L'Empereur devient rigide. Autoritarisme, entêtement ou besoin de tout contrôler bloquent le mouvement. La force sans souplesse finit par casser.",
  noyau:["une base solide et la capacité de décider","une rigidité et un besoin de contrôle qui bloquent tout"],
  amour:["En amour, engagement, sécurité, relation stable. Quelqu'un sur qui tu peux compter.","En amour, rapport de force, jalousie possessive ou manque de tendresse. Personne ne gagne à commander l'autre."],
  travail:["Côté travail, poste stable, responsabilités, cadre clair. Bon moment pour négocier ou signer.","Côté travail, conflit avec la hiérarchie ou cadre trop strict. Choisis tes batailles."],
  argent:["Pour l'argent, stabilité et bonne gestion. Un investissement concret et réfléchi est favorisé.","Pour l'argent, entêtement sur une mauvaise décision ou dépenses de prestige. Reste pragmatique."],
  conseil:["Pose des bases claires et tiens-les.","Lâche un peu de contrôle, tu ne perdras pas tout."] },

{ id:"pape", n:5, nom:"Le Pape",
  mots:["Transmission","Conseil","Valeurs"],
  symb:"Un sage bénit deux disciples : il relie, transmet et guide.",
  up:"Le Pape parle de transmission et de bon conseil. Une personne de confiance, un mentor ou une institution peut t'aider. Tes valeurs sont un bon guide.",
  rev:"Retourné, Le Pape alerte sur un mauvais conseil ou des règles qui ne te correspondent plus. Méfie-toi des donneurs de leçons et écoute ta propre morale.",
  noyau:["un bon conseil et des valeurs qui guident","un mauvais conseil et des règles qui sonnent faux"],
  amour:["En amour, sincérité, fidélité, envie d'officialiser. La relation repose sur des valeurs communes.","En amour, une relation figée par les conventions ou le regard des autres. Demandez-vous ce que vous voulez vraiment, vous deux."],
  travail:["Côté travail, apprentissage, formation, tutorat. Un supérieur ou ton réseau peut t'ouvrir une porte.","Côté travail, une hiérarchie peu bienveillante ou un cadre trop traditionnel. Cherche un autre mentor."],
  argent:["Pour l'argent, demande conseil à un professionnel avant de t'engager : c'est payant.","Pour l'argent, méfie-toi des conseils trop sûrs d'eux et des promesses de gain facile."],
  conseil:["Écoute quelqu'un qui est passé par là.","Fie-toi à tes valeurs plutôt qu'aux règles toutes faites."] },

{ id:"amoureux", n:6, nom:"L'Amoureux",
  mots:["Choix","Désir","Lien"],
  symb:"Un jeune homme entre deux femmes, et un ange qui vise : le cœur doit choisir.",
  up:"L'Amoureux annonce un choix à faire avec le cœur. Plusieurs chemins s'ouvrent et c'est ton désir profond qui doit trancher. C'est aussi la carte des liens et de la vie sociale.",
  rev:"Retourné, L'Amoureux parle d'indécision. Tu hésites, tu veux tout garder ou tu laisses les autres choisir pour toi. Ne pas choisir, c'est déjà choisir.",
  noyau:["un choix sincère et des liens qui se tissent","une hésitation qui dure et un cœur partagé"],
  amour:["En amour, un coup de cœur, une harmonie retrouvée, une relation qui fait du bien.","En amour, indécision entre deux personnes ou deux envies, ou un engagement qui fait peur."],
  travail:["Côté travail, deux propositions ou deux voies : choisis celle qui te ressemble. Bonne entente avec les collègues.","Côté travail, tu repousses une décision importante. Les tensions d'équipe viennent souvent de là."],
  argent:["Pour l'argent, un choix de dépense ou d'investissement à faire selon tes vraies priorités.","Pour l'argent, achats d'impulsion et difficulté à trancher entre deux options."],
  conseil:["Choisis ce qui te rend vivant.","Tranche, même si ce n'est pas parfait."] },

{ id:"chariot", n:7, nom:"Le Chariot",
  mots:["Victoire","Mouvement","Maîtrise"],
  symb:"Un prince debout sur son char avance droit devant : la volonté qui dirige.",
  up:"Le Chariot annonce l'avancée. Tu reprends les commandes, les obstacles tombent et la situation se débloque. C'est une carte de réussite par l'action.",
  rev:"Retourné, Le Chariot part dans tous les sens. Précipitation, perte de contrôle ou ambition mal dirigée te font avancer de travers. Ralentis pour reprendre le volant.",
  noyau:["une avancée franche et la maîtrise retrouvée","une précipitation et une direction qui t'échappe"],
  amour:["En amour, la relation avance : emménagement, projet commun, déclaration.","En amour, l'un veut aller plus vite que l'autre. Trouvez un rythme commun."],
  travail:["Côté travail, promotion, réussite d'un projet, déplacement professionnel. Fonce.","Côté travail, trop de projets en même temps. Termine avant de recommencer."],
  argent:["Pour l'argent, la situation progresse grâce à tes efforts. Un achat lié aux déplacements est possible.","Pour l'argent, des dépenses qui dérapent et un budget qui t'échappe."],
  conseil:["Fixe ta direction et avance.","Freine avant de choisir ta route."] },

{ id:"justice", n:8, nom:"La Justice",
  mots:["Équilibre","Décision","Vérité"],
  symb:"Une femme tient une balance et une épée : elle pèse, puis elle tranche.",
  up:"La Justice demande de la clarté. Chaque chose est remise à sa juste place : ce que tu as semé te revient. Les décisions prises avec honnêteté seront les bonnes.",
  rev:"Retournée, La Justice signale un déséquilibre. Injustice, mauvaise foi, jugement trop sévère sur toi ou sur les autres. Rétablis les faits avant de juger.",
  noyau:["une décision juste et un équilibre retrouvé","un déséquilibre et un jugement faussé"],
  amour:["En amour, une relation équilibrée où chacun donne autant qu'il reçoit. Les choses sont claires.","En amour, un sentiment d'injustice, des comptes que l'on tient l'un sur l'autre. Parlez des attentes de chacun."],
  travail:["Côté travail, contrat, signature, évaluation favorable. Tes efforts sont reconnus à leur juste valeur.","Côté travail, conflit administratif ou décision qui te semble injuste. Garde des traces écrites."],
  argent:["Pour l'argent, budget équilibré, dossier qui se règle, remboursement possible.","Pour l'argent, litige, retard de paiement ou paperasse à régulariser."],
  conseil:["Sois juste, avec les autres comme avec toi.","Vérifie les faits avant de trancher."] },

{ id:"ermite", n:9, nom:"L'Ermite",
  mots:["Recul","Recherche","Sagesse"],
  symb:"Un vieil homme avance avec sa lanterne : il éclaire le chemin pas à pas.",
  up:"L'Ermite invite à prendre du recul. Le silence et la réflexion t'aident à voir clair. Les choses avancent lentement, mais dans la bonne direction.",
  rev:"Retourné, L'Ermite parle d'un isolement subi ou d'un repli trop long. Tu tournes en rond avec tes questions, sans personne à qui en parler. Accepter de l'aide ferait avancer les choses.",
  noyau:["un recul nécessaire et une sagesse patiente","un isolement qui pèse et un repli trop long"],
  amour:["En amour, une relation mature, ou un temps pour toi afin de comprendre ce que tu cherches vraiment.","En amour, solitude, distance ou difficulté à laisser quelqu'un entrer dans ta vie."],
  travail:["Côté travail, expertise, recherche, travail de fond. La patience paie.","Côté travail, tu manques de visibilité ou de soutien. Va vers les autres."],
  argent:["Pour l'argent, gestion prudente et petites économies régulières. Pas de risque inutile.","Pour l'argent, la peur de manquer t'empêche d'avancer."],
  conseil:["Prends le temps qu'il faut, la lumière est déjà dans ta main.","Sors de ta grotte et demande de l'aide."] },

{ id:"roue", n:10, nom:"La Roue de Fortune",
  mots:["Cycle","Changement","Opportunité"],
  symb:"Une roue tourne, des créatures montent et descendent : rien ne reste figé.",
  up:"La Roue de Fortune annonce que les choses bougent. Une opportunité, un retournement, un nouveau cycle : saisis le mouvement quand il passe.",
  rev:"Retournée, La Roue de Fortune parle de blocage ou de répétition. La situation tourne en rond. Ce qui doit changer, c'est peut-être ta façon de réagir.",
  noyau:["un changement de cycle et une chance à saisir","un blocage et une situation qui tourne en rond"],
  amour:["En amour, un rebondissement, une rencontre inattendue ou une relation qui passe un cap.","En amour, les mêmes schémas se répètent. Cherche ce que tu peux faire différemment."],
  travail:["Côté travail, une opportunité arrive vite : reste prêt à réagir.","Côté travail, retards et stagnation. Patience, et prépare la suite."],
  argent:["Pour l'argent, la situation évolue : rentrée inattendue ou nouvelle source de revenus.","Pour l'argent, des hauts et des bas. Garde une réserve pour les mois difficiles."],
  conseil:["Saisis ta chance quand elle passe.","Change un détail pour casser la répétition."] },

{ id:"force", n:11, nom:"La Force",
  mots:["Courage","Maîtrise","Douceur"],
  symb:"Une femme ouvre la gueule d'un lion sans effort : la force tranquille.",
  up:"La Force te donne le courage d'affronter la situation. Tu maîtrises tes émotions et tu avances avec calme. La douceur obtient plus que la violence.",
  rev:"Retournée, La Force parle de fatigue ou d'émotions qui débordent. Colère, impatience, ou au contraire manque de confiance. Reprends des forces avant de foncer.",
  noyau:["un courage tranquille et une belle maîtrise de soi","une fatigue et des émotions qui débordent"],
  amour:["En amour, passion maîtrisée, confiance et tendresse. La relation est solide.","En amour, disputes, rapport de force ou passion qui fait souffrir. Apaisez le jeu."],
  travail:["Côté travail, tu as l'énergie pour relever un défi. Ta persévérance impressionne.","Côté travail, surmenage ou conflit qui t'épuise. Préserve-toi."],
  argent:["Pour l'argent, tu reprends le contrôle de tes finances avec discipline.","Pour l'argent, dépenses émotionnelles ou peur qui paralyse tes décisions."],
  conseil:["Avance avec calme, tu as plus de force que tu ne le crois.","Repose-toi avant de livrer bataille."] },

{ id:"pendu", n:12, nom:"Le Pendu",
  mots:["Pause","Lâcher-prise","Autre regard"],
  symb:"Un homme suspendu par un pied, les mains dans le dos : il voit le monde à l'envers.",
  up:"Le Pendu impose une pause. Ce n'est pas le moment d'agir mais de regarder autrement. En acceptant l'attente, tu découvres une solution que tu ne voyais pas.",
  rev:"Retourné, Le Pendu parle d'une attente subie, de sacrifices inutiles, d'une impasse. Tu peux en sortir en changeant de point de vue.",
  noyau:["une pause féconde et un nouveau regard","une attente subie et une impasse dont on ne voit pas la sortie"],
  amour:["En amour, la relation est en suspens. Laisse le temps faire son œuvre, sans forcer.","En amour, tu donnes beaucoup sans recevoir, ou tu attends quelqu'un qui ne vient pas."],
  travail:["Côté travail, un projet en attente. Profites-en pour te former ou revoir ta stratégie.","Côté travail, une situation figée. Cherche une autre porte au lieu de pousser celle-ci."],
  argent:["Pour l'argent, une période creuse mais passagère. Évite les grosses décisions.","Pour l'argent, des fonds bloqués ou des sacrifices qui ne mènent à rien."],
  conseil:["Accepte d'attendre et regarde autrement.","Arrête de te sacrifier pour rien."] },

{ id:"sansnom", n:13, nom:"L'Arcane sans nom",
  mots:["Transformation","Fin","Renouveau"],
  symb:"Un squelette fauche un champ : il coupe ce qui doit l'être pour que tout repousse. Sur la carte, aucun nom n'est inscrit.",
  up:"L'Arcane sans nom annonce une transformation profonde. Quelque chose se termine pour laisser place au neuf. Ce n'est pas une fin triste, c'est un grand ménage.",
  rev:"Retourné, l'Arcane sans nom montre une résistance au changement. Tu t'accroches à ce qui est déjà fini. Plus tu retiens, plus c'est difficile.",
  noyau:["une transformation profonde et un vrai renouveau","une résistance au changement et du mal à tourner la page"],
  amour:["En amour, une page se tourne : rupture nécessaire ou relation qui se transforme en profondeur.","En amour, tu t'accroches à une histoire terminée. Laisser partir, c'est aussi te libérer."],
  travail:["Côté travail, changement de poste, reconversion, fin d'un cycle. Le neuf arrive vite.","Côté travail, tu restes dans un poste qui ne te correspond plus, par peur du vide."],
  argent:["Pour l'argent, tu fais le tri : fin d'une dépense, d'un abonnement, d'une dette.","Pour l'argent, de mauvaises habitudes difficiles à couper."],
  conseil:["Coupe ce qui ne pousse plus.","Lâche ce qui est déjà fini."] },

{ id:"temperance", n:14, nom:"Tempérance",
  mots:["Harmonie","Apaisement","Patience"],
  symb:"Un ange verse de l'eau d'un vase à l'autre : tout circule, rien ne se perd.",
  up:"Tempérance apporte l'apaisement. Les tensions se calment, les échanges se font en douceur et tu retrouves ton équilibre. Le temps travaille pour toi.",
  rev:"Retournée, Tempérance parle d'excès ou de déséquilibre. Trop ou pas assez : sommeil, travail, émotions. Il est temps de doser.",
  noyau:["un apaisement et une harmonie qui revient","des excès et un équilibre à retrouver"],
  amour:["En amour, tendresse, réconciliation, relation douce et sereine.","En amour, communication au point mort ou relation tiède. Remettez de l'échange."],
  travail:["Côté travail, collaboration fluide et rythme sain. La diplomatie est ton atout.","Côté travail, un rythme épuisant ou une équipe qui ne se parle plus."],
  argent:["Pour l'argent, les comptes se stabilisent. Rentrées et dépenses s'équilibrent.","Pour l'argent, des dépenses irrégulières. Lisse ton budget sur le mois."],
  conseil:["Dose, mélange, laisse le temps agir.","Reviens au juste milieu."] },

{ id:"diable", n:15, nom:"Le Diable",
  mots:["Désir","Attachement","Pouvoir"],
  symb:"Une créature cornue et ailée, une torche à la main, tient deux petits personnages attachés à son socle : la force du désir, et ses chaînes.",
  up:"Le Diable parle d'énergie brute : désir, ambition, charisme. Cette force peut te porter très loin, à condition qu'elle ne t'enchaîne pas.",
  rev:"Retourné, Le Diable montre un lien qui te retient : une habitude, une relation, une peur. La bonne nouvelle, c'est que les chaînes sont lâches. Tu peux t'en libérer.",
  noyau:["un désir puissant et une énergie qui attire","un attachement qui retient et une chaîne à briser"],
  amour:["En amour, passion intense et forte attirance. Attention à la jalousie et à la possessivité.","En amour, une relation toxique ou une dépendance affective. Tu mérites un lien qui libère."],
  travail:["Côté travail, ambition, sens des affaires, pouvoir de persuasion. Un gros coup est possible.","Côté travail, pression, manipulation ou poste qui t'use. Fixe tes limites."],
  argent:["Pour l'argent, des gains importants sont possibles, surtout par le commerce ou la négociation.","Pour l'argent, dettes, crédits ou achats compulsifs. Reprends la main."],
  conseil:["Fais de ton désir un moteur, pas une laisse.","Repère ce qui te tient, et coupe."] },

{ id:"maisondieu", n:16, nom:"La Maison Dieu",
  mots:["Rupture","Libération","Révélation"],
  symb:"Une tour dont le toit s'ouvre sous une flamme : ce qui était enfermé sort enfin.",
  up:"La Maison Dieu annonce un bouleversement. Une structure trop rigide éclate, une vérité sort. Le choc est réel, mais il libère ce qui étouffait.",
  rev:"Retournée, La Maison Dieu parle d'un changement que tu retardes. Les fissures sont là, tu fais semblant de ne pas les voir. Mieux vaut agir que subir.",
  noyau:["un bouleversement qui libère","des fissures que tu refuses de voir"],
  amour:["En amour, une crise éclate, une vérité sort. Après l'orage, la relation repart sur du vrai, ou s'arrête.","En amour, des tensions couvent. Parlez avant que tout explose."],
  travail:["Côté travail, un changement brutal : réorganisation, départ, projet remis à plat. Une porte se ferme, une autre s'ouvre.","Côté travail, tu sens que ça va craquer. Prépare ton plan B."],
  argent:["Pour l'argent, une dépense imprévue ou une remise en question de ta façon de gérer.","Pour l'argent, des risques ignorés. Vérifie tes assurances et ton épargne."],
  conseil:["Laisse tomber ce qui doit tomber.","Répare ou pars, mais n'attends pas l'effondrement."] },

{ id:"etoile", n:17, nom:"L'Étoile",
  mots:["Espoir","Inspiration","Confiance"],
  symb:"Une femme verse deux cruches sous un ciel étoilé : elle donne sans compter.",
  up:"L'Étoile apporte l'espoir et la protection. Tu es à ta place, tu peux avoir confiance en l'avenir. Tes rêves sont à portée de main si tu les arroses.",
  rev:"Retournée, L'Étoile parle de découragement ou d'illusions. Tu doutes de toi, ou tu attends un miracle. Reviens à ce qui t'inspire vraiment.",
  noyau:["un espoir sincère et une confiance retrouvée","un découragement et des rêves un peu flous"],
  amour:["En amour, une relation sincère et lumineuse, ou une rencontre qui redonne foi en l'amour.","En amour, idéalisation ou déception. Regarde la personne telle qu'elle est."],
  travail:["Côté travail, inspiration et reconnaissance. Les projets artistiques ou humains sont favorisés.","Côté travail, manque de motivation. Retrouve le sens de ce que tu fais."],
  argent:["Pour l'argent, la situation s'éclaircit et un coup de pouce arrive.","Pour l'argent, des espoirs de gains irréalistes. Garde les pieds sur terre."],
  conseil:["Crois en toi et donne sans compter.","Rallume ce qui t'inspire."] },

{ id:"lune", n:18, nom:"La Lune",
  mots:["Intuition","Rêve","Incertitude"],
  symb:"La lune pleure sur deux chiens qui hurlent et une écrevisse : tout est flou, tout est sensible.",
  up:"La Lune réveille l'intuition et l'imaginaire. Tout n'est pas clair, mais tes ressentis sont justes. Fie-toi à ton instinct et à tes rêves.",
  rev:"Retournée, La Lune parle de confusion, d'angoisses ou de mensonges. Ce que tu crois voir n'est peut-être pas la réalité. Attends que le brouillard se lève.",
  noyau:["une intuition forte et un monde sensible","une confusion et des peurs qui déforment tout"],
  amour:["En amour, des émotions intenses et un besoin de tendresse. Écoute ce que tu ressens.","En amour, doutes, jalousie, non-dits. Ne te fie pas aux suppositions."],
  travail:["Côté travail, métiers créatifs, intuition qui guide les bonnes décisions.","Côté travail, un flou sur ton rôle ou sur les intentions de quelqu'un. Demande des précisions."],
  argent:["Pour l'argent, avance avec ton instinct, mais sans parier.","Pour l'argent, risque d'arnaque ou d'erreur. Ne signe rien que tu ne comprends pas."],
  conseil:["Écoute ton intuition.","Attends d'y voir clair avant d'agir."] },

{ id:"soleil", n:19, nom:"Le Soleil",
  mots:["Joie","Réussite","Clarté"],
  symb:"Deux enfants jouent sous un grand soleil : la chaleur, la joie, la fraternité.",
  up:"Le Soleil est l'une des plus belles cartes du jeu. Réussite, joie, clarté : ce que tu entreprends rayonne, et les relations sont chaleureuses.",
  rev:"Retourné, Le Soleil brille un peu moins fort, mais il brille. Petite fatigue, orgueil ou excès d'optimisme : la réussite est là, avec un peu plus de modestie.",
  noyau:["une réussite lumineuse et une vraie joie","une joie voilée et un petit excès de confiance"],
  amour:["En amour, bonheur partagé, complicité, relation épanouie. Tout est simple.","En amour, un nuage passager. Un peu d'écoute et la chaleur revient."],
  travail:["Côté travail, succès, reconnaissance, travail d'équipe réussi. Tu es dans la lumière.","Côté travail, une réussite retardée ou partagée. Laisse de la place aux autres."],
  argent:["Pour l'argent, une période faste. Les projets rapportent.","Pour l'argent, ça va bien, mais ne dépense pas comme si ça devait durer toujours."],
  conseil:["Profite, partage, rayonne.","Reste simple, la lumière fera le reste."] },

{ id:"jugement", n:20, nom:"Le Jugement",
  mots:["Appel","Renaissance","Réveil"],
  symb:"Un ange souffle dans sa trompette, un être sort de terre : c'est l'appel du réveil.",
  up:"Le Jugement annonce un réveil. Une nouvelle, un appel, une prise de conscience : ce que tu attendais se manifeste, et c'est le moment d'y répondre.",
  rev:"Retourné, Le Jugement parle d'un appel que tu n'entends pas, ou d'un jugement trop dur sur toi-même. Arrête de ressasser le passé.",
  noyau:["un appel à renaître et une bonne nouvelle","un appel manqué et un passé qui pèse"],
  amour:["En amour, retour d'une personne, déclaration, relation qui renaît plus forte.","En amour, regrets ou rancune. Pardonner, ou te pardonner, ouvre une porte."],
  travail:["Côté travail, une réponse positive, une vocation qui se révèle, un examen réussi.","Côté travail, une réponse qui tarde. Relance."],
  argent:["Pour l'argent, une rentrée attendue arrive enfin.","Pour l'argent, un vieux problème revient. Règle-le une bonne fois."],
  conseil:["Réponds à l'appel.","Pardonne-toi et avance."] },

{ id:"monde", n:21, nom:"Le Monde",
  mots:["Accomplissement","Plénitude","Ouverture"],
  symb:"Une femme danse au centre d'une couronne, entourée des quatre éléments : tout est accompli.",
  up:"Le Monde est la carte de l'accomplissement. Un cycle se termine en beauté, tu récoltes le fruit de tes efforts. Le monde s'ouvre à toi, y compris au loin.",
  rev:"Retourné, Le Monde parle d'une réussite incomplète. Il manque une étape, un détail ou un peu de confiance pour boucler la boucle.",
  noyau:["un accomplissement et une ouverture sur le monde","une réussite presque complète, à laquelle il manque une étape"],
  amour:["En amour, plénitude, relation accomplie, engagement heureux.","En amour, la relation stagne juste avant une étape importante."],
  travail:["Côté travail, succès total, projet abouti, ouverture à l'international.","Côté travail, un projet presque fini qu'il faut vraiment terminer."],
  argent:["Pour l'argent, abondance et sécurité. Un voyage est possible.","Pour l'argent, l'objectif est presque atteint. Encore un effort."],
  conseil:["Savoure ce que tu as accompli.","Termine ce que tu as commencé."] }
];

/* Phrases de position et introductions : voir phrases.js */
const FRAMES = {};
const INTROS = {};

/* Combinaisons fortes, lues quand les deux lames sortent ensemble */
const COMBOS = [
  ["amoureux","diable","L'Amoureux et Le Diable ensemble : une attirance très forte, où le désir peut prendre le pas sur le choix libre. Demande-toi si c'est toi qui choisis."],
  ["soleil","lune","Le Soleil et La Lune : la clarté rencontre le doute. Ce qui semble flou va s'éclaircir, garde confiance."],
  ["maisondieu","etoile","La Maison Dieu et L'Étoile : après le choc, l'espoir. Ce qui s'effondre laisse la place à quelque chose de plus vrai."],
  ["sansnom","jugement","L'Arcane sans nom et Le Jugement : une fin qui prépare une vraie renaissance. Tu changes en profondeur."],
  ["roue","mat","La Roue de Fortune et Le Mat : le changement arrive vite et sans prévenir. Laisse-toi porter, en gardant un œil sur la route."],
  ["empereur","imperatrice","L'Empereur et L'Impératrice : l'alliance de la structure et de la créativité. Un duo, un couple ou un projet très porteur."],
  ["pape","papesse","Le Pape et La Papesse : le savoir et la transmission. Formation, études, conseils précieux."],
  ["bateleur","monde","Le Bateleur et Le Monde : du premier pas à la réussite complète. Ce que tu lances maintenant peut aller très loin."],
  ["justice","diable","La Justice et Le Diable : une question d'argent, de contrat ou de pouvoir à régler honnêtement."],
  ["chariot","pendu","Le Chariot et Le Pendu : l'envie de foncer, mais les circonstances imposent d'attendre. Prépare-toi pendant la pause."],
  ["ermite","etoile","L'Ermite et L'Étoile : le temps passé seul devient source d'inspiration. Ton chemin intérieur porte ses fruits."],
  ["force","diable","La Force et Le Diable : tu as de quoi dompter tes envies et tes peurs. Tu restes aux commandes."],
  ["temperance","maisondieu","Tempérance et La Maison Dieu : les tensions peuvent s'apaiser avant que tout casse. Choisis le dialogue."],
  ["soleil","monde","Le Soleil et Le Monde : une très belle réussite, joyeuse et complète."]
];

/* ===== Significations longues et chemin initiatique =====
   Synthèse originale inspirée de deux traditions :
   - le Tarot de Marseille lu par sa structure (numérologie des deux séries, regards, couleurs), dans l'esprit du travail de restauration Jodorowsky-Camoin ;
   - la tradition de la Golden Dawn reprise par le Waite-Smith (lettres hébraïques, correspondances astrologiques, 22 sentiers de l'Arbre de Vie). */

const SEPH = {kether:"Kether, la Couronne", chokmah:"Chokmah, la Sagesse", binah:"Binah, la Compréhension", chesed:"Chesed, la Clémence", geburah:"Geburah, la Rigueur", tiphareth:"Tiphareth, la Beauté", netzach:"Netzach, la Victoire", hod:"Hod, la Splendeur", yesod:"Yesod, le Fondement", malkuth:"Malkuth, le Royaume"};

const DEGRES = {1:"Le potentiel, le commencement",2:"L'accumulation, la gestation",3:"L'explosion, la création",4:"La stabilité, la construction",5:"Le pont, le nouvel idéal",6:"Le plaisir, la beauté, le choix",7:"L'action dans le monde",8:"La perfection, l'équilibre",9:"La crise, la sagesse, le passage",10:"La fin d'un cycle"};

const LORE = {
mat:{ gd:{l:"א",n:"Aleph",s:"le bœuf",a:"l'Air",p:11,de:"kether",to:"chokmah"},
  sens:["Le Mat est la seule lame sans numéro. Il n'est ni le début ni la fin du jeu : il est l'énergie qui traverse toutes les autres. Il marche vers la droite de la carte, c'est-à-dire, dans la lecture du Marseille, vers l'avenir et vers l'action. Son baluchon contient tout ce qu'il possède, sa canne le relie au sol, et l'animal qui griffe sa cuisse rappelle que l'instinct le suit partout.",
        "Il représente la liberté totale, l'élan vital à l'état brut, la folie au sens noble : celle qui ose sortir du cadre. Il peut aussi être l'errance, la fuite ou l'inconscience. Dans la tradition de la Golden Dawn, il porte la lettre Aleph, première de l'alphabet hébreu, souffle silencieux qui précède toute parole, et l'élément Air. Il trace le sentier le plus haut de l'Arbre de Vie, juste sous la Couronne. Tiré dans un jeu, il annonce un départ, un saut dans l'inconnu, ou une énergie qui demande à circuler."],
  chemin:"Le Mat, c'est toi au seuil du voyage. Tu as quitté la maison avec presque rien, le regard tourné vers le monde qui t'attend. Tu ne sais pas encore qui tu es : tu sais seulement que tu dois avancer. Chaque arcane que tu vas croiser est une porte, et chaque porte va te transformer. Tu porteras leurs visages tour à tour, jusqu'à danser au centre du Monde.",
  symboles:["Il marche vers la droite : il va vers l'avenir et l'action.","Le baluchon : tout ce qu'il possède tient dans un sac, son passé est léger.","La canne rouge : l'énergie qui le guide et le relie au sol.","L'animal qui le griffe : l'instinct, ou ce qui le pousse à avancer.","Le bonnet à grelots : le fou du roi, libre de dire ce que les autres taisent."] },

bateleur:{ gd:{l:"ב",n:"Beth",s:"la maison",a:"Mercure",p:12,de:"kether",to:"binah"},
  sens:["Le Bateleur est le premier pas. Debout derrière sa table, il a devant lui tout ce qu'il faut pour commencer : gobelets, dés, couteau, pièces, bâton. Ce sont les outils des quatre éléments, que l'on retrouve dans les petits arcanes. Il n'a encore rien construit, mais tout est possible. Sa table n'a que trois pieds visibles : le quatrième est hors de la carte, comme si une partie de sa force restait encore à découvrir. Son large chapeau dessine une boucle, signe d'une énergie qui tourne et se renouvelle.",
        "Il incarne le talent, l'initiative, l'habileté, la capacité à choisir et à agir, mais aussi le débutant qui improvise et parfois le beau parleur. Pour la Golden Dawn, il devient le Magicien : lettre Beth, la maison, et planète Mercure, la communication, la ruse, le mouvement de la pensée. Tiré dans un jeu, il dit : commence, avec ce que tu as."],
  chemin:"Premier pas : tu poses ton baluchon sur une table et tu l'ouvres. Le Mat devient Bateleur. Tu découvres que tu n'es pas venu les mains vides : tu as des talents, des idées, de la ruse. Tu ne sais pas encore t'en servir, alors tu essaies, tu joues, tu te trompes. Ton bâton levé relie le ciel à la table : tu apprends que l'intention peut devenir action. C'est le temps de l'apprenti, plein d'enthousiasme et de maladresse.",
  symboles:["La table à trois pieds visibles : le quatrième reste invisible, une part de ton potentiel est encore cachée.","Les objets posés : les quatre éléments prêts à servir.","Le bâton levé et la pièce tenue : il relie l'idée et la matière.","Le chapeau en boucle : une énergie qui circule sans fin.","La petite pousse verte entre ses pieds : quelque chose commence à germer."] },

papesse:{ gd:{l:"ג",n:"Gimel",s:"le chameau",a:"la Lune",p:13,de:"kether",to:"tiphareth"},
  sens:["La Papesse est la gardienne du savoir. Assise, enveloppée d'un grand manteau, elle tient un livre ouvert sur ses genoux. Elle ne bouge pas, elle accumule. Le deux est le nombre de la gestation : ce qui n'est pas encore né se prépare dans le secret. Le voile clair derrière elle sépare ce qui est montré de ce qui reste caché. On ne voit ni ses pieds ni le sol : elle n'agit pas encore dans le monde.",
        "Elle représente l'étude, la patience, la mémoire, l'intuition silencieuse, la pureté, et parfois la froideur ou le jugement. Pour la Golden Dawn, elle devient la Grande Prêtresse : lettre Gimel, le chameau qui traverse le désert avec ses réserves, et la Lune, qui reflète une lumière reçue. Son sentier traverse l'Abîme, de la Couronne jusqu'au cœur de l'Arbre. Tirée dans un jeu, elle invite à se taire, à observer et à apprendre avant d'agir."],
  chemin:"Deuxième pas : tu t'assois. Après l'agitation du Bateleur, tu découvres le silence. Tu deviens la Papesse. Tu ouvres le livre de ce que d'autres ont su avant toi, et tu apprends à écouter ce qui parle en toi sans faire de bruit. Rien ne se voit encore de l'extérieur, mais tout se prépare. Tu comprends qu'une partie du voyage se fait immobile, et que le savoir mûrit comme un fruit, dans l'ombre.",
  symboles:["Le livre ouvert : le savoir que l'on reçoit et que l'on garde.","La tiare à trois étages : une autorité spirituelle, pas temporelle.","Le voile derrière elle : la frontière entre le visible et l'invisible.","Le manteau qui couvre tout : la réceptivité et le secret.","Ni pieds ni sol : elle n'agit pas encore dans le monde."] },

imperatrice:{ gd:{l:"ד",n:"Daleth",s:"la porte",a:"Vénus",p:14,de:"chokmah",to:"binah"},
  sens:["L'Impératrice est l'explosion créatrice. Après l'accumulation de la Papesse, le trois fait jaillir ce qui était contenu : idées, désirs, paroles, beauté. Elle est assise de face, couronnée, adossée à un trône dont le dossier ressemble à des ailes. Elle tient son sceptre contre l'épaule et garde près d'elle un bouclier orné d'un aigle : l'intelligence qui s'élève et protège ce qu'elle crée.",
        "Elle représente la fécondité au sens large, la séduction, l'expression, l'abondance, la nature qui pousse sans se retenir. Le revers de cette force, c'est l'excès, la dispersion, le besoin de plaire. Pour la Golden Dawn, elle porte la lettre Daleth, la porte, et Vénus, l'amour et l'harmonie. Son sentier relie la Sagesse et la Compréhension : là où l'idée prend forme. Tirée dans un jeu, elle annonce un temps de création et d'épanouissement."],
  chemin:"Troisième pas : ce que tu as appris éclate en toi. Tu deviens l'Impératrice. Tu oses enfin parler, créer, séduire, montrer ce que tu portes. C'est une adolescence de l'âme : tout pousse en même temps, parfois dans le désordre. Tu découvres la joie de produire, d'inventer, d'être vu. Tu apprends aussi que la création demande un cadre, sinon elle s'épuise : c'est ce que va t'apporter le pas suivant.",
  symboles:["Le dossier en forme d'ailes : une création qui veut s'envoler.","Le sceptre au globe et à la croix : le pouvoir sur la matière.","Le bouclier à l'aigle : l'intelligence qui protège et prend de la hauteur.","La position de face : elle s'expose, elle se montre.","La couronne : la souveraineté sur son propre territoire intérieur."] },

empereur:{ gd:{l:"ה",n:"Heh",s:"la fenêtre",a:"le Bélier",p:15,de:"chokmah",to:"tiphareth"},
  sens:["L'Empereur est la stabilité. Le quatre est le carré, la table posée sur ses quatre pieds, la maison construite. Barbu, couronné, il se tient de profil, tourné vers la gauche : dans un tirage, il regarde la lame posée avant lui, comme s'il veillait sur ce qui a été semé. Ses jambes croisées dessinent un 4, il s'adosse à son trône plus qu'il ne s'y assoit, prêt à se lever. L'aigle à ses pieds couve son territoire.",
        "Il représente l'autorité, l'ordre, la responsabilité, la protection, le père, la loi, la réussite matérielle. Son ombre, c'est la rigidité et le besoin de tout contrôler. Pour la Golden Dawn, il porte la lettre Heh, la fenêtre, et le signe du Bélier, l'énergie qui fonde et qui commande. Tiré dans un jeu, il dit : construis, organise, assume."],
  chemin:"Quatrième pas : tu poses tes pieds sur la terre. Tu deviens l'Empereur. Ce que l'Impératrice a fait jaillir, tu lui donnes une forme durable : une maison, une règle, un métier, une place. Tu apprends à dire oui et non, à protéger ce qui t'appartient, à porter des responsabilités. Pour la première fois, tu as un territoire. Tu découvres aussi que le pouvoir isole, et qu'il faudra un jour lever les yeux vers quelque chose de plus grand que toi.",
  symboles:["Le profil tourné vers la gauche : il veille sur ce qui a été accompli avant lui.","Les jambes croisées en forme de 4 : la stabilité du carré.","Le sceptre tenu droit : une volonté ferme.","L'aigle au pied du trône : une puissance couvée, qui attend son heure.","Le collier et le médaillon : la responsabilité qu'il porte sur lui."] },

pape:{ gd:{l:"ו",n:"Vav",s:"le clou",a:"le Taureau",p:16,de:"chokmah",to:"chesed"},
  sens:["Le Pape est le pont. Le cinq ouvre une nouvelle dimension : après la stabilité de l'Empereur, il faut un idéal, une direction, un sens. Barbu, coiffé de la tiare, il bénit de sa main levée et tient de l'autre une croix à trois traverses, la main gantée. Deux disciples, vus de dos, se tiennent devant lui : il est le lien entre eux et ce qui les dépasse. Deux colonnes bleues encadrent la scène comme l'entrée d'un temple.",
        "Il représente la transmission, l'enseignement, la foi, les valeurs, le conseil, le mariage, la communication. Son ombre, ce sont les dogmes et les donneurs de leçons. Pour la Golden Dawn, il devient le Hiérophante : lettre Vav, le clou qui relie, et le Taureau, ce qui s'ancre et dure. Tiré dans un jeu, il invite à chercher un guide, ou à le devenir."],
  chemin:"Cinquième pas : tu lèves les yeux. Tu as un territoire, mais il te manque un sens. Tu deviens le Pape. Tu découvres qu'il existe des maîtres, des traditions, des valeurs, et que tu peux les recevoir puis les transmettre. Tu apprends à faire le lien entre ce qui est en haut et ce qui est en bas, entre le ciel de la Papesse et la terre de l'Empereur. Et tu comprends qu'un enseignement ne vaut que s'il est vécu.",
  symboles:["La main qui bénit, deux doigts levés : la parole qui relie.","La croix à trois traverses : trois niveaux, le corps, le cœur, l'esprit.","Le gant marqué d'une croix : une action guidée par l'esprit.","Les deux disciples de dos : nous sommes à leur place, face à l'enseignement.","Les deux colonnes bleues : l'entrée d'un lieu sacré."] },

amoureux:{ gd:{l:"ז",n:"Zayin",s:"l'épée",a:"les Gémeaux",p:17,de:"binah",to:"tiphareth"},
  sens:["L'Amoureux est la lame du choix et du plaisir. Le six est le premier pas vers la beauté : on ne fait plus seulement ce qu'il faut, on cherche ce que l'on aime. Au centre, un jeune homme pieds nus se tient entre deux femmes. Il en désigne une de la main tout en regardant l'autre : son geste et son regard ne vont pas dans la même direction. Au-dessus, un ange dans un soleil blanc tend son arc.",
        "Cette lame parle d'union, de relation, d'émotion, de vie sociale, et surtout d'une question : que veux-tu vraiment ? Elle représente aussi le conflit entre le devoir et le désir. Pour la Golden Dawn, elle porte la lettre Zayin, l'épée qui tranche, et le signe des Gémeaux, la dualité. Tirée dans un jeu, elle demande de choisir avec le cœur, et d'assumer ce choix."],
  chemin:"Sixième pas : tu rencontres l'autre. Tu deviens l'Amoureux. Après les règles et les maîtres, tu découvres le désir, l'émotion, l'attirance, et avec eux le doute. Plusieurs chemins s'ouvrent devant toi, et tu ne peux pas les prendre tous. Tu apprends que choisir, c'est renoncer, et que le vrai choix ne se fait pas avec la tête mais avec ce qui vibre en toi. La flèche de l'ange t'atteint : tu sais enfin ce que tu aimes.",
  symboles:["Le geste vers une femme, le regard vers l'autre : la tension entre le désir et le devoir.","L'ange dans le soleil blanc : une force supérieure qui choisit parfois à notre place.","Les pieds nus : une situation vécue sans protection, avec sincérité.","La couronne de feuilles et les cheveux libres : deux visages, deux voies.","La flèche : l'élan qui tranche l'hésitation."] },

chariot:{ gd:{l:"ח",n:"Cheth",s:"l'enclos",a:"le Cancer",p:18,de:"binah",to:"geburah"},
  sens:["Le Chariot est l'action dans le monde. Le sept est le nombre le plus actif du jeu : on part conquérir. Un prince couronné se tient debout dans son char, sceptre en main, sous un baldaquin porté par des colonnes. Ses épaules portent deux croissants de lune, deux visages qu'il garde sur lui. Les deux chevaux n'ont pas de rênes : il ne les dirige pas à la main, mais par sa seule volonté, et ils regardent chacun de son côté.",
        "Le Chariot représente le succès, le voyage, la conquête, la confiance en soi, la maîtrise des forces opposées. Son revers, c'est la précipitation ou l'orgueil du vainqueur. Pour la Golden Dawn, il porte la lettre Cheth, l'enclos, et le Cancer, la carapace qui protège. Tiré dans un jeu, il dit : avance, tu tiens la direction."],
  chemin:"Septième pas : tu montes sur ton char et tu pars. Tu deviens le Chariot. Tout ce que tu as appris, tu l'emportes dans le monde. Tu découvres la victoire, le voyage, la reconnaissance. Tu apprends surtout à mener ensemble des forces qui tirent en sens contraire : ta raison et ton cœur, ton ambition et ta peur. Pas besoin de rênes quand tu sais où tu vas. C'est le sommet de la première moitié du voyage.",
  symboles:["Les deux chevaux sans rênes, tournés chacun de son côté : des forces contraires guidées par la volonté.","Les croissants sur les épaules : deux humeurs que le héros assume.","Le baldaquin : il emporte sa maison avec lui.","Le sceptre : il agit au nom de ce qu'il croit.","L'écusson sur la caisse : son identité, qu'il affiche au monde."] },

justice:{ gd:{l:"ל",n:"Lamed",s:"l'aiguillon",a:"la Balance",p:22,de:"geburah",to:"tiphareth"},
  sens:["La Justice est l'équilibre parfait. Le huit est le nombre de la perfection : rien n'est à ajouter, rien n'est à retirer. Elle est assise de face et regarde droit vers toi : on ne peut pas tricher avec elle. Dans une main, la balance pèse ; dans l'autre, l'épée dressée tranche. Un disque brille au centre de sa couronne : une pensée claire, centrée.",
        "Elle représente la vérité, la décision juste, la loi, les contrats, la responsabilité, et ce juste retour des choses que certains appellent karma. Elle pose aussi une question intime : est-ce que je me donne ce que je mérite ? Dans le Waite-Smith, la Golden Dawn l'a placée au numéro 11 et a donné le 8 à la Force, pour suivre l'ordre du zodiaque. Elle porte la lettre Lamed, l'aiguillon qui fait avancer, et le signe de la Balance. Tirée dans un jeu, elle demande de peser, puis de trancher."],
  chemin:"Huitième pas : après la course du Chariot, tu t'arrêtes pour faire les comptes. Tu deviens la Justice. Tu regardes ta vie en face, sans te mentir. Tu pèses ce que tu as donné et ce que tu as reçu, tu tranches ce qui est en trop. Tu apprends que la perfection n'est pas de tout avoir, mais d'avoir ce qui est juste. Et tu découvres que la juge la plus sévère, souvent, c'est toi.",
  symboles:["Le regard droit vers toi : la vérité ne se contourne pas.","La balance à plateaux égaux : l'équilibre entre donner et recevoir.","L'épée dressée pointe en haut : la décision qui tranche.","Le disque sur la couronne : une pensée claire.","Les deux montants derrière elle : le cadre de la loi."] },

ermite:{ gd:{l:"י",n:"Yod",s:"la main",a:"la Vierge",p:20,de:"chesed",to:"tiphareth"},
  sens:["L'Ermite est la crise qui rend sage. Le neuf termine presque le cycle : on a tout vécu, et il faut maintenant lâcher pour passer à autre chose. Le vieil homme marche vers la gauche de la carte, vers le passé, comme s'il reculait pour mieux voir. Il lève une lanterne à hauteur du visage, appuyé sur un bâton. Son grand manteau bleu, qui laisse voir le rouge et le vert dessous, cache une lumière intérieure.",
        "Il représente la solitude choisie, la recherche, la prudence, l'expérience, l'enseignement discret, le temps long. Son revers, c'est l'isolement subi et le repli sur soi. Pour la Golden Dawn, il porte la lettre Yod, la main, première étincelle du Nom divin, et le signe de la Vierge, l'analyse et le soin. Tiré dans un jeu, il invite à prendre du recul et à avancer pas à pas, à la lumière de ce que l'on sait."],
  chemin:"Neuvième pas : tu quittes la foule. Tu deviens l'Ermite. Après avoir conquis et jugé, tu as besoin de silence pour comprendre ce que tu as vécu. Tu marches à rebours, vers ton passé, ta lanterne levée. Tu découvres que la lumière que tu cherchais était déjà dans ta main. Tu apprends à éclairer le chemin pour toi, puis pour ceux qui viendront après. C'est la sagesse, celle qui accepte de ne pas tout savoir.",
  symboles:["La marche vers la gauche : il revient sur le passé pour le comprendre.","La lanterne levée : une lumière modeste, juste assez pour le pas suivant.","Le bâton : l'expérience sur laquelle il s'appuie.","Le manteau bleu sur la robe verte et le capuchon rouge : une sagesse calme qui cache un feu.","Le dos voûté : le poids des années devenu force."] },

roue:{ gd:{l:"כ",n:"Kaph",s:"la paume de la main",a:"Jupiter",p:21,de:"chesed",to:"netzach"},
  sens:["La Roue de Fortune ferme le premier cycle. Le dix est une fin et un recommencement. Une roue à six rayons tourne sur un socle posé sur l'eau. À gauche, une créature descend ; à droite, une autre monte ; au sommet, un être couronné et ailé tient une épée et ne bouge pas. La manivelle est libre : personne ne la tient.",
        "La Roue représente les cycles, les hauts et les bas, la chance, les changements que l'on ne contrôle pas. Elle pose une question : qui va tourner la manivelle ? Parfois il faut attendre, parfois demander de l'aide, parfois accepter. Pour la Golden Dawn, elle porte la lettre Kaph, la paume de la main, et Jupiter, la chance et l'expansion. Tirée dans un jeu, elle annonce que les choses bougent, et qu'un cycle se termine."],
  chemin:"Dixième pas : tu vois la roue. Tu as monté, tu as régné, tu as douté. Tu deviens la Roue de Fortune. Tu comprends que tout ce que tu as vécu tourne : la réussite et l'échec, la joie et la peine reviennent par cycles. Tu ne peux pas arrêter la roue, mais tu peux choisir d'en sortir par le centre, là où rien ne bouge. La première moitié du voyage se termine ici : tu as trouvé ta place dans le monde. Il reste à trouver ta place en toi.",
  symboles:["La manivelle que personne ne tient : le monde attend une main, peut-être la tienne.","La créature qui descend et celle qui monte : les hauts et les bas de la fortune.","L'être couronné au sommet, immobile : ce qui reste stable au milieu du mouvement.","Les six rayons : le cycle complet.","Les ondulations bleues sous le socle : la roue repose sur l'inconscient."] },

force:{ gd:{l:"ט",n:"Teth",s:"le serpent",a:"le Lion",p:19,de:"chesed",to:"geburah"},
  sens:["La Force ouvre la deuxième série du jeu. Elle est un nouveau commencement, comme le Bateleur, dont elle porte le même grand chapeau en boucle. Mais cette fois, le travail ne se fait plus dans le monde : il se fait à l'intérieur. Une femme debout pose ses deux mains sur la gueule d'un lion jaune qui semble sortir de sa robe. Elle ne lutte pas, elle accompagne. Ses yeux sont baissés vers la bête.",
        "Elle représente le courage, la maîtrise de soi, l'énergie vitale, la sexualité, la créativité qui monte des profondeurs, et l'alliance entre l'esprit et l'instinct. Dans le Waite-Smith, la Golden Dawn lui a donné le numéro 8 pour suivre l'ordre du zodiaque. Elle porte la lettre Teth, le serpent, et le signe du Lion. Tirée dans un jeu, elle dit : ta force est calme, et elle vient de dedans."],
  chemin:"Onzième pas : tu descends en toi. Tu deviens la Force. Tu rencontres le lion qui vit en toi : tes instincts, ta colère, ton désir, ta vitalité. Tu pourrais le combattre, tu choisis de le comprendre. Tu poses tes mains sur sa gueule, sans peur. Tu découvres que cette énergie brute, une fois apprivoisée, devient ta plus grande ressource. Le voyage intérieur commence, et il commence par la douceur.",
  symboles:["Le chapeau en boucle, le même que celui du Bateleur : un nouveau départ, plus profond.","Les mains sur la gueule du lion : la maîtrise par la douceur.","Le lion qui sort de sa robe : l'instinct fait partie d'elle.","Les yeux baissés : elle regarde ce qui est en bas, ce qui est en dedans.","La robe bleue : la réceptivité qui accueille la force."] },

pendu:{ gd:{l:"מ",n:"Mem",s:"l'eau",a:"l'Eau",p:23,de:"geburah",to:"hod"},
  sens:["Le Pendu est l'arrêt volontaire. Le douze répond au deux de la Papesse : c'est encore une gestation, mais plus profonde. Un homme est suspendu par un pied à une traverse posée entre deux troncs aux branches coupées. Son autre jambe se plie en forme de 4 renversé, ses mains sont cachées dans son dos, et son visage est serein. Il ne se débat pas.",
        "Il représente la pause, le lâcher-prise, le don de soi, la méditation, le point de vue inversé qui fait voir autrement. Son revers, c'est l'impuissance, l'attente subie, le rôle de victime. Pour la Golden Dawn, il porte la lettre Mem, l'eau, élément de l'abandon et de la dissolution. Tiré dans un jeu, il invite à ne plus forcer : la solution viendra en changeant de regard."],
  chemin:"Douzième pas : tu t'arrêtes, la tête en bas. Tu deviens le Pendu. Tout ce que tu croyais savoir se retourne. Tu cesses d'agir, de vouloir, de contrôler. Tes mains sont derrière ton dos : tu n'as plus rien à saisir. Dans cet abandon, tu découvres une paix étrange. Tu vois le monde à l'envers, donc autrement. Tu comprends que certaines réponses ne viennent qu'à celui qui accepte d'attendre.",
  symboles:["La tête en bas : le monde vu à l'envers, une nouvelle perspective.","La jambe repliée en 4 renversé : l'Empereur à l'envers, l'ordre ancien qui s'inverse.","Les mains derrière le dos : il ne saisit plus, il accepte.","Les branches coupées : les tentatives passées, abandonnées.","Le visage serein : l'attente n'est pas une souffrance quand elle est choisie."] },

sansnom:{ gd:{l:"נ",n:"Nun",s:"le poisson",a:"le Scorpion",p:24,de:"tiphareth",to:"netzach"},
  sens:["L'Arcane sans nom est la seule lame du jeu dont le bandeau reste vide : on ne nomme pas ce qui transforme tout. Le treize répond au trois de l'Impératrice : c'est une explosion, mais une explosion qui nettoie. Un squelette couleur chair, tourné vers la droite, vers l'avenir, fauche une terre noire d'où sortent des têtes, des mains, et de jeunes pousses. La couleur chair du squelette rappelle que c'est encore la vie qui travaille.",
        "Il ne représente pas la mort physique, mais la transformation radicale : la fin d'une étape, le deuil, la rupture, la libération de ce qui est mort pour que le vivant repousse. Pour la Golden Dawn, il porte la lettre Nun, le poisson qui vit dans les profondeurs, et le Scorpion, signe de la mort et de la renaissance. Tiré dans un jeu, il annonce un changement profond et nécessaire."],
  chemin:"Treizième pas : tu laisses mourir ce qui doit mourir. Tu deviens l'Arcane sans nom. Après l'attente du Pendu, la transformation éclate. Tu fauches tes vieilles certitudes, tes masques, tes rôles. Tu perds des choses, des gens, des images de toi. C'est violent, et c'est libérateur. Sous la terre noire, de nouvelles pousses sortent déjà. Tu découvres que ce qui reste quand tout est coupé, c'est l'essentiel : ta structure, ce qui ne meurt pas.",
  symboles:["Le bandeau sans nom : ce qui transforme ne se laisse pas nommer.","Le squelette couleur chair : la mort est encore une œuvre de la vie.","Le regard vers la droite : la transformation va vers l'avenir.","La terre noire : le fond, la matière qui se décompose et nourrit.","Les têtes, les mains et les pousses : ce qui tombe et ce qui renaît, ensemble."] },

temperance:{ gd:{l:"ס",n:"Samekh",s:"l'étai",a:"le Sagittaire",p:25,de:"tiphareth",to:"yesod"},
  sens:["Tempérance est la guérison. Le quatorze répond au quatre de l'Empereur : c'est une nouvelle stabilité, mais intérieure, fluide, vivante. Un ange aux ailes claires se tient debout entre deux touffes d'herbe. Il fait passer un liquide d'un vase tenu en haut vers un vase tenu en bas, et le filet semble couler en biais, contre toute logique. Une fleur rouge est posée dans ses cheveux.",
        "Tempérance représente l'harmonie, la circulation, la santé, la réconciliation, la patience, la protection, l'art de doser. Elle parle de l'échange entre l'esprit et le corps, entre soi et les autres. Pour la Golden Dawn, elle porte la lettre Samekh, l'étai qui soutient, et le Sagittaire, la flèche qui vise juste. Son sentier descend du cœur de l'Arbre vers son fondement. Tirée dans un jeu, elle dit : mélange, apaise, laisse circuler."],
  chemin:"Quatorzième pas : après la grande coupe, tu te soignes. Tu deviens Tempérance. Tu apprends à faire circuler ce qui était séparé : le haut et le bas, le chaud et le froid, ce que tu donnes et ce que tu reçois. Tu n'es plus en guerre avec toi-même. Un ange veille, peut-être ton ange gardien, peut-être une part de toi que tu ne connaissais pas. Tu découvres la paix intérieure, et l'énergie qui revient doucement.",
  symboles:["Le filet qui coule en biais : un échange qui défie les lois ordinaires.","Un vase en haut, un vase en bas : l'esprit et la matière qui se nourrissent l'un l'autre.","Les ailes : une protection qui vient d'ailleurs.","La fleur dans les cheveux : la beauté qui repousse après l'épreuve.","Les deux touffes d'herbe : la vie qui reprend autour de lui."] },

diable:{ gd:{l:"ע",n:"Ayin",s:"l'œil",a:"le Capricorne",p:26,de:"tiphareth",to:"hod"},
  sens:["Le Diable est la force de l'inconscient. Le quinze répond au cinq du Pape : c'est aussi un pont, mais il ne mène pas vers le ciel, il mène vers les profondeurs. Une créature aux ailes de chauve-souris et aux bois de cerf, à la fois homme et femme, se dresse sur un socle rouge. Elle lève une main, paume ouverte, et tient de l'autre une torche. Deux diablotins sont attachés à son socle par une corde au cou, une corde lâche dont ils pourraient se libérer.",
        "Le Diable représente le désir, la passion, l'argent, le pouvoir, la créativité brute, mais aussi les attachements, les dépendances, les peurs qui nous tiennent. Pour la Golden Dawn, il porte la lettre Ayin, l'œil, et le Capricorne, l'ambition terrestre. Tiré dans un jeu, il dit : regarde ce qui te tient, et sers-toi de sa force."],
  chemin:"Quinzième pas : tu descends dans ta cave. Tu deviens le Diable. Tu y trouves ce que tu avais caché : tes désirs interdits, ta colère, ta soif de pouvoir, tes peurs, tes dépendances. Tu pourrais les fuir, tu choisis de les regarder en face. Tu découvres que cette ombre contient une énergie immense, et que les cordes qui te liaient sont lâches. Tu peux en sortir quand tu le décides. La lumière se nourrit aussi de ce qui est obscur.",
  symboles:["Les ailes de chauve-souris : une créature de la nuit, de l'inconscient.","Le corps à la fois masculin et féminin : une énergie qui rassemble tout.","La main levée paume ouverte : il montre plus qu'il ne cache.","Les cordes au cou des diablotins : des liens que l'on pourrait défaire.","Le socle rouge : une base de passion et d'énergie brute."] },

maisondieu:{ gd:{l:"פ",n:"Peh",s:"la bouche",a:"Mars",p:27,de:"netzach",to:"hod"},
  sens:["La Maison Dieu est la libération. Le seize répond au six de l'Amoureux : c'est encore une joie, mais une joie qui fait éclater les murs. Une tour de briques sans porte voit sa couronne se soulever sous une flamme venue du ciel. Des boules de couleur pleuvent tout autour, et deux personnages sont projetés au sol : l'un tombe, l'autre est à quatre pattes, les mains au contact de la terre. On peut y voir une chute, ou une sortie enfin possible.",
        "Elle représente le bouleversement, la révélation, la rupture d'une structure trop fermée, l'énergie qui se libère d'un coup, et parfois une grande joie. Pour la Golden Dawn, elle devient la Tour : lettre Peh, la bouche qui parle, et Mars, l'énergie qui frappe. Son sentier traverse l'Arbre de part en part, d'un pilier à l'autre. Tirée dans un jeu, elle annonce un changement soudain qui ouvre ce qui était enfermé."],
  chemin:"Seizième pas : les murs tombent. Tu deviens la Maison Dieu. Après avoir regardé ton ombre, la prison que tu t'étais construite explose. Tes certitudes, tes défenses, ta tour d'orgueil s'ouvrent par le haut. Tu te retrouves au sol, les mains dans la terre, étourdi et vivant. Tu découvres que ce que tu croyais être une catastrophe est une délivrance : il n'y avait pas de porte, il fallait que le toit s'ouvre.",
  symboles:["La tour sans porte : une construction qui enfermait, sans sortie possible.","La couronne qui se soulève : l'esprit qui s'ouvre vers le haut.","La flamme venue du ciel : une énergie extérieure, une révélation.","Les boules de couleur : une pluie d'énergie, presque une fête.","Les deux personnages au sol : la chute, et le retour à la terre."] },

etoile:{ gd:{l:"צ",n:"Tzaddi",s:"l'hameçon",a:"le Verseau",p:28,de:"netzach",to:"yesod"},
  sens:["L'Étoile est la confiance retrouvée. Le dix-sept répond au sept du Chariot : c'est encore une action dans le monde, mais une action qui donne au lieu de conquérir. Une femme nue, un genou à terre, verse deux cruches : l'une dans l'eau, l'autre sur la terre. Elle ne garde rien. Au-dessus d'elle brillent une grande étoile et sept plus petites. Un oiseau noir est posé sur un arbuste.",
        "Nue, elle n'a plus rien à cacher. Elle représente l'espoir, la générosité, la protection, l'inspiration, la beauté simple, le fait de trouver sa place dans l'univers. Pour la Golden Dawn, elle porte la lettre Tzaddi, l'hameçon, et le Verseau, l'idéal et le partage. Tirée dans un jeu, elle dit : tu es à ta place, donne ce que tu as, la vie te le rendra."],
  chemin:"Dix-septième pas : après l'orage, la nuit étoilée. Tu deviens l'Étoile. Tu n'as plus rien à cacher, plus rien à défendre. Tu poses un genou à terre, au bord de l'eau, et tu verses ce que tu portes, sans compter. Tu découvres que tu as ta place dans l'univers, sous les étoiles, comme chaque être vivant. Tu apprends que donner ne t'appauvrit pas : la source coule à travers toi.",
  symboles:["La nudité : plus de masque, plus de rôle, la vérité de l'être.","Les deux cruches versées : elle donne à l'eau et à la terre, à l'esprit et à la matière.","Le genou à terre : l'humilité et le lien direct avec le sol.","La grande étoile et les sept petites : un ordre cosmique qui protège.","L'oiseau noir sur l'arbre : l'esprit qui veille, l'âme prête à s'envoler."] },

lune:{ gd:{l:"ק",n:"Qoph",s:"la nuque",a:"les Poissons",p:29,de:"netzach",to:"malkuth"},
  sens:["La Lune est la réceptivité absolue. Le dix-huit répond au huit de la Justice : c'est encore une perfection, mais nocturne, mouvante, impossible à mesurer. La lune, de profil, tournée vers la gauche, baisse les yeux. Des gouttes montent vers elle. En bas, deux chiens dressés face à face hurlent vers le ciel, entre deux tours. Dans un bassin, une écrevisse remonte des profondeurs.",
        "La Lune représente l'intuition, les rêves, l'imaginaire, le féminin profond, la mère, la poésie, mais aussi les peurs, les illusions et les zones d'ombre. Pour la Golden Dawn, elle porte la lettre Qoph, la nuque, l'arrière de la tête, et les Poissons, la dissolution et la compassion. Son sentier mène au Royaume : c'est la dernière épreuve avant le retour au monde. Tirée dans un jeu, elle invite à se fier à son intuition sans se laisser égarer par ses peurs."],
  chemin:"Dix-huitième pas : la nuit tombe sur ton chemin. Tu deviens la Lune. Tu traverses les zones les plus mystérieuses de toi-même : tes rêves, tes peurs anciennes, tes souvenirs d'enfance. Les chiens hurlent, l'écrevisse remonte du fond. Tu ne peux pas tout comprendre, alors tu ressens. Tu apprends à recevoir sans saisir, à avancer dans le flou en suivant ton instinct. Tu découvres que la nuit a sa propre lumière.",
  symboles:["La lune de profil tournée vers la gauche : elle regarde le passé, la mémoire.","Les gouttes qui montent vers elle : la terre qui offre ce qu'elle a.","Les deux chiens face à face : l'instinct apprivoisé et l'instinct sauvage.","L'écrevisse dans le bassin : ce qui remonte des profondeurs de l'inconscient.","Les deux tours : les portes d'un territoire inconnu."] },

soleil:{ gd:{l:"ר",n:"Resh",s:"la tête",a:"le Soleil",p:30,de:"hod",to:"yesod"},
  sens:["Le Soleil est la lumière consciente. Le dix-neuf répond au neuf de l'Ermite : après la sagesse solitaire, voici la chaleur partagée. Un grand soleil à visage humain regarde droit vers toi et répand ses rayons et ses gouttes. En dessous, deux enfants nus se tiennent devant un petit mur : l'un pose la main sur la nuque de l'autre. Le mur protège sans enfermer.",
        "Le Soleil représente la réussite, la joie, l'amour lucide, l'amitié, la fraternité, une nouvelle construction sur des bases saines. C'est l'une des lames les plus heureuses du jeu. Pour la Golden Dawn, il porte la lettre Resh, la tête, et le Soleil lui-même, centre de toute vie. Tiré dans un jeu, il dit : tout s'éclaire, partage ta lumière."],
  chemin:"Dix-neuvième pas : le jour se lève. Tu deviens le Soleil. Après la nuit de la Lune, tout s'éclaire. Tu te sens vivant, chaleureux, en paix avec toi. Tu rencontres l'autre non plus comme un rival ou un désir, mais comme un frère. Tu construis une vie nouvelle, simple et confiante, comme un enfant. Tu découvres que la joie n'est pas une récompense : c'est l'état naturel d'un être qui ne se cache plus.",
  symboles:["Le visage du soleil, de face : une conscience qui voit tout et ne juge pas.","Les deux enfants : la fraternité, l'autre comme un égal.","La main sur la nuque : l'aide, la protection, la confiance.","Le petit mur : un cadre qui protège sans enfermer.","Les gouttes qui montent : la vie qui répond à la lumière."] },

jugement:{ gd:{l:"ש",n:"Shin",s:"la dent",a:"le Feu",p:31,de:"hod",to:"malkuth"},
  sens:["Le Jugement est l'appel. Le vingt répond au dix de la Roue : un cycle se termine, mais cette fois on ne retombe pas, on s'élève. Un ange sort des nuages et souffle dans une trompette d'où pend une bannière à croix. En bas, un être sort d'une tombe, vu de dos, entre une femme et un homme qui prient.",
        "Il représente la renaissance, la vocation, le désir irrésistible, la nouvelle conscience, la réconciliation, la bonne nouvelle. Il parle aussi de famille : un enfant naît de ses deux parents, et devient lui-même. Pour la Golden Dawn, il porte la lettre Shin, la dent, et l'élément Feu, l'esprit qui purifie. Tiré dans un jeu, il dit : quelque chose t'appelle, réponds."],
  chemin:"Vingtième pas : tu entends l'appel. Tu deviens le Jugement. Une trompette résonne et tu sors de ta tombe, celle de tes vieilles peurs et de tes vieux rôles. Ceux qui t'ont donné la vie sont là, et tu peux enfin leur pardonner, et te pardonner. Tu découvres ta vocation, ce pour quoi tu es là. Ce n'est plus une décision, c'est une évidence. Le dernier pas t'attend.",
  symboles:["L'ange qui sort des nuages : un appel venu d'au-delà de toi.","La trompette et la bannière : une annonce, un réveil.","L'être de dos qui sort de la tombe : nous sommes à sa place, celui qui renaît.","La femme et l'homme qui prient : les parents, le passé réconcilié.","La tombe ouverte : une terre qui libère, pas une prison."] },

monde:{ gd:{l:"ת",n:"Tav",s:"le signe",a:"Saturne",p:32,de:"yesod",to:"malkuth"},
  sens:["Le Monde est la réalisation totale. Le vingt-et-un est le plus haut nombre du jeu : tout est accompli. Une femme nue, à peine drapée, danse au centre d'une couronne ovale de feuilles. Aux quatre coins se tiennent un ange, un aigle, un taureau et un lion : les quatre éléments, les quatre directions du monde. Elle tient une baguette et une petite fiole. Une jambe en appui, l'autre levée, elle est à la fois immobile et en mouvement.",
        "Le Monde représente la réussite complète, l'harmonie, la plénitude, la reconnaissance, le voyage lointain, l'unité retrouvée entre soi et l'univers. Pour la Golden Dawn, il porte la lettre Tav, la dernière de l'alphabet, et Saturne, le temps et la forme. Son sentier est le premier que l'initié emprunte en partant du Royaume, la terre. Tiré dans un jeu, il annonce un accomplissement."],
  chemin:"Vingt-et-unième pas : tu danses au centre. Tu deviens le Monde. Toutes les forces que tu as rencontrées sont autour de toi, en harmonie : l'ange, l'aigle, le taureau, le lion. Tu n'es plus en lutte, tu n'es plus en quête. Tu es à la fois toi-même et une part de tout. Tu découvres que le but du voyage n'était pas d'arriver quelque part, mais de devenir entier.",
  symboles:["La danseuse au centre : l'être accompli, libre de ses mouvements.","La couronne ovale : un œuf cosmique, un monde complet.","Les quatre figures aux coins : les quatre éléments réunis.","La jambe levée : l'équilibre dans le mouvement.","La baguette et la fiole : l'action et la réception, réunies dans les mains d'une seule personne."] }
};

const CHEMIN = {
  intro:["Le Mat, c'est toi. Il se tient au bord du chemin, son baluchon sur l'épaule, et il regarde vers la droite de la carte, vers le monde qui l'attend. Les vingt-et-un arcanes numérotés racontent son voyage. À chaque étape, il endosse un nouveau visage : chaque lame est une transformation de celui ou de celle qui consulte.",
         "Le chemin se lit en deux grandes séries. De I à X, le Mat apprend à vivre dans le monde : il découvre ses talents, construit, aime, agit, juge, puis prend du recul. De XI à XX, il refait le même chemin à l'intérieur de lui : il apprivoise ses instincts, lâche prise, se transforme, guérit, affronte son ombre, se libère, puis renaît. Chaque lame de la deuxième série répond à celle qui se trouve dix rangs plus bas. Le Monde, XXI, réunit tout. Puis le Mat repart, changé. Cette lecture en deux séries est celle d'Alejandro Jodorowsky et Marianne Costa, dans La Voie du Tarot."],
  traditions:[
    {t:"Le Tarot de Marseille", d:"Selon Alejandro Jodorowsky et Marianne Costa, on lit la structure du jeu : la valeur des nombres de 1 à 10, répétée sur deux séries, la direction des regards (vers la gauche, le passé et la réception ; vers la droite, l'avenir et l'action), et les couleurs : la chair pour l'humain, le rouge pour l'action, le bleu pour la réceptivité, le jaune pour l'intelligence et la lumière, le vert pour la vie qui pousse, le noir pour la profondeur."},
    {t:"L'école française et la Golden Dawn", d:"Éliphas Lévi, en 1856, donne à chaque arcane une lettre de l'alphabet hébreu, en commençant par le Bateleur ; Papus et Wirth le suivent. En 1888, la Golden Dawn anglaise décale l'attribution d'un rang. Dans son système, chaque arcane majeur reçoit une lettre de l'alphabet hébreu, un signe, une planète ou un élément, et devient l'un des 22 sentiers qui relient les dix sphères de l'Arbre de Vie. L'initié y voyage du Royaume, la terre, jusqu'à la Couronne. Le voyage se lit donc dans les deux sens : le Mat ouvre le jeu, et il est aussi le dernier sentier avant la Couronne."}
  ],
  series:[
    {from:1,to:10,t:"Première série · I à X",s:"Le chemin dans le monde"},
    {from:11,to:20,t:"Deuxième série · XI à XX",s:"Le chemin intérieur"},
    {from:21,to:21,t:"L'accomplissement · XXI",s:"L'être entier"}
  ],
  retour:["Le voyage est fini, et le Mat reprend la route. Mais ce n'est plus le même Mat. Au début, il partait parce qu'il ne savait pas qui il était. À la fin, il repart parce qu'il le sait. Son baluchon contient maintenant les vingt-et-une expériences du chemin. L'animal qui le griffait est devenu un compagnon. Sa folie n'est plus de l'inconscience : c'est la liberté de celui qui n'a plus besoin de s'accrocher à rien.",
          "Dans la Golden Dawn, l'initié qui a remonté tout l'Arbre arrive au sentier du Mat, juste sous la Couronne : le Fou est à la fois le premier pas et le dernier. La même carte a changé de sens. En fin de voyage, le Mat ne parle plus d'imprudence, mais de sagesse libre : tu peux aller où tu veux, parce que tu sais d'où tu viens."],
  matFin:"Le Mat arrive en fin de tirage : comme à la fin du chemin initiatique, il ne parle plus de fuite mais de liberté conquise. Tu repars plus léger, parce que tu as compris quelque chose."
};

const WS_ROWS = [null,
  {r:1, t:"première rangée, le monde extérieur", s:"ce que la vie, la société et les autres te demandent"},
  {r:2, t:"deuxième rangée, le monde intérieur", s:"ce que tu découvres en te tournant vers toi"},
  {r:3, t:"troisième rangée, l'esprit", s:"ce qui te dépasse, te brise et te libère"}];
const wsRow = n => WS_ROWS[Math.ceil(n / 7)];
function degreOf(n){
  if(DECK_ID === "ws"){
    if(n === 0) return {deg:null, txt:"Le zéro : le Fou est avant toutes les rangées. Il les traverse toutes."};
    const R = wsRow(n), pos = ((n - 1) % 7) + 1;
    return {deg:null, row:R.r, txt:`Arcane ${ROMAN[n]}, ${pos === 1 ? "premier" : pos + "e"} de la ${R.t} : ${R.s}. Rachel Pollack range ainsi les vingt-et-un arcanes numérotés du Waite-Smith en trois rangées de sept.`};
  }
  if(DECK_ID === "sb"){
    if(n === 0) return {deg:null, txt:"Mato porte un zéro gravé, ce qui est rare : dans la plupart des tarots anciens, le fou n'a pas de nombre."};
    return {deg:null, txt:`Atout ${ROMAN[n]} : le numéro est gravé sur la carte en chiffres romains. C'est ce numéro, et lui seul, qui permet de le rapprocher de l'arcane ${ROMAN[n]} du Marseille.`};
  }
  if(DECK_ID === "et"){ const c = CARDS.find(x => x.n === n); return {deg:null, txt: c && ET.maj[c.id] ? ET.maj[c.id].place : ""}; }
  if(n===0) return {deg:null, txt:"Sans nombre : l'énergie originelle, libre, qui traverse tout le jeu."};
  if(n===21) return {deg:null, txt:"Vingt-et-un : la totalité, au-delà des deux séries."};
  const d = n<=10 ? n : n-10;
  const serie = n<=10 ? "première série, dans le monde" : "deuxième série, en dedans";
  return {deg:d, txt:`Degré ${d}, ${serie} : ${DEGRES[d].charAt(0).toLowerCase()+DEGRES[d].slice(1)}.`};
}
function echoOf(n){ if(!deck().echo) return null; if(n>=1 && n<=10) return CARDS.find(c=>c.n===n+10); if(n>=11 && n<=20) return CARDS.find(c=>c.n===n-10); return null; }

/* ===== Les lames : Tarot de Marseille de Nicolas Conver (1760), réédition Reality Publishing (2020), photographies Tarot World Project, CC BY-SA 4.0, via Wikimedia Commons ===== */
const K="#1a1714", Y="#efbf3c";
function starPts(cx,cy,r1,r2,n,rot=-90){const p=[];for(let i=0;i<n*2;i++){const r=i%2?r2:r1,a=(rot+i*180/n)*Math.PI/180;p.push((cx+r*Math.cos(a)).toFixed(1)+","+(cy+r*Math.sin(a)).toFixed(1));}return p.join(" ");}
let CARD_AR = 480/945;            /* proportions des lames du Conver */
let CARD_H = Math.round(120/CARD_AR);
document.documentElement.style.setProperty("--card-ar", String(CARD_AR));
const pad2 = n => String(n).padStart(2,"0");
function cardSVG(c){
  const D = typeof PLAY_DECKS !== "undefined" ? PLAY_DECKS[DECK_ID] : null, w = D ? D.w : 480, h = D ? D.h : 945, src = D ? D.src(c.id) : `lames/${pad2(c.n)}.webp`;
  return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${c.nom}" class="lame-img" xmlns="http://www.w3.org/2000/svg"><image href="${src}" x="0" y="0" width="${w}" height="${h}" preserveAspectRatio="xMidYMid slice"/></svg>`;
}
