const DOS_URL = {};
function dosURL(id){
  if(!DOS_SRC[id]) return null;
  if(!DOS_URL[id]){ try{ DOS_URL[id] = URL.createObjectURL(new Blob([DOS_SRC[id]], {type:"image/svg+xml"})); }catch(e){ DOS_URL[id] = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(DOS_SRC[id]); } }
  return DOS_URL[id];
}
function backSVG(){
  const h = CARD_H, u = typeof DECK_ID !== "undefined" ? dosURL(DECK_ID) : null;
  if(u) return `<svg viewBox="0 0 120 ${h}" aria-hidden="true" class="lame-img" xmlns="http://www.w3.org/2000/svg"><image href="${u}" x="0" y="0" width="120" height="${h}" preserveAspectRatio="xMidYMid slice"/></svg>`;
  return `<svg viewBox="0 0 120 ${h}" aria-hidden="true" class="lame-img" xmlns="http://www.w3.org/2000/svg">
  <rect x=".75" y=".75" width="118.5" height="${h-1.5}" rx="5" fill="#e9dcc0" stroke="${K}" stroke-width="1.5"/>
  <rect x="7" y="7" width="106" height="${h-14}" rx="2" fill="url(#arc-back)" stroke="#8a2f22" stroke-width="1.4"/>
  <circle cx="60" cy="${h/2}" r="21" fill="#e9dcc0" stroke="#8a2f22" stroke-width="1.4"/>
  <polygon points="${starPts(60,h/2,14,5.5,8)}" fill="#2f63ad"/>
  <circle cx="60" cy="${h/2}" r="3" fill="#e9dcc0"/>
</svg>`;
}
