/* Arbre de Vie (disposition de la Golden Dawn) : sphères et 22 sentiers */
const TREE_POS = {kether:[50,8],chokmah:[86,26],binah:[14,26],chesed:[86,62],geburah:[14,62],tiphareth:[50,80],netzach:[86,112],hod:[14,112],yesod:[50,130],malkuth:[50,160]};
function treeSVG(activeId){
  const paths = CARDS.map(c => ({id:c.id, ...LORE[c.id].gd}));
  let s = `<svg viewBox="0 0 100 168" class="tree" role="img" aria-label="Arbre de Vie">`;
  paths.forEach(p => { const [x1,y1]=TREE_POS[p.de],[x2,y2]=TREE_POS[p.to]; const on=p.id===activeId; s+=`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" class="${on?"t-on":"t-off"}"/>`; });
  Object.entries(TREE_POS).forEach(([k,[x,y]]) => { const a = LORE[activeId] && (LORE[activeId].gd.de===k || LORE[activeId].gd.to===k); s+=`<circle cx="${x}" cy="${y}" r="6" class="${a?"s-on":"s-off"}"/>`; });
  return s + `</svg>`;
}

