function combosFor(ids){
  const hit = COMBOS.filter(([a,b,,k]) => ids.includes(a) && ids.includes(b) && (k !== "echo" || deck().echo));
  hit.sort((x,y) => (x[3]==="echo"?0:1) - (y[3]==="echo"?0:1));
  return hit.slice(0,5);
}

