const hs = { lame:"mat" };
/* Une rangée d'images avec légendes, puis les crédits de chaque source, sans doublon */
function hcardsHTML(list, h, D, seen = new Set()){
  const credits = [];
  const fig = src => { const m = HIMG[src] || {}; const cap = (h.cap && h.cap[src]) || m.cap || "";
    const dk = m.deck ? DECKS[m.deck] : (m.cr ? null : D);
    const cr = dk ? `${dk.nom}, ${dk.date}. ${dk.credit}` : (m.cr || "");
    if(cr && !seen.has(cr)){ seen.add(cr); credits.push(cr); }
    return `<figure${m.w ? ` class="h-${m.w}"` : ""}>${deckImg(src, cap || (dk ? dk.nom : ""))}${cap ? `<figcaption>${cap}</figcaption>` : ""}</figure>`; };
  const figs = list.map(fig).join("");
  return `<div class="hcards">${figs}</div>${credits.map(c => `<p class="hcredit">${c}</p>`).join("")}`;
}
function deckImg(path, alt, cls=""){ return `<img class="himg ${cls}" src="${path.startsWith("lames/") ? path : "jeux/"+path}.webp" alt="${esc(alt)}" loading="lazy" decoding="async">`; }
function renderHistoire(){
  const root = $("#v-histoire");
  let eraN = 0;
  const tl = HISTORY.map(h => {
    if(h.era) return `<li class="hera" id="hera-${eraN++}"><h2>${h.era}</h2><span>${h.span}</span></li>`;
    const D = h.deck ? DECKS[h.deck] : null, seen = new Set();
    return `<li class="hstep${h.imgs||h.pimgs?"":" textonly"}">
      <div class="hdate"><span>${h.date}</span></div>
      <div class="hbody"><h3>${h.titre}</h3><p class="eyebrow">${h.lieu}</p>${h.p.map(p=>`<p>${p}</p>`).join("")}
        ${h.imgs ? hcardsHTML(h.imgs, h, D, seen) : ""}
        ${h.plus ? `<details class="hmore"><summary>En savoir plus</summary>${h.plus.map(p=>`<p>${p}</p>`).join("")}
          ${h.pimgs ? `${h.plab ? `<p class="hplab">${h.plab}</p>` : ""}${hcardsHTML(h.pimgs, h, D, seen)}` : ""}</details>` : ""}</div></li>`; }).join("");
  const eras = HISTORY.filter(h => h.era), short = ["Origines italiennes","Les cartiers","Le tarot divinatoire","XXe siècle"];
  const toc = [...eras.map((e,i) => [`hera-${i}`, short[i] || e.era]), ["hfaq","Les questions"],["hfam","Les familles"],["hcomp","Une lame"],["hpeople","Les personnages"],["hcult","La culture"],["hreads","Pour aller plus loin"]];
  root.innerHTML = `<header class="sec-head"><h1>L'histoire du tarot</h1><p>Près de six siècles d'histoire : un jeu de cartes né dans les cours italiennes, devenu en France un jeu populaire, puis un outil de divination et un objet d'art. Les jeux montrés ici sont tous dans le domaine public.</p></header>
    ${stocHTML("Sommaire de l'histoire", toc)}
    <section class="hkey" aria-label="L'essentiel">
      <div><span class="hkey-n">1440</span><span>première mention du tarot, à Florence</span></div>
      <div><span class="hkey-n">3 siècles</span><span>de jeu avant les premières lectures</span></div>
      <div><span class="hkey-n">1760</span><span>le Tarot de Nicolas Conver, celui d'Arcanes</span></div>
      <div><span class="hkey-n">1909</span><span>le Waite-Smith, le tarot le plus vendu</span></div>
    </section>
    <ol class="htl" id="htl">${tl}</ol>
    <section class="hsec" id="hfaq"><h2 class="lsub">Les questions qu'on se pose</h2><div class="hfaq">${HFAQ.map(([q,a])=>`<details class="hq"><summary>${q}</summary><p>${a}</p></details>`).join("")}</div></section>
    <section class="hsec" id="hfam"><h2 class="lsub">Les grandes familles de jeux</h2><p class="hcomp-intro">Le même jeu a pris des formes très différentes selon les pays et les usages.</p>
      <div class="hfams">${HFAMILIES.map(f=>`<article class="hfam">${f.img ? `<div class="hfam-art">${deckImg(f.img, f.t)}</div>` : ""}<div><h3>${f.t}</h3><p class="eyebrow">${f.d}</p><p>${f.txt}</p></div></article>`).join("")}</div></section>
    <section class="hsec hcomp" id="hcomp"><h2 class="lsub">Une lame à travers les siècles</h2><p class="hcomp-intro">Choisis une lame et suis-la dans six jeux, de la cour de Milan à la Golden Dawn : ce qui change d'une image à l'autre, et pourquoi.</p>
      <div class="hchips" role="group" aria-label="Choisir une lame">${CARDS.map(c=>`<button type="button" class="chip${hs.lame===c.id?" on":""}" data-hl="${c.id}" aria-pressed="${hs.lame===c.id}">${c.n?ROMAN[c.n]:"0"} · ${c.nom}</button>`).join("")}</div>
      <div id="hcomp-body">${compareHTML(hs.lame)}</div></section>
    <section class="hsec" id="hpeople"><h2 class="lsub">Les personnages</h2><div class="hpeople">${HPEOPLE.map(([n,d,t,img])=>`<div class="hperson has-img"><div class="hperson-art">${img ? deckImg(img, n) : `<span class="hmono" aria-hidden="true">${n.split(" ").filter(w=>/^[A-ZÉ]/.test(w)).slice(0,2).map(w=>w[0]).join("")}</span>`}</div><div><h3>${n}</h3><p class="eyebrow">${d}</p><p>${t}</p></div></div>`).join("")}</div>
      <p class="hcredit">Portraits : Court de Gébelin, gravure d'après André Pujos (1784) ; Etteilla, gravure de 1790 ; Éliphas Lévi par Charles Revel (1874) ; Papus, portrait attribué à Louis-Isidore Journot (1897) ; Pamela Colman Smith, photographie parue dans The Craftsman (1912) ; Arthur Edward Waite par J. Russell and Sons (1911) ; Aleister Crowley par Arnold Genthe (1919) ; Frieda Harris, photographie anonyme (vers 1900) : domaine public. Oswald Wirth : photographie anonyme, CC BY-SA 3.0. Michael Dummett : Klaus Reisinger, CC BY-SA 4.0. Alejandro Jodorowsky en 2024 : ManoSolo13241324, CC0. Via Wikimedia Commons.</p></section>
    ${cultureHTML()}
    <section class="hsec" id="hreads"><h2 class="lsub">Pour aller plus loin</h2><ul class="hreads">${HREADS.map(([t,d,x,u,l])=>`<li><strong>${t}</strong> <span class="eyebrow">${d}</span><p>${x}</p>${u ? `<p><a class="hlink" href="${u}" target="_blank" rel="noopener">${l} ↗</a></p>` : l ? `<p class="help">${l}</p>` : ""}</li>`).join("")}</ul>
      <p class="help">Dates et faits vérifiés auprès de sources historiques, notamment les travaux de Michael Dummett et Thierry Depaulis. Si tu repères une erreur, elle sera corrigée.</p></section>`;
  bindHistoire();
}
function compareHTML(id){
  const k = byId(id);
  const col = (deck, src, name) => { const D = DECKS[deck];
    return `<figure class="hcol">${src ? deckImg(src, name) : `<div class="hmissing">Carte perdue</div>`}<figcaption><strong>${name}</strong><span>${D.nom} · ${D.date}</span></figcaption></figure>`; };
  const v = DECK_NAMES.visconti[id];
  return `<div class="hrow">
      ${col("visconti", v ? "visconti/"+id : null, v || (id==="diable" ? "Le Diable" : "La Tour"))}
      ${col("vieville", "vieville/"+id, DECK_NAMES.vieville[id])}
      ${col("conver", "lames/"+pad2(BASE_N[id]), baseNom(id))}
      ${col("wirth", "wirth/"+id, DECK_NAMES.wirth[id])}
      ${col("rws", "rws/"+id, DECK_NAMES.rws[id])}
    </div>
    ${v ? "" : `<p class="help">Le Diable et la Tour du jeu Visconti-Sforza n'ont jamais été retrouvés.</p>`}
    <div class="hnote"><h3>Du Marseille au Waite-Smith</h3><p>${RWS_NOTE[id]}</p><p><button type="button" class="linkbtn" data-sheet="${id}">Ouvrir la fiche ${k.nom}</button></p></div>`;
}
function bindHistoire(){
  const root = $("#v-histoire");
  root.querySelectorAll("[data-hl]").forEach(b => b.onclick = () => { hs.lame = b.dataset.hl;
    root.querySelectorAll("[data-hl]").forEach(x => { const on = x.dataset.hl===hs.lame; x.classList.toggle("on", on); x.setAttribute("aria-pressed", on); });
    $("#hcomp-body").innerHTML = compareHTML(hs.lame); bindSheetLinks($("#hcomp-body")); });
  bindStoc(root);
  bindSheetLinks(root); applyGloss(root);
}
function bindSheetLinks(el){ el.querySelectorAll("[data-sheet]").forEach(b => b.onclick = () => openSheet(b.dataset.sheet)); }

/* ===== Le tarot dans la culture : chaque œuvre, sa structure et ce qu'elle doit au tarot =====
   img : une image libre de droits (œuvre du domaine public, jeu historique ou portrait sous licence libre).
   Les œuvres encore protégées ne sont pas reproduites : on les évoque par les lames qu'elles mettent en jeu,
   et un lien mène vers une page où l'on peut les voir. */
const CULT_CATS = {bd:"Bande dessinée et manga", litt:"Littérature", art:"Peinture et sculpture", cine:"Cinéma", jeux:"Jeux vidéo", scene:"Musique et scène"};
const CULTURE = [
  {id:"jojo", cat:"bd", titre:"JoJo's Bizarre Adventure : Stardust Crusaders", qui:"Hirohiko Araki", date:"1989–1992", lames:["etoile","mat","monde"],
   img:{f:"hist/araki", cap:"Hirohiko Araki, l'auteur, en 2013", cr:"Photographie monoprixgourmet, CC BY 2.0, via Wikimedia Commons."},
   link:["https://fr.wikipedia.org/wiki/Stardust_Crusaders","Stardust Crusaders sur Wikipédia"],
   resume:"Le manga où le tarot structure tout le récit : les vingt-deux pouvoirs des personnages portent les noms des vingt-deux arcanes, du premier allié jusqu'au dernier adversaire, DIO, dont le Stand s'appelle The World, Le Monde.",
   parts:[
    ["L'œuvre","Troisième partie de la saga JoJo, publiée dans le Weekly Shōnen Jump puis adaptée en anime en 2014. En 1987, le lycéen Jotaro Kujo découvre qu'il possède un « Stand », un double invisible doté de pouvoirs. Avec son grand-père Joseph Joestar et quatre compagnons, il traverse l'Asie jusqu'au Caire en cinquante jours pour vaincre DIO, dont le réveil menace la vie de sa mère. Araki a voulu en faire un road movie, inspiré du Tour du monde en quatre-vingts jours."],
    ["Le tarot comme système","Dans le manga, c'est Mohammed Avdol, diseur de bonne aventure au Caire, qui nomme le pouvoir de Jotaro en tirant une carte : L'Étoile, d'où Star Platinum. À partir de là, chaque Stand de l'aventure porte le nom d'un arcane majeur, et les vingt-deux y passent.","Chez les héros : Star Platinum (L'Étoile) pour Jotaro, Magician's Red (Le Bateleur) pour Avdol, Hermit Purple (L'Ermite) pour Joseph, Hierophant Green (Le Pape) pour Kakyoin, Silver Chariot (Le Chariot) pour Polnareff, et The Fool (Le Mat) pour Iggy, le chien. Chez les ennemis : La Maison Dieu, La Lune, La Force, L'Empereur, L'Impératrice, La Papesse, L'Amoureux, La Justice, La Roue de Fortune, Le Pendu, L'Arcane sans nom (Death 13), Tempérance, Le Diable, Le Soleil, Le Jugement… et enfin The World, Le Monde, pour DIO."],
    ["Un voyage du Mat jusqu'au Monde","La structure suit l'ordre symbolique du jeu. Le Mat, Iggy, rejoint le groupe tard, à l'entrée de l'Égypte : le voyageur sans attache entre dans le dernier tiers du chemin. Le Monde, XXI, l'arcane de la totalité, est réservé à l'adversaire final.","Le pouvoir de The World est d'arrêter le temps. Dans le tarot, Le Monde montre une figure qui danse au centre d'une couronne, entourée des quatre éléments : le point immobile autour duquel tout tourne, hors du temps. Le combat final révèle que Star Platinum peut, lui aussi, arrêter le temps : L'Étoile (XVII), l'espoir qui guide, rejoint Le Monde (XXI). Le héros n'atteint la totalité qu'en traversant toute la suite des arcanes."],
    ["Vers l'Égypte du mythe","Une fois les vingt-deux arcanes épuisés, les derniers ennemis portent les noms des neuf dieux de l'Égypte. Le voyage mène donc, littéralement, du tarot à l'Égypte : celle que Court de Gébelin, en 1781, imaginait comme l'origine des cartes. On ne sait pas si Araki y pensait, mais le parcours rejoue à sa façon le grand mythe de l'occultisme.","Autre écho : Death 13, le Stand de l'Arcane sans nom, attaque ses victimes dans leurs rêves, là où l'on ne contrôle plus rien. La lame XIII y devient la peur de ce qui se passe quand la conscience s'éteint."]
   ]},
  {id:"incal", cat:"bd", titre:"L'Incal", qui:"Alejandro Jodorowsky et Moebius", date:"1980–1988", lames:["mat","soleil","lune","monde"],
   img:{f:"hist/moebius", cap:"Moebius (Jean Giraud), le dessinateur, en 2008", cr:"Photographie Jarek Obważanek (WRAK.PL), CC BY-SA 4.0, via Wikimedia Commons."},
   link:["https://fr.wikipedia.org/wiki/L%27Incal","L'Incal sur Wikipédia"],
   resume:"Le chef-d'œuvre de la science-fiction en bande dessinée est un voyage initiatique écrit par le plus célèbre lecteur du Marseille. Son héros, John Difool, est Le Mat ; son enfant, Solune, unit le Soleil et la Lune.",
   parts:[
    ["L'œuvre","Publié dans Métal hurlant entre 1980 et 1988, dessiné par Moebius (Jean Giraud), L'Incal suit John Difool, détective privé de classe R, lâche, menteur et attachant, qui se retrouve porteur de l'Incal, un cristal de lumière pure convoité par tout l'univers. Autour de lui se forme une troupe improbable : Deepo, la mouette de béton, l'Animah, le Méta-Baron, Tanatah, Kill Tête-de-Chien et l'enfant Solune. Jodorowsky a raconté qu'il n'avait pas de scénario écrit : il mimait les scènes devant Moebius, qui les dessinait. La série est souvent citée parmi les plus grandes bandes dessinées de l'histoire."],
    ["John Difool, Le Mat","Le nom dit tout : Difool, c'est « the Fool », Le Mat. Comme lui, John avance sans savoir où il va, refuse le rôle de héros, voudrait seulement retrouver ses petits plaisirs. Et comme Le Mat, il est le zéro qui peut devenir tout : c'est l'homme le plus ordinaire que l'Incal choisit pour sauver l'univers. Le récit est l'initiation d'un homme qui ne voulait pas être initié."],
    ["Solune, le Soleil et la Lune","Le nom de Solune réunit soleil et lune. Fils de l'Animah et de John, élevé par le Méta-Baron, Solune est destiné à devenir un être aux deux sexes qui guidera l'univers. C'est l'androgyne des alchimistes, le Rebis, l'union des contraires que le tarot place aux lames XVIII et XIX, puis au Monde, dont la figure dansante est souvent lue comme androgyne. L'Incal lui-même existe en deux moitiés, l'Incal Lumière et l'Incal Ténèbre, qui doivent se réunir."],
    ["Les quatre John Difool","Dans Final Incal (2008), dessiné par José Ladrönn, John rencontre trois doubles de lui-même : un John beau et lisse, un vieillard mystique et un ange androgyne. Les quatre doivent découvrir lequel est le vrai, celui qui pourra sauver le monde.","Une lecture s'impose à qui connaît La Voie du Tarot : Jodorowsky y décrit l'être humain comme quatre centres, l'intellect (les Épées), le cœur (les Coupes), l'énergie sexuelle et créatrice (les Bâtons) et le corps (les Deniers), qui doivent s'accorder pour former un être entier. Les quatre John sont quatre visages d'un même homme divisé, et leur réunion rejoue Le Monde : une figure au centre, entourée des quatre éléments. Jodorowsky ne donne pas lui-même cette clé dans l'album : c'est une lecture, mais elle découle directement de sa façon de lire les cartes."]
   ]},
  {id:"promethea", cat:"bd", titre:"Promethea", qui:"Alan Moore et J. H. Williams III", date:"1999–2005", lames:["monde","mat","bateleur"],
   img:{f:"hist/amoore", cap:"Alan Moore, le scénariste", cr:"Photographie Mirka, CC BY-SA 3.0, via Wikimedia Commons."},
   link:["https://en.wikipedia.org/wiki/Promethea","Promethea sur Wikipédia"],
   resume:"Une super-héroïne devient un véritable cours de magie : un épisode entier sur les vingt-deux arcanes, puis un voyage, sefira après sefira, à travers l'Arbre de Vie.",
   parts:[
    ["L'œuvre","Sophie Bangs, étudiante new-yorkaise, découvre qu'en écrivant un poème elle peut devenir Promethea, une figure née de l'imagination, incarnée depuis l'Antiquité par des femmes successives. Alan Moore, qui s'est déclaré magicien en 1993, en fait le livre où il expose sa vision de la magie : l'imagination comme un monde réel, l'Immateria."],
    ["Le tarot, lame par lame","Un épisode entier est construit sur les arcanes majeurs : les vingt-deux lames y défilent l'une après l'autre, avec leurs symboles et leurs correspondances kabbalistiques, de sorte que le lecteur traverse tout le jeu en tournant les pages. Le tarot y devient une histoire de l'univers racontée en vingt-deux images, de l'origine jusqu'à aujourd'hui."],
    ["La montée de l'Arbre de Vie","Pendant une dizaine d'épisodes, Sophie et Barbara, une ancienne Promethea, montent l'Arbre de Vie, de Malkuth jusqu'à Kether : chaque sefira devient un monde, avec sa couleur, son astre et ses épreuves. Les sentiers qu'elles empruntent sont ceux des lames : c'est exactement le chemin du bas vers le haut que décrit l'onglet L'Arbre de Vie d'Arcanes, du Monde jusqu'au Mat."]
   ]},
  {id:"calvino", cat:"litt", titre:"Le Château des destins croisés", qui:"Italo Calvino", date:"1969–1973", lames:["bateleur","amoureux","monde"],
   img:{f:"visconti/amoureux", cap:"L'Amoureux du tarot Visconti, le jeu de la première partie du livre", deck:"visconti"},
   link:["https://fr.wikipedia.org/wiki/Le_Ch%C3%A2teau_des_destins_crois%C3%A9s","Le Château des destins croisés sur Wikipédia"],
   resume:"Des voyageurs devenus muets racontent leur vie en posant des cartes sur une table. L'un des plus beaux livres jamais écrits sur le tarot, et une démonstration de ce qu'est un tirage : une histoire construite par la place des images.",
   parts:[
    ["L'œuvre","Après avoir traversé une forêt, des voyageurs se retrouvent dans un château, puis dans une taverne. Ils ont tous perdu la parole. Pour raconter leur histoire, chacun pose des cartes de tarot sur la table, et le narrateur déchiffre ce qu'elles disent. On y reconnaît Roland furieux, Faust, Parsifal, Hamlet, Macbeth ou le roi Lear, et même l'auteur, qui essaie à son tour de raconter la sienne."],
    ["Deux jeux, deux livres","La première partie paraît seule en 1969, dans un livre de luxe de Franco Maria Ricci consacré au tarot Visconti de Bergame et de New York : ce sont ces cartes, peintes pour les ducs de Milan, que posent les voyageurs du château. Le livre complet paraît en 1973 avec une seconde partie, La Taverne des destins croisés, qui utilise le Tarot de Marseille, plus populaire, plus rude. Les cartes Visconti montrées sur cette page sont exactement celles du livre."],
    ["La structure : un tirage géant","Chaque histoire est une suite de cartes posées en ligne ; mais les lignes se croisent, si bien qu'une même carte sert à deux récits et prend deux sens selon le sens de lecture. À la fin, toutes les cartes forment un grand tableau où toutes les histoires se lisent ensemble.","C'est exactement le principe d'un tirage : une carte n'a pas de sens fixe, elle en prend un selon sa place et ses voisines. Calvino, qui rejoindra l'Oulipo, voit dans le tarot une machine à raconter des histoires, capable de les combiner à l'infini. L'idée lui est venue d'une communication du sémiologue Paolo Fabbri sur la cartomancie, à Urbino, en 1968."]
   ]},
  {id:"eliot", cat:"litt", titre:"La Terre vaine", qui:"T. S. Eliot", date:"1922", lames:["pendu","roue"],
   img:{f:"hist/eliot_wl", cap:"« Madame Sosostris, famous clairvoyante… » : la page des cartes dans l'édition originale, New York, 1922", cr:"T. S. Eliot, The Waste Land, Boni and Liveright, New York, 1922, page 13. Domaine public aux États-Unis ; numérisation Internet Archive (Duke University Libraries), via Wikimedia Commons."},
   link:["https://fr.wikipedia.org/wiki/La_Terre_vaine","La Terre vaine sur Wikipédia"],
   resume:"Le grand poème moderniste s'ouvre sur une séance de cartes : Madame Sosostris, « la femme la plus sage d'Europe, avec un jeu de cartes maléfique », tire le destin d'un monde stérile qui attend sa renaissance.",
   parts:[
    ["L'œuvre","Publié en 1922, La Terre vaine est un collage de voix, de langues et de mythes sur une Europe épuisée par la guerre. Son fil rouge est la légende du Roi Pêcheur, dont la blessure rend la terre stérile jusqu'à ce qu'un chevalier vienne la guérir."],
    ["La séance de Madame Sosostris","Dans la première partie, une voyante enrhumée tire les cartes : le Marin phénicien noyé, Belladonna « la Dame des Rochers », l'homme aux trois bâtons, la Roue, le marchand borgne, une carte blanche qu'il porte sur son dos… et elle ne trouve pas le Pendu. Elle conclut : crains la mort par l'eau. Le reste du poème déroule ces images : le marin Phlébas se noie dans la quatrième partie.","Eliot avoue dans ses notes qu'il connaît mal la composition exacte du tarot et qu'il s'en écarte pour son usage. Il relie le Pendu au dieu pendu des rites antiques décrits par Frazer, et à la silhouette encapuchonnée de la dernière partie ; l'homme aux trois bâtons, au Roi Pêcheur."],
    ["Le tarot et le Graal","Eliot s'appuie sur From Ritual to Romance (1920) de Jessie Weston, qui soutenait que les quatre couleurs du tarot, coupe, lance, épée et plat, descendaient des objets sacrés de la légende du Graal. L'hypothèse n'est pas retenue par les historiens, mais elle a donné au tarot sa place dans la littérature du XXe siècle.","Clin d'œil : quand Dummett, Decker et Depaulis écrivent en 1996 l'histoire des mythes occultes du tarot, ils l'intitulent A Wicked Pack of Cards, « un jeu de cartes maléfique », la formule d'Eliot."]
   ]},
  {id:"williams", cat:"litt", titre:"Les Grands Atouts", qui:"Charles Williams", date:"1932", lames:["mat","monde"],
   img:{f:"hist/cwilliams", cap:"Charles Williams dessiné par Anne Spalding", cr:"Dessin d'Anne Spalding (1911–1948), domaine public, via Wikimedia Commons."},
   link:["https://en.wikipedia.org/wiki/The_Greater_Trumps","The Greater Trumps sur Wikipédia (en anglais)"],
   resume:"Un roman fantastique d'un ami de Tolkien et de C. S. Lewis : un tarot originel commande des figurines d'or qui dansent la danse du monde. Toutes bougent, sauf Le Mat, au centre… qui se révèle le plus rapide de tous.",
   parts:[
    ["L'œuvre","Lothair Coningsby hérite d'un très vieux tarot. Henry Lee, fiancé de sa fille Nancy et descendant d'une famille gitane, reconnaît dans ses grands atouts les modèles de figurines d'or que sa famille garde depuis des siècles, et qui dansent sans fin sur une table. Réunir les cartes et les figurines, c'est pouvoir agir sur les éléments : Henry déchaîne une tempête de neige qui menace le monde."],
    ["Le Mat, centre immobile","Toutes les figurines tournent, sauf une, celle du Mat, qui semble rester immobile au milieu. Seule Sybil, la tante de Nancy, une femme d'une paix et d'une bonté parfaites, voit qu'il bouge aussi, plus vite que tous les autres : il est partout à la fois. C'est l'idée la plus profonde du livre : le zéro n'est pas absent du jeu, il en est le mouvement même, le point autour duquel la danse s'organise."],
    ["L'auteur","Charles Williams appartenait aux Inklings d'Oxford et avait été membre de la Fellowship of the Rosy Cross, l'ordre fondé par Arthur Edward Waite, le concepteur du Waite-Smith. Il mêle ici l'occultisme de la Golden Dawn et une mystique chrétienne de l'amour : c'est Nancy, en apprenant à aimer, qui sauve le monde."]
   ]},
  {id:"breton", cat:"litt", titre:"Arcane 17", qui:"André Breton", date:"1945", lames:["etoile","lune"],
   link:["https://fr.wikipedia.org/wiki/Arcane_17","Arcane 17 sur Wikipédia"],
   resume:"Écrit en 1944 en Gaspésie, ce livre du fondateur du surréalisme prend L'Étoile pour emblème : après la guerre et le deuil, l'amour et la poésie comme forces de renaissance.",
   parts:[
    ["L'œuvre","À l'automne 1944, Breton séjourne à Percé, au Québec, avec Elisa, qu'il vient de rencontrer et qui a perdu sa fille. Face au rocher Percé, il écrit un livre-méditation sur la guerre qui finit, la liberté, l'amour et la femme, mêlant souvenirs, mythes et réflexion politique. Il paraît à New York en 1945."],
    ["L'Étoile, arcane XVII","Le titre désigne la dix-septième lame : une femme nue, agenouillée au bord de l'eau, verse deux urnes sous les étoiles. Breton y voit l'image de l'espérance qui revient après la destruction, et de la femme salvatrice. Il y superpose Mélusine, la fée-serpent des légendes, et Isis, qui rassemble les morceaux d'Osiris : la renaissance après la dispersion. C'est exactement le sens de L'Étoile après La Maison Dieu."],
    ["Les surréalistes et les cartes","En 1941, à Marseille, en attendant de fuir la guerre, Breton et ses amis avaient dessiné leur propre jeu de cartes, le Jeu de Marseille : quatre couleurs nouvelles, l'Amour, le Rêve, la Révolution et la Connaissance, et des figures tirées de leurs héros, Baudelaire, Freud, Lautréamont, Paracelse ou Alice. Le tarot, jeu d'images et de hasard, était pour eux une machine à révéler l'inconscient."]
   ]},
  {id:"amber", cat:"litt", titre:"Les Princes d'Ambre", qui:"Roger Zelazny", date:"1970–1991", lames:["roue","bateleur"],
   link:["https://fr.wikipedia.org/wiki/Cycle_des_Princes_d%27Ambre","Le Cycle des Princes d'Ambre sur Wikipédia"],
   resume:"Dans ce grand cycle de fantasy, une famille royale communique et voyage entre les mondes grâce à des cartes peintes : les Atouts.",
   parts:[
    ["L'œuvre","Ambre est le seul monde réel ; tous les autres, la Terre comprise, n'en sont que des ombres. Corwin, prince amnésique, reprend peu à peu conscience de son rang et entre dans la lutte de ses frères et sœurs pour le trône. Le cycle compte dix romans."],
    ["Les Atouts, des portraits qui ouvrent des portes","Les princes possèdent des jeux de cartes dont les atouts portent leurs portraits. Il suffit de fixer une carte pour joindre la personne représentée, lui parler, et même passer jusqu'à elle. Zelazny prend au pied de la lettre une idée centrale du tarot : une image peut rendre présent ce qu'elle représente. Chaque carte est un seuil, comme chaque lame d'un tirage ouvre une porte vers une part de soi."]
   ]},
  {id:"king", cat:"litt", titre:"La Tour sombre", qui:"Stephen King", date:"1982–2004", lames:["maisondieu","sansnom","roue"],
   img:{f:"hist/king", cap:"Stephen King, l'auteur", cr:"Photographie Pinguino Kolb, CC BY 2.0, via Wikimedia Commons."},
   link:["https://fr.wikipedia.org/wiki/La_Tour_sombre","La Tour sombre sur Wikipédia"],
   resume:"Toute la saga de King marche vers une Tour, et son héros découvre son destin dans un tirage de tarot.",
   parts:[
    ["L'œuvre","Roland, le dernier pistolero, poursuit l'homme en noir à travers un monde qui « a changé », vers la Tour sombre, centre de tous les univers. Sept romans, inspirés d'un poème de Robert Browning, Childe Roland à la Tour noire s'en vint."],
    ["Le tirage de l'homme en noir","À la fin du premier livre, l'homme en noir tire le tarot pour Roland. Sortent le Marin, le Prisonnier, la Dame des ombres, puis la Mort, qui ne le concerne pas, la Tour, et la Vie. Le deuxième livre, Les Trois Cartes, accomplit le tirage : Roland « tire » littéralement dans notre monde les compagnons annoncés par les cartes.","King invente certaines cartes, mais il garde l'esprit du tarot : un tirage n'annonce pas seulement des événements, il désigne des rencontres. Et le Marin noyé est un clin d'œil à Eliot : le troisième tome s'intitule d'ailleurs Terres perdues, The Waste Lands."],
    ["La Tour et la Roue","La Tour de King, centre fragile qui tient tous les mondes, répond à La Maison Dieu, la tour frappée par la foudre. Le destin qui ramène sans cesse les personnages, le ka, est une roue : celle de la dixième lame."]
   ]},
  {id:"niki", cat:"art", titre:"Le Jardin des Tarots", qui:"Niki de Saint Phalle", date:"1979–1998", lames:["imperatrice","maisondieu","roue"],
   link:["https://fr.wikipedia.org/wiki/Jardin_des_Tarots","Le Jardin des Tarots sur Wikipédia"],
   resume:"Près de Capalbio, en Toscane, vingt-deux sculptures monumentales couvertes de miroirs et de céramiques : l'œuvre d'une vie, et le plus grand tarot jamais construit.",
   parts:[
    ["L'œuvre","Niki de Saint Phalle acquiert le terrain en 1979 et y travaille près de vingt ans. Les vingt-deux figures, en béton armé recouvert de miroirs et de mosaïques de céramique, représentent les arcanes majeurs ; on peut entrer dans certaines d'entre elles. Le jardin ouvre au public en 1998. Elle s'inspire du parc Güell de Gaudí à Barcelone, du parc des Monstres de Bomarzo, du Palais idéal du facteur Cheval et des Watts Towers de Los Angeles. Son compagnon, le sculpteur Jean Tinguely, y ajoute des éléments mécaniques."],
    ["Vivre dans L'Impératrice","Pendant plusieurs années de chantier, l'artiste habite à l'intérieur de L'Impératrice, une immense sphinge dont le corps abrite une chambre et une cuisine tapissées de miroirs. La lame de la création et de la fécondité est devenue sa maison et son atelier : on ne peut pas imaginer lecture plus littérale de l'arcane III."],
    ["Un tarot à traverser","Le visiteur se promène d'arcane en arcane comme le Mat sur son chemin : le jardin est un tirage dans lequel on marche. Chaque lame devient un lieu que l'on habite un moment."]
   ]},
  {id:"dali", cat:"art", titre:"Le Tarot universel", qui:"Salvador Dalí", date:"1984", lames:["bateleur","imperatrice"],
   img:{f:"hist/dali", cap:"Salvador Dalí en 1939, par Carl Van Vechten", cr:"Carl Van Vechten, 1939, domaine public (Bibliothèque du Congrès), via Wikimedia Commons."},
   link:["https://www.smithsonianmag.com/smart-news/see-surreal-tarot-cards-designed-salvador-dali-james-bond-movie-180973506/","Voir les cartes (Smithsonian Magazine, en anglais)"],
   resume:"Né d'une commande pour un James Bond, le tarot de Dalí est devenu un jeu complet de 78 cartes où l'artiste se peint en Bateleur et sa femme Gala en Impératrice.",
   parts:[
    ["L'histoire","En 1973, le producteur Albert Broccoli demande à Dalí un tarot pour Vivre et laisser mourir. L'artiste réclame un cachet si élevé que la production renonce. Dalí continue pourtant, seul, et publie en 1984 une édition limitée de 78 cartes, rééditée depuis."],
    ["Un tarot-collage","Dalí peint par-dessus des chefs-d'œuvre de l'histoire de l'art, qu'il découpe, déforme et assemble : le Dix d'Épées reprend par exemple La Mort de César de Vincenzo Camuccini. Le tarot devient un musée imaginaire, où chaque carte dialogue avec un tableau célèbre."],
    ["Le Bateleur et L'Impératrice","Dalí se représente en Bateleur, le magicien qui fait apparaître les choses : c'est ainsi qu'il voyait l'artiste. Gala, sa muse, est L'Impératrice, la créatrice souveraine. Le jeu dit, à sa façon, le mythe du couple Dalí."]
   ]},
  {id:"carrington", cat:"art", titre:"Les Arcanes majeurs", qui:"Leonora Carrington", date:"vers 1955", lames:["papesse","chariot","ermite"],
   link:["https://hyperallergic.com/tarot-of-leonora-carrington-review-fulgur-press","Voir les cartes (Hyperallergic, en anglais)"],
   resume:"La peintre surréaliste, installée au Mexique, peint ses vingt-deux arcanes à l'huile et à la feuille d'or. Restés inconnus, ils ont été redécouverts en 2018.",
   parts:[
    ["L'œuvre","Vers 1955, Leonora Carrington peint les vingt-deux arcanes majeurs sur de petits panneaux, à l'huile, rehaussés d'or et d'argent. Même les spécialistes ignoraient leur existence jusqu'à ce que la commissaire Tere Arcq les retrouve en préparant une rétrospective au Musée d'art moderne de Mexico, en 2018. Ils ont depuis été publiés en livre et en jeu."],
    ["Les sources","Carrington puise aux jeux italiens dorés du XVe siècle, au Marseille, cher aux surréalistes, et au Waite-Smith. Elle y mêle les contes celtiques de son enfance irlandaise, l'alchimie, la Kabbale, et La Déesse blanche de Robert Graves, qu'elle appelait « la plus grande révélation de [sa] vie »."],
    ["Un tarot au féminin","Dans son Chariot, les deux figures qui tirent d'habitude en sens opposés se tournent l'une vers l'autre, liées par un cœur. L'Ermite lui a inspiré deux autoportraits. Son jeu fait de la sagesse féminine, celle de la Papesse et de l'Impératrice, le centre du voyage."]
   ]},
  {id:"cleo", cat:"cine", titre:"Cléo de 5 à 7", qui:"Agnès Varda", date:"1962", lames:["sansnom","lune","soleil"],
   img:{f:"hist/varda", cap:"Agnès Varda en 2019", cr:"Photographie Martin Kraft, CC BY-SA 4.0, via Wikimedia Commons."},
   link:["https://fr.wikipedia.org/wiki/Cl%C3%A9o_de_5_%C3%A0_7","Cléo de 5 à 7 sur Wikipédia"],
   resume:"Le film s'ouvre sur une séance de tarot, seule scène en couleur. La lame de la mort sort, et toute l'attente de la jeune chanteuse en est colorée, pendant treize chapitres.",
   parts:[
    ["L'œuvre","Le 21 juin 1961, de 17 heures à 18 h 30, Cléo, jeune chanteuse, attend les résultats d'un examen médical. Elle craint d'avoir un cancer. Varda suit ces quatre-vingt-dix minutes presque en temps réel, à travers Paris."],
    ["La séance de tarot","La cartomancienne étale les cartes, filmées d'en haut, en couleur, alors que tout le reste du film sera en noir et blanc. Sort une lame de mort, un squelette face à une jeune femme. La voyante explique qu'elle annonce une transformation complète de tout l'être, puis, Cléo partie, confie à son mari qu'elle est perdue. Les deux lectures de la lame XIII, la fin et la métamorphose, vont s'affronter pendant tout le film."],
    ["Treize chapitres","Le film est découpé en treize chapitres, chacun titré avec son horaire : le nombre même de l'Arcane sans nom. Et le film raconte bien cette lame-là : Cléo, qui ne vivait que par son reflet dans les miroirs, se défait de son personnage, se fait appeler par son vrai prénom, Florence, et finit par dire que sa peur est partie. La mort annoncée était une transformation."]
   ]},
  {id:"holy", cat:"cine", titre:"La Montagne sacrée", qui:"Alejandro Jodorowsky", date:"1973", lames:["mat","bateleur","maisondieu"],
   img:{f:"hist/jodorowsky", cap:"Alejandro Jodorowsky en 2024", cr:"Photographie ManoSolo13241324, CC0, via Wikimedia Commons."},
   link:["https://fr.wikipedia.org/wiki/La_Montagne_sacr%C3%A9e_(film,_1973)","La Montagne sacrée sur Wikipédia"],
   resume:"Un voyage initiatique vers le sommet d'une montagne, guidé par un alchimiste : le film où Jodorowsky met en scène ce que le tarot lui a appris, vingt-cinq ans avant sa restauration du Marseille.",
   parts:[
    ["L'œuvre","Un voleur, figure christique, gravit une tour et y rencontre un alchimiste, joué par Jodorowsky, qui change ses excréments en or et le prend pour élève. L'alchimiste réunit sept personnages puissants et corrompus, chacun lié à une planète, et les emmène sur une île pour gravir la Montagne sacrée et voler le secret de l'immortalité à neuf sages."],
    ["Le Mat et les planètes","Le voleur du début est conçu comme Le Mat : un vagabond sans nom, qui part de rien. Les sept compagnons portent chacun une planète, de Vénus à Pluton : c'est l'astrologie que la Golden Dawn a placée sur l'Arbre de Vie, où Vénus va à L'Impératrice, Mars à La Maison Dieu, Jupiter à la Roue et Saturne au Monde. Le film est un tirage vivant."],
    ["« Zoom arrière, caméra ! »","Au sommet, les sages immortels ne sont que des mannequins. L'alchimiste se tourne vers l'équipe de tournage, fait reculer la caméra et renvoie tout le monde, spectateurs compris, à la vraie vie. C'est la leçon du Monde et du retour du Mat : le voyage initiatique ne mène pas ailleurs, il ramène au réel, transformé.","Pour préparer le film, les acteurs ont suivi des exercices spirituels avec Oscar Ichazo, inspirés notamment de Gurdjieff, de la Kabbale et du Yi King. Le récit doit aussi beaucoup au Mont Analogue de René Daumal."]
   ]},
  {id:"bond", cat:"cine", titre:"Vivre et laisser mourir", qui:"Guy Hamilton", date:"1973", lames:["amoureux","papesse","sansnom"],
   link:["https://fr.wikipedia.org/wiki/Vivre_et_laisser_mourir","Vivre et laisser mourir sur Wikipédia"],
   resume:"Solitaire, la voyante du méchant, lit l'avenir dans le tarot. Bond la séduit en trichant : son jeu ne contient que des cartes des Amoureux.",
   parts:[
    ["L'œuvre","Premier James Bond de Roger Moore. Bond enquête sur Kananga, dictateur caribéen et trafiquant, qui s'appuie sur les prédictions de Solitaire, jeune femme dont le don dépend de sa virginité, selon le film."],
    ["Le tarot dans le film","Solitaire, jouée par Jane Seymour, est une figure de Papesse : savoir caché, voile, virginité, oracle au service d'un pouvoir. Bond lui fait tirer une carte dans un jeu truqué, entièrement composé de lames des Amoureux : le choix est joué d'avance. Ironie du tarot : L'Amoureux est justement la lame du choix.","Le jeu du film, peint par l'artiste écossais Fergus Hall, a été édité ensuite sous le nom de Tarot des Sorcières. Dalí avait d'abord été sollicité, mais son cachet était trop élevé : son propre tarot est né de cette commande avortée."]
   ]},
  {id:"persona", cat:"jeux", titre:"Persona", qui:"Atlus", date:"depuis 1996", lames:["mat","sansnom","monde"],
   link:["https://fr.wikipedia.org/wiki/Persona_(s%C3%A9rie_de_jeux_vid%C3%A9o)","Persona sur Wikipédia"],
   resume:"La série de jeux de rôle qui a fait connaître les arcanes à toute une génération : chaque lien, chaque compagnon et chaque créature y porte un arcane, et le héros est Le Mat.",
   parts:[
    ["Le système","Dans Persona, des lycéens invoquent des « Personas », des facettes d'eux-mêmes nées de l'inconscient, un terme et une idée empruntés à Jung, comme celle de l'Ombre. Depuis Persona 3 (2006), chaque arcane majeur correspond à un lien social, appelé Confident dans Persona 5 : se rapprocher d'un personnage renforce les Personas de son arcane."],
    ["Le héros est Le Mat","Le protagoniste porte toujours l'arcane du Mat, la lame zéro : il peut accueillir toutes les Personas, comme Le Mat contient toutes les possibilités. Persona 3 le dit en toutes lettres : un personnage y explique que les arcanes, du Mat au Monde, racontent dans l'ordre le chemin d'une vie. Et l'ennemi final de ce jeu est lié à la Mort, la lame XIII : seul Le Mat, celui qui n'a pas de numéro, peut la traverser."],
    ["Un jeu qui suit le Marseille","Les deux premiers jeux suivent la numérotation du Waite-Smith ; à partir de Persona 3, la série adopte celle du Tarot de Marseille, avec La Justice en VIII et La Force en XI. La série invente aussi de nouveaux arcanes au fil des éditions, l'Éon, le Fou du roi, la Faim, la Foi ou le Conseiller : le jeu grandit, comme les tarots modernes."]
   ]},
  {id:"balatro", cat:"jeux", titre:"Balatro", qui:"LocalThunk", date:"2024", lames:["roue","sansnom","ermite"],
   link:["https://fr.wikipedia.org/wiki/Balatro","Balatro sur Wikipédia"],
   resume:"Ce jeu de poker a fait découvrir les arcanes à des millions de joueurs : les vingt-deux lames y deviennent des cartes magiques dont l'effet reprend souvent leur sens.",
   parts:[
    ["L'œuvre","Un jeu de cartes solitaire où l'on compose des mains de poker, en améliorant son paquet au fil de la partie avec des jokers, des planètes et des cartes de tarot."],
    ["Des effets fidèles aux lames","Les vingt-deux arcanes y ont chacun un pouvoir, souvent bien choisi : La Mort transforme une carte en une autre, la métamorphose de la lame XIII ; La Roue de Fortune n'a qu'une chance sur quatre de réussir ; L'Ermite double ton argent, la sagesse de l'épargne ; Le Pendu sacrifie des cartes ; L'Amoureux rend une carte « joker », libre de prendre toutes les couleurs, comme un choix ouvert ; La Papesse fait apparaître des cartes de planètes, ses astres. L'Étoile, la Lune, le Soleil et le Monde changent la couleur des cartes."],
    ["Le tarot, un jeu","Ironie de l'histoire : Balatro ramène le tarot à ce qu'il était au XVe siècle, un jeu de cartes, et le fait découvrir à un public qui n'a jamais vu de tirage."]
   ]},
  {id:"carmen", cat:"scene", titre:"Carmen", qui:"Georges Bizet", date:"1875", lames:["sansnom","roue"],
   img:{f:"hist/carmen", cap:"L'affiche de la création de Carmen à l'Opéra-Comique, 1875", cr:"Prudent-Louis Leray, 1875, domaine public, via Wikimedia Commons."},
   link:["https://fr.wikipedia.org/wiki/Carmen_(op%C3%A9ra)","Carmen sur Wikipédia"],
   resume:"Au troisième acte, Carmen tire les cartes et y lit sa mort. La scène a fixé pour longtemps l'image de la cartomancie à l'opéra.",
   parts:[
    ["La scène des cartes","Dans la montagne, chez les contrebandiers, Frasquita et Mercédès se tirent les cartes et y lisent amour et richesse. Carmen les rejoint, mêle et coupe à son tour : « Carreau, pique… la mort ! ». Elle chante alors qu'il est vain de fuir les réponses amères : si le destin est écrit, la carte reviendra toujours. Sa mort, au dernier acte, accomplit l'oracle."],
    ["Des cartes ordinaires","Carmen ne tire pas un tarot mais un jeu ordinaire : c'est la cartomancie populaire, celle qu'Etteilla avait codifiée dès 1770 avec un jeu de piquet de trente-deux cartes, avant de passer au tarot. Le pique, couleur des épées, garde le sens le plus sombre : comme les Épées du tarot, il annonce conflit et deuil."]
   ]}
];

/* ---------- Affichage ---------- */
function cultImgHTML(c){
  if(c.img){ const src = c.img.f.startsWith("lames/") ? c.img.f : "jeux/" + c.img.f;
    return `<div class="cult-side"><figure class="cult-img"><img src="${src}.webp" alt="${esc(c.img.cap)}" loading="lazy" decoding="async"><figcaption>${c.img.cap}</figcaption></figure>
      <div class="cult-mini" aria-hidden="true">${c.lames.slice(0,3).map(id => cardSVG(byId(id))).join("")}</div></div>`; }
  return `<div class="cult-cards" aria-label="Les lames de l'œuvre">${c.lames.slice(0,3).map((id,i) => `<span class="cc cc${i}">${cardSVG(byId(id))}</span>`).join("")}</div>`;
}
function cultCredit(c){
  if(!c.img) return "";
  if(c.img.deck){ const D = DECKS[c.img.deck]; return `${D.nom}, ${D.date}. ${D.credit}`; }
  return c.img.cr || "";
}
function cultureHTML(){
  return `<section class="hsec" id="hcult"><h2 class="lsub">Le tarot dans la culture</h2>
    <p class="hcomp-intro">Mangas, romans, poèmes, films, sculptures, jeux vidéo : un florilège d'œuvres construites avec le tarot. Ouvre chaque œuvre pour lire comment elle reprend la structure du jeu et les idées ésotériques qui l'accompagnent.</p>
    ${Object.entries(CULT_CATS).map(([k,l]) => { const list = CULTURE.filter(c => c.cat===k); if(!list.length) return "";
      return `<h3 class="hcult-h">${l}</h3><div class="cults">${list.map(c => `<article class="cult" id="cult-${c.id}">
        <div class="cult-top">${cultImgHTML(c)}
          <div class="cult-head"><h4>${c.titre}</h4><p class="eyebrow">${c.qui} · ${c.date}</p><p>${c.resume}</p>
            <p class="cult-lames">${c.lames.map(id => `<button type="button" class="chip" data-sheet="${id}">${byId(id).nom}</button>`).join("")}</p></div></div>
        <details class="cult-more"><summary>Lire l'analyse complète</summary>
          ${c.parts.map(([h, ps]) => `<h5>${h}</h5>${(Array.isArray(ps) ? ps : [ps]).map(p => `<p>${p}</p>`).join("")}`).join("")}
          <p class="cult-link"><a class="hlink" href="${c.link[0]}" target="_blank" rel="noopener">${c.link[1]} ↗</a></p>
          ${cultCredit(c) ? `<p class="hcredit">Image : ${cultCredit(c)}</p>` : ""}</details></article>`).join("")}</div>`; }).join("")}
    <p class="help">Les mangas, films, sculptures et jeux récents sont protégés par le droit d'auteur : Arcanes ne reproduit pas leurs images. Ils sont évoqués par les lames qu'ils mettent en jeu, et chaque analyse donne un lien vers une page où les voir.</p></section>`;
}

/* ===== Dictionnaire des symboles du Marseille ===== */
const SYM_CATS = {couleurs:"Les couleurs", animaux:"Les animaux et les êtres", ciel:"Le ciel", objets:"Les objets", corps:"Le corps et les gestes", lieux:"Les lieux et la nature"};
const SYMBOLS = [
  /* Couleurs, d'après la lecture de Jodorowsky et Camoin */
  {id:"rouge", cat:"couleurs", nom:"Le rouge", hex:"#c8402a", sens:"L'énergie, l'action, la passion, le sang qui circule. Le rouge dit ce qui agit et ce qui brûle.", lames:["pape","papesse","temperance","monde"]},
  {id:"bleu", cat:"couleurs", nom:"Le bleu", hex:"#2b4a8b", sens:"La réceptivité, le calme, l'intériorité. Le bleu est ce qui accueille plutôt que ce qui agit : le ciel, l'eau, l'âme.", lames:["imperatrice","ermite","temperance","pendu"]},
  {id:"jaune", cat:"couleurs", nom:"Le jaune", hex:"#e3b53a", sens:"La lumière, l'intelligence, la conscience. C'est l'or des couronnes et du soleil : ce qui éclaire.", lames:["soleil","bateleur","etoile","jugement"]},
  {id:"vert", cat:"couleurs", nom:"Le vert", hex:"#3f7d45", sens:"La nature, la croissance, la vie qui pousse. Le vert parle de ce qui se développe à son rythme, et d'espoir.", lames:["mat","amoureux","ermite","etoile"]},
  {id:"chair", cat:"couleurs", nom:"La couleur chair", hex:"#f0c2a4", sens:"L'humain, le corps vivant, la sensibilité. Là où la chair est nue, la lame parle de vérité sans masque.", lames:["sansnom","etoile","soleil","monde"]},
  {id:"noir", cat:"couleurs", nom:"Le noir", hex:"#1d1b1a", sens:"La terre profonde, le mystère, ce qui travaille en secret. Rare dans le jeu, il couvre le sol de L'Arcane sans nom : la terre où tout se décompose pour renaître.", lames:["sansnom"]},
  {id:"blanc", cat:"couleurs", nom:"Le blanc", hex:"#f4efe4", sens:"La pureté, la sagesse, le vide qui permet de recevoir. C'est aussi la couleur du papier lui-même, la lumière de fond de toutes les lames.", lames:["papesse","ermite","lune"]},
  /* Animaux et êtres */
  {id:"chien", cat:"animaux", nom:"Le chien", sens:"L'instinct, la fidélité, l'animal qui nous accompagne. Il pousse Le Mat à avancer ; à La Lune, deux chiens hurlent vers l'astre, entre domestique et sauvage.", lames:["mat","lune"]},
  {id:"cheval", cat:"animaux", nom:"Le cheval", sens:"La force vitale qu'on dirige. Les deux chevaux du Chariot tirent chacun de leur côté : c'est au conducteur de les tenir ensemble. Au Monde, la bête du coin inférieur gauche, souvent lue comme un taureau, est la force de la terre.", lames:["chariot","monde"]},
  {id:"lion", cat:"animaux", nom:"Le lion", sens:"La puissance animale, le désir, la colère. La Force ne le tue pas, elle l'apprivoise. Au Monde, il est l'un des quatre vivants, le feu.", lames:["force","monde"]},
  {id:"aigle", cat:"animaux", nom:"L'aigle", sens:"La hauteur de vue, le pouvoir, l'esprit qui s'élève. Il orne le bouclier de L'Impératrice et celui de L'Empereur ; au Monde, il est l'un des quatre vivants, l'air.", lames:["imperatrice","empereur","monde"]},
  {id:"ecrevisse", cat:"animaux", nom:"L'écrevisse", sens:"Ce qui remonte des profondeurs. Au fond du bassin de La Lune, elle figure l'inconscient, les peurs anciennes et les intuitions qui cherchent la lumière.", lames:["lune"]},
  {id:"oiseau", cat:"animaux", nom:"L'oiseau", sens:"L'âme, l'inspiration, le lien entre le ciel et la terre. Posé sur un arbre de L'Étoile, il chante la confiance retrouvée.", lames:["etoile"]},
  {id:"creatures", cat:"animaux", nom:"Les créatures de la Roue", sens:"L'une monte, l'autre descend, le sphinx couronné reste en haut avec son épée : on ne s'arrête pas sur la roue, on apprend à en trouver le centre.", lames:["roue"]},
  {id:"ange", cat:"animaux", nom:"L'ange et Cupidon", sens:"Le messager du ciel. Cupidon décoche sa flèche au-dessus des Amoureux, l'ange de Tempérance mélange les eaux, celui du Jugement appelle à se relever, celui du Monde veille dans son coin.", lames:["amoureux","temperance","jugement","monde"]},
  {id:"diablotins", cat:"animaux", nom:"Les diablotins", sens:"Deux petits êtres attachés par le cou au socle du Diable. La corde est lâche : ils pourraient s'en défaire. C'est l'image de l'attachement qu'on entretient soi-même.", lames:["diable"]},
  /* Ciel */
  {id:"soleil", cat:"ciel", nom:"Le soleil et ses rayons", sens:"La conscience, la chaleur, la vérité qui se montre. Il brille derrière Cupidon chez L'Amoureux, règne sur Le Soleil et rayonne autour de l'ange du Jugement.", lames:["amoureux","soleil","jugement"]},
  {id:"lune", cat:"ciel", nom:"La lune", sens:"L'intuition, les rêves, ce qui est vrai à moitié. Elle a un visage de profil à La Lune ; sur les épaules du Chariot, deux croissants à visage rappellent ses deux humeurs.", lames:["lune","chariot"]},
  {id:"etoiles", cat:"ciel", nom:"Les étoiles", sens:"Huit étoiles, une grande et sept petites, au-dessus de la femme de L'Étoile : l'espoir, l'orientation, la place de chacun dans le cosmos.", lames:["etoile"]},
  {id:"gouttes", cat:"ciel", nom:"Les gouttes et les boules de couleur", sens:"Des gouttes montent vers La Lune et descendent du Soleil ; des boules colorées tombent autour de la Maison Dieu. C'est un échange d'énergie entre le ciel et la terre.", lames:["lune","soleil","maisondieu"]},
  {id:"nuages", cat:"ciel", nom:"Les nuages", sens:"Ils ouvrent le ciel du Jugement pour laisser passer l'ange : le monde invisible qui se manifeste.", lames:["jugement"]},
  {id:"feu", cat:"ciel", nom:"Le feu et la flamme", sens:"Une flamme en panache sort du sommet de la Maison Dieu ; Le Diable tient une torche. Le feu détruit et éclaire à la fois.", lames:["maisondieu","diable"]},
  /* Objets */
  {id:"baton", cat:"objets", nom:"Le bâton et la baguette", sens:"L'appui, la direction, le pouvoir de faire. Le Mat marche avec le sien, l'Ermite s'y appuie, le Bateleur et la danseuse du Monde tiennent une baguette.", lames:["mat","bateleur","ermite","monde"]},
  {id:"sceptre", cat:"objets", nom:"Le sceptre", sens:"L'autorité qu'on exerce dans le monde. Ceux de L'Impératrice et de L'Empereur portent un globe et une croix ; celui du Pape a trois traverses.", lames:["imperatrice","empereur","chariot","pape"]},
  {id:"couronne", cat:"objets", nom:"Couronnes et tiares", sens:"Ce qui est accompli, la souveraineté, l'esprit au-dessus de la tête. À la Maison Dieu, la couronne est arrachée de la tour : l'orgueil qui tombe.", lames:["papesse","imperatrice","empereur","pape","chariot","justice","roue","maisondieu"]},
  {id:"chapeau", cat:"objets", nom:"Le grand chapeau", sens:"Le Bateleur et La Force portent le même chapeau aux larges bords, dont la forme rappelle le huit couché de l'infini : une énergie sans fin, au début de chaque série.", lames:["bateleur","force"]},
  {id:"livre", cat:"objets", nom:"Le livre", sens:"Le savoir reçu, la tradition, ce qui s'étudie dans le silence. La Papesse le garde ouvert sur ses genoux.", lames:["papesse"]},
  {id:"epee", cat:"objets", nom:"L'épée", sens:"Ce qui tranche, la décision, la parole juste. La Justice la tient droite ; le sphinx de la Roue la tient au sommet.", lames:["justice","roue"]},
  {id:"balance", cat:"objets", nom:"La balance", sens:"Peser, comparer, rendre à chacun ce qui lui revient. Elle est l'équilibre que La Justice cherche entre deux plateaux.", lames:["justice"]},
  {id:"lanterne", cat:"objets", nom:"La lanterne", sens:"Une petite lumière qu'on porte soi-même : celle de L'Ermite éclaire juste assez pour faire le pas suivant.", lames:["ermite"]},
  {id:"faux", cat:"objets", nom:"La faux", sens:"Elle coupe ce qui est mûr ou mort pour laisser repousser. Avec elle, L'Arcane sans nom fait le ménage.", lames:["sansnom"]},
  {id:"vases", cat:"objets", nom:"Les vases et les cruches", sens:"Recevoir et donner. Tempérance fait passer l'eau d'un vase à l'autre, L'Étoile verse ses deux cruches dans la rivière, la danseuse du Monde tient une fiole.", lames:["temperance","etoile","monde"]},
  {id:"table", cat:"objets", nom:"La table et ses outils", sens:"Gobelets, pièces, couteau, dés : tous les moyens sont posés devant le Bateleur. À lui de choisir comment s'en servir.", lames:["bateleur"]},
  {id:"liens", cat:"objets", nom:"La corde et les liens", sens:"Ce qui attache ou ce qui retient. Le Pendu est suspendu par un pied, les diablotins sont liés au socle : l'un accepte son lien, les autres le subissent.", lames:["pendu","diable"]},
  {id:"arc", cat:"objets", nom:"L'arc et la flèche", sens:"Le désir qui frappe sans prévenir. Cupidon vise l'un des trois personnages de L'Amoureux : le choix vient parfois du cœur avant la raison.", lames:["amoureux"]},
  {id:"trompette", cat:"objets", nom:"La trompette", sens:"L'appel qu'on ne peut pas ignorer. L'ange du Jugement souffle et réveille ceux qui dormaient.", lames:["jugement"]},
  {id:"baluchon", cat:"objets", nom:"Le baluchon", sens:"Tout ce que Le Mat emporte avec lui, son passé et ses ressources, léger sur l'épaule.", lames:["mat"]},
  {id:"mandorle", cat:"objets", nom:"La couronne de feuilles", sens:"Une grande couronne ovale entoure la danseuse du Monde : l'espace accompli, protégé, où tout est enfin à sa place.", lames:["monde"]},
  /* Corps et gestes */
  {id:"nudite", cat:"corps", nom:"La nudité", sens:"La vérité sans masque, l'être tel qu'il est. L'Étoile se donne, les enfants du Soleil jouent, les ressuscités du Jugement renaissent, la danseuse du Monde est libre. Le Diable, lui, s'exhibe : la nudité y devient provocation.", lames:["etoile","soleil","jugement","monde","diable"]},
  {id:"jambes", cat:"corps", nom:"Les jambes croisées", sens:"Les jambes qui forment un quatre : la stabilité, la matière, le monde construit. On les retrouve chez L'Empereur, Le Pendu et la danseuse du Monde, le même chiffre lu à l'endroit, à l'envers puis en mouvement.", lames:["empereur","pendu","monde"]},
  {id:"mains", cat:"corps", nom:"La main levée", sens:"Le Pape lève la main pour bénir, Le Diable pour fasciner : le même geste, l'un qui relie au ciel, l'autre qui attache.", lames:["pape","diable"]},
  {id:"morceaux", cat:"corps", nom:"Têtes, mains et pieds dans la terre", sens:"Autour de L'Arcane sans nom, des têtes, des mains et des pieds sortent du sol noir. Ce qui est coupé n'est pas perdu : il repousse autrement.", lames:["sansnom"]},
  {id:"ailes", cat:"corps", nom:"Les ailes", sens:"Ce qui s'élève au-dessus de la matière. Ailes d'oiseau pour Cupidon, Tempérance et l'ange du Jugement, ailes déployées derrière le trône de L'Impératrice, ailes de chauve-souris pour Le Diable : deux manières d'échapper au sol.", lames:["imperatrice","amoureux","temperance","jugement","diable"]},
  {id:"paires", cat:"corps", nom:"Les paires", sens:"Deux disciples devant Le Pape, deux diablotins au Diable, deux chiens à La Lune, deux enfants au Soleil : quand un personnage se dédouble, la lame parle de relation, de reflet ou de choix.", lames:["pape","diable","lune","soleil"]},
  /* Lieux et nature */
  {id:"tour", cat:"lieux", nom:"La tour", sens:"Ce qu'on a construit pour se protéger. La Maison Dieu s'ouvre par le sommet ; à La Lune, deux tours gardent un passage vers l'inconnu.", lames:["maisondieu","lune"]},
  {id:"colonnes", cat:"lieux", nom:"Colonnes, piliers et dais", sens:"Le cadre, le seuil, l'institution. Le Pape siège entre deux colonnes, La Justice entre les montants de son trône, le Chariot sous un dais à quatre piliers.", lames:["pape","justice","chariot","papesse"]},
  {id:"voile", cat:"lieux", nom:"Le voile et le rideau", sens:"Ce qui cache et protège ce qui n'est pas encore prêt à être vu : derrière La Papesse, un voile ; au-dessus du Chariot, un dais.", lames:["papesse","chariot"]},
  {id:"eau", cat:"lieux", nom:"L'eau", sens:"Les émotions, le flux de la vie. Elle coule entre les vases de Tempérance, se mêle à la rivière de L'Étoile, dort dans le bassin de La Lune.", lames:["temperance","etoile","lune"]},
  {id:"plantes", cat:"lieux", nom:"Les plantes et les pousses", sens:"La vie qui recommence, toujours. Elles poussent sous les pieds du Mat et du Bateleur, renaissent dans la terre de L'Arcane sans nom, fleurissent autour de L'Étoile.", lames:["mat","bateleur","sansnom","etoile"]},
  {id:"arbres", cat:"lieux", nom:"Les arbres", sens:"Les racines et la croissance. Le Pendu est suspendu entre deux arbres aux branches coupées ; à L'Étoile, un arbre porte l'oiseau.", lames:["pendu","etoile"]},
  {id:"mur", cat:"lieux", nom:"Le mur", sens:"Une limite protectrice. Derrière les deux enfants du Soleil, un mur de briques ferme un jardin où l'on peut enfin être soi.", lames:["soleil"]},
  {id:"tombe", cat:"lieux", nom:"La tombe", sens:"Ce qu'on croyait fini. Au Jugement, trois personnes se lèvent d'une tombe ouverte : rien n'est définitivement enterré.", lames:["jugement"]}
];
const ss = { cat:"tout", q:"" };
function symbolsFor(id){ return SYMBOLS.filter(s => s.lames.includes(id)); }
function symbolsHTML(){
  const norm = t => t.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"");
  const q = norm(ss.q.trim());
  const list = SYMBOLS.filter(s => (ss.cat==="tout" || s.cat===ss.cat) && (!q || norm(s.nom + " " + s.sens + " " + s.lames.map(i=>byId(i).nom).join(" ")).includes(q)));
  const groups = Object.keys(SYM_CATS).filter(c => list.some(s=>s.cat===c));
  return groups.length ? groups.map(c => `<div class="sgroup"><h2 class="sgroup-h">${SYM_CATS[c]}</h2><div class="sgrid">${list.filter(s=>s.cat===c).map(s => `
      <article class="sym" id="sym-${s.id}">
        <h3>${s.hex ? `<span class="swatch" style="background:${s.hex}"></span>` : ""}${s.nom}</h3>
        <p>${s.sens}</p>
        <div class="sym-lames">${s.lames.map(i => `<button type="button" class="sym-lame" data-sheet="${i}" aria-label="Ouvrir la fiche ${byId(i).nom}">${cardSVG(byId(i))}<span>${byId(i).nom}</span></button>`).join("")}</div>
      </article>`).join("")}</div></div>`).join("") : `<p class="help">Aucun symbole ne correspond à « ${esc(ss.q)} ».</p>`;
}
function dictHTML(){
  const chips = [["tout","Tout"],["couleurs","Couleurs"],["animaux","Animaux et êtres"],["ciel","Ciel"],["objets","Objets"],["corps","Corps et gestes"],["lieux","Lieux et nature"]];
  return `<section class="dict" id="dict">
    <div class="dict-tools"><div class="chips" role="group" aria-label="Catégories">${chips.map(([k,l])=>`<button type="button" class="chip${ss.cat===k?" on":""}" data-scat="${k}" aria-pressed="${ss.cat===k}">${l}</button>`).join("")}</div>
      <input type="search" id="sym-q" placeholder="Chercher un symbole : lion, couronne, rouge…" value="${esc(ss.q)}" aria-label="Chercher un symbole"></div>
    <div id="sym-list">${symbolsHTML()}</div></section>`;
}
function bindDict(root){
  root.querySelectorAll("[data-scat]").forEach(b => b.onclick = () => { ss.cat = b.dataset.scat;
    root.querySelectorAll("[data-scat]").forEach(x => { const on = x.dataset.scat===ss.cat; x.classList.toggle("on", on); x.setAttribute("aria-pressed", on); });
    $("#sym-list").innerHTML = symbolsHTML(); bindSheetLinks($("#sym-list")); });
  const q = $("#sym-q"); if(q) q.oninput = () => { ss.q = q.value; $("#sym-list").innerHTML = symbolsHTML(); bindSheetLinks($("#sym-list")); };
  bindSheetLinks($("#sym-list"));
}
function goSymbol(id){
  ss.cat = "tout"; ss.q = ""; closeSheet(); lamesSub = "sym"; if(state.view === "lames") renderLames(); else setView("lames");
  const el = document.getElementById("sym-"+id);
  if(el){ el.scrollIntoView({block:"center", behavior: reduceMotion() ? "auto" : "smooth"}); el.classList.add("flash"); setTimeout(()=>el.classList.remove("flash"), 1600); }
}

/* ===== L'Arbre de Vie : les dix sefirot, les vingt-deux sentiers et les arcanes majeurs =====
   Pensé pour quelqu'un qui découvre : d'abord comprendre en cinq étapes, puis explorer lame par lame. */
const SEFIROT = {
  kether:   {n:1,  nom:"Kether",    fr:"la Couronne",     pil:"milieu", et:0, astre:"le Premier Mouvant (Primum Mobile)", txt:"La source, l'unité d'avant toute division. Le point d'où tout émane, au-delà de ce que l'on peut nommer ou se représenter.", vie:"Ce qui te relie à plus grand que toi : le sens, la source, la raison d'être.", q:"Qu'est-ce qui donne un sens à ma vie ?"},
  chokmah:  {n:2,  nom:"Chokmah",   fr:"la Sagesse",      pil:"droit",  et:0, astre:"le Zodiaque", txt:"Le premier jaillissement, la force créatrice pure : l'idée qui surgit d'un coup, avant d'avoir une forme. La Kabbale l'appelle le Père.", vie:"Les idées soudaines, l'élan créateur, l'intuition qui jaillit sans prévenir.", q:"Quel élan me traverse en ce moment ?"},
  binah:    {n:3,  nom:"Binah",     fr:"l'Intelligence",  pil:"gauche", et:0, astre:"Saturne", txt:"Le réceptacle qui donne forme : comprendre, contenir, structurer. La Kabbale l'appelle la Mère : elle accepte les limites sans lesquelles rien ne prend corps.", vie:"Ta capacité de comprendre, d'organiser, d'accepter le temps et les limites.", q:"Quelle forme puis-je donner à ce que je veux ?"},
  chesed:   {n:4,  nom:"Chesed",    fr:"la Clémence",     pil:"droit",  et:1, astre:"Jupiter", txt:"La bonté qui donne sans compter, l'expansion, la générosité qui bâtit. On l'appelle aussi Gedulah, la Grandeur.", vie:"Ta générosité, ta confiance, ton envie de donner et de construire.", q:"Qu'ai-je à donner, et à qui ?"},
  geburah:  {n:5,  nom:"Geburah",   fr:"la Rigueur",      pil:"gauche", et:1, astre:"Mars", txt:"La force qui tranche, la discipline, la justice : ce qui retire pour rétablir l'équilibre. On l'appelle aussi Din, le Jugement.", vie:"Ta capacité de dire non, de trancher, de te discipliner.", q:"Qu'est-ce que je dois couper ou refuser ?"},
  tiphareth:{n:6,  nom:"Tiphareth", fr:"la Beauté",       pil:"milieu", et:1, astre:"le Soleil", txt:"Le cœur de l'Arbre, l'harmonie entre la clémence et la rigueur. C'est le centre de l'être, le soi, relié à presque toutes les autres sefirot.", vie:"Ton centre : ce qui en toi est vrai, juste et harmonieux.", q:"Qu'est-ce qui est juste pour moi, au fond ?"},
  netzach:  {n:7,  nom:"Netzach",   fr:"la Victoire",     pil:"droit",  et:2, astre:"Vénus", txt:"Les émotions, le désir, l'art et l'endurance de ce qui aime. La force qui persévère parce qu'elle est portée par le cœur.", vie:"Tes émotions, tes désirs, ton amour de la beauté.", q:"Qu'est-ce que je désire vraiment ?"},
  hod:      {n:8,  nom:"Hod",       fr:"la Gloire",       pil:"gauche", et:2, astre:"Mercure", txt:"L'intellect, le langage, les symboles et les rites : la pensée qui classe, nomme et transmet. On traduit aussi par la Splendeur.", vie:"Ta pensée, tes mots, ta façon d'analyser et de te raconter les choses.", q:"Quelle histoire est-ce que je me raconte ?"},
  yesod:    {n:9,  nom:"Yesod",     fr:"le Fondement",    pil:"milieu", et:2, astre:"la Lune", txt:"L'imaginaire, les rêves, l'inconscient : la fondation invisible sur laquelle repose le monde visible.", vie:"Tes rêves, ton imaginaire, tes habitudes, ce qui agit en toi sans bruit.", q:"Quelles images me guident sans que je le sache ?"},
  malkuth:  {n:10, nom:"Malkuth",   fr:"le Royaume",      pil:"milieu", et:3, astre:"la Terre et les quatre éléments", txt:"Le monde concret, le corps, la matière : là où tout ce qui descend de l'Arbre s'incarne, et d'où part celui qui veut remonter.", vie:"Ton corps, ta maison, ton travail : le monde que tu touches.", q:"Que puis-je faire concrètement aujourd'hui ?"}
};
const PILIERS = {droit:"le pilier de la Clémence", gauche:"le pilier de la Rigueur", milieu:"le pilier de l'Équilibre"};
const ETAGES = [
  {t:"Le monde de l'esprit", d:"Kether, Chokmah et Binah : les grands principes, au-dessus de l'Abîme. Ce que l'on ne peut pas toucher, seulement pressentir."},
  {t:"Le monde de l'âme", d:"Chesed, Geburah et Tiphareth : l'éthique et le cœur, entre l'Abîme et le Voile. Ce qui en toi choisit, donne, juge et aime."},
  {t:"Le monde de la personnalité", d:"Netzach, Hod et Yesod : les émotions, la pensée et l'imaginaire. La vie psychique de tous les jours."},
  {t:"Le monde concret", d:"Malkuth : le corps et la matière, le point de départ de tout voyage intérieur."}
];
/* Les six bandes de l'Arbre, de haut en bas : chaque lame trouve sa place dans l'une d'elles */
const BANDES = [
  {t:"Dans le monde de l'esprit", d:"Trois sentiers entre la Couronne, la Sagesse et l'Intelligence : l'origine de tout.", ids:["mat","bateleur","imperatrice"]},
  {t:"Ils traversent l'Abîme", d:"Cinq sentiers qui font descendre les grands principes vers l'âme, en franchissant le vide où se tient Daath.", ids:["papesse","empereur","pape","amoureux","chariot"]},
  {t:"Dans le monde de l'âme", d:"Trois sentiers entre la Clémence, la Rigueur et le cœur : l'éthique et la sagesse.", ids:["force","ermite","justice"]},
  {t:"Ils traversent le Voile", d:"Cinq sentiers qui relient l'âme à la personnalité : les grandes épreuves de transformation.", ids:["roue","pendu","sansnom","temperance","diable"]},
  {t:"Dans le monde de la personnalité", d:"Trois sentiers entre les émotions, la pensée et l'imaginaire.", ids:["maisondieu","etoile","soleil"]},
  {t:"Ils descendent dans le monde concret", d:"Trois sentiers qui touchent la Terre : les premiers pas de celui qui commence à monter.", ids:["lune","jugement","monde"]}
];
const bandeOf = id => BANDES.findIndex(b => b.ids.includes(id));

/* Chaque sentier en profondeur, dans la tradition de la Golden Dawn.
   voie : le titre traditionnel des « Trente-deux voies de la sagesse » (traduction de Westcott, 1887). */
const VOIES = {
  mat:{voie:"l'Intelligence scintillante", txt:["C'est le tout premier sentier, celui par lequel l'Unité de Kether se met en mouvement vers Chokmah, la première force créatrice. Rien n'a encore de forme : il n'y a qu'un souffle. La Golden Dawn y place le Mat, la lame zéro, et Aleph, la lettre muette qui ne se prononce pas mais porte toutes les autres. Aleph est une lettre mère : l'Air, l'élément qui circule partout et ne se fixe nulle part.","Le Mat sur ce sentier n'est pas un fou au sens courant : c'est l'innocence de l'esprit avant toute expérience, la confiance totale de celui qui part sans savoir. Le zéro n'est pas un manque, c'est un potentiel : tout est encore possible."], tirage:"Quand Le Mat sort, l'Arbre invite à regarder ce qui en toi est encore libre de toute forme : une envie de départ, une idée neuve, une liberté à reprendre. C'est un appel à oser avant d'avoir toutes les réponses, et un rappel : le souffle a besoin d'une direction pour devenir un chemin."},
  bateleur:{voie:"l'Intelligence de transparence", txt:["Le deuxième sentier descend de la Couronne vers Binah, l'Intelligence, la grande forme qui contient. Là où le Mat était souffle, le Bateleur est intention : il prend ce qui vient d'en haut et commence à lui donner une forme. Beth veut dire la maison : c'est la première lettre de la Bible hébraïque (Bereshit, « au commencement »), le premier contenant. Mercure, le messager, est l'astre de la parole, de l'habileté et des échanges.","Le Bateleur de l'Arbre est le magicien qui relie le ciel et la terre : une main tient la baguette tournée vers le haut, l'autre manie les objets de la table, les outils du monde concret, prêts à servir."], tirage:"Le Bateleur te demande de passer de l'idée au premier geste. Tu as les outils sur la table : nomme ce que tu veux, choisis un instrument, commence. Sur ce sentier, la parole a du pouvoir : ce que tu formules clairement commence à exister."},
  papesse:{voie:"l'Intelligence unificatrice", txt:["C'est le plus long sentier de l'Arbre et le plus central : il descend tout droit de la Couronne jusqu'au cœur, Tiphareth, en traversant l'Abîme, la zone vide où se tient Daath, la connaissance cachée. Gimel veut dire le chameau : l'animal qui traverse le désert en portant sa propre eau. La Lune est l'astre du reflet, de l'intuition et des cycles.","La Papesse est donc la gardienne d'un savoir qui ne s'apprend pas dans les livres mais se reçoit dans le silence. Elle relie directement le plus haut et le plus intime : la part de toi qui sait, avant de pouvoir l'expliquer."], tirage:"Quand La Papesse sort, l'Arbre conseille de ne pas forcer la réponse. Écoute, observe, laisse mûrir : l'intuition qui monte en toi vient de plus loin que ta réflexion du moment. C'est un temps d'étude, d'écriture, de retraite."},
  imperatrice:{voie:"l'Intelligence illuminatrice", txt:["Ce sentier est horizontal : il relie Chokmah, la force qui jaillit, et Binah, la forme qui accueille, les deux grands principes de la création, que la Kabbale appelle le Père et la Mère. Leur union, c'est la fécondité même : voilà pourquoi la Golden Dawn y place L'Impératrice. Daleth veut dire la porte, l'ouverture par laquelle la vie passe d'un monde à l'autre. Vénus est l'astre de l'amour, de la beauté et de l'harmonie.","L'Impératrice est l'énergie qui fait naître : elle n'invente pas seule, elle unit. Sur l'Arbre, c'est le premier équilibre entre deux pôles, le modèle de tous les sentiers horizontaux qui suivront."], tirage:"Quand L'Impératrice sort, quelque chose demande à naître : un projet, une œuvre, une relation. L'Arbre dit que la création vient de la rencontre entre l'élan et la forme, entre l'idée et la patience. Ouvre la porte, nourris, laisse grandir."},
  empereur:{voie:"l'Intelligence constituante", txt:["Le sentier descend de Chokmah, l'élan créateur, vers Tiphareth, le cœur, en traversant l'Abîme. L'élan pur devient ordre : la volonté s'organise, construit, gouverne. Heh veut dire la fenêtre, l'ouverture qui laisse entrer la lumière. Le Bélier, premier signe du zodiaque, est l'audace des commencements.","L'Empereur de l'Arbre n'est pas un tyran : il est la structure qui permet à la vie de durer. Il pose les fondations sur lesquelles le cœur pourra s'épanouir."], tirage:"L'Empereur te demande de prendre ta place et d'organiser : poser un cadre, décider, assumer une autorité juste. Sur ce sentier, l'audace doit devenir construction. Demande-toi ce qui mérite des fondations solides."},
  pape:{voie:"l'Intelligence triomphale", txt:["Ce sentier descend le long du pilier de droite, celui de la Clémence : la Sagesse de Chokmah y devient bonté et enseignement en Chesed. Vav veut dire le clou, le crochet : la lettre qui relie, comme la conjonction « et » en hébreu. Le Taureau est le signe de la stabilité, de la patience et de ce qui s'enracine.","Le Pape est le pont entre le savoir et ceux qui le reçoivent : il transmet, il relie, il bénit. Sur l'Arbre, il est la tradition vivante, la sagesse qui accepte de se mettre au service des autres."], tirage:"Le Pape invite à chercher ou à donner un conseil, à s'appuyer sur une tradition, un maître, une communauté. Sur ce sentier, la question est : qu'as-tu à transmettre, et de qui acceptes-tu d'apprendre ?"},
  amoureux:{voie:"l'Intelligence ordonnatrice", txt:["Ce sentier descend de Binah, la compréhension, jusqu'au cœur de l'Arbre, en traversant l'Abîme. Ce que l'on a compris doit maintenant être choisi et aimé. Zayin veut dire l'épée, ou l'arme : la lettre qui tranche. Les Gémeaux sont le signe de la dualité, du dialogue, des deux voies possibles.","L'Amoureux de l'Arbre parle du choix qui engage tout l'être. Choisir, c'est trancher entre deux possibles, mais c'est aussi s'unir à ce que l'on choisit. Le cœur, Tiphareth, est au bout du sentier : c'est lui qui doit décider."], tirage:"Quand L'Amoureux sort, l'Arbre dit qu'un choix t'attend et qu'il ne se fera pas seulement par la raison. Écoute ce que ton cœur reconnaît comme juste, puis accepte que choisir une voie, c'est en laisser une autre."},
  chariot:{voie:"l'Intelligence de la maison de l'influence", txt:["Ce sentier descend le pilier de gauche, celui de la Rigueur, de Binah à Geburah : la forme reçoit la force, la compréhension devient action déterminée. Cheth veut dire l'enclos, la barrière qui protège un espace. Le Cancer, signe d'eau, est l'abri, la carapace, la maison que l'on porte avec soi.","Le Chariot de l'Arbre est donc un véhicule protégé : la volonté avance, mais à l'intérieur d'un cadre qui la garde. C'est la maîtrise qui permet de traverser le monde sans s'y perdre."], tirage:"Le Chariot te dit d'avancer, mais avec une direction et des limites claires. Protège ce qui compte, tiens les rênes, ne te disperse pas. Sur ce sentier, la victoire vient de la constance plus que de la vitesse."},
  force:{voie:"l'Intelligence du secret de toutes les activités spirituelles", txt:["C'est le deuxième sentier horizontal : il relie Chesed, la Clémence qui donne, et Geburah, la Rigueur qui tranche. Entre la douceur et la sévérité, il faut une force d'un autre ordre : celle qui dompte sans briser. Teth veut dire le serpent, l'énergie vitale enroulée. Le Lion est le signe du feu, du courage et du cœur.","C'est pourquoi la Golden Dawn place ici La Force et lui donne le numéro VIII, avant La Justice. La femme qui ouvre la gueule du lion sans effort montre que la vraie puissance est l'énergie animale apprivoisée par la douceur."], tirage:"La Force te demande de ne pas choisir entre la douceur et la fermeté, mais de les unir. Ce qui te résiste se calme quand tu l'abordes avec calme et courage. Sur ce sentier, la maîtrise de soi est la plus grande des forces."},
  ermite:{voie:"l'Intelligence de la volonté", txt:["Ce sentier descend de Chesed, la générosité, vers le cœur de l'Arbre. La bonté devient sagesse intérieure : avant de donner aux autres, il faut trouver sa propre lumière. Yod veut dire la main ; c'est la plus petite lettre, un simple trait de flamme, dont toutes les autres lettres semblent formées. La Vierge est le signe de la discrétion, du tri, du travail patient.","L'Ermite porte cette petite flamme dans sa lanterne : il éclaire juste assez pour faire le pas suivant, et c'est assez. Sur l'Arbre, il est la sagesse qui naît du retrait et de l'expérience."], tirage:"L'Ermite conseille le recul, la solitude choisie, la recherche patiente. N'attends pas de grande révélation : la petite lumière que tu as suffit pour avancer. Sur ce sentier, le temps est un allié."},
  roue:{voie:"l'Intelligence de conciliation", txt:["Ce sentier descend le pilier de droite, de Chesed à Netzach, et traverse le Voile qui sépare l'âme de la personnalité. L'abondance de Chesed entre dans le monde du désir et des émotions : elle devient cycle, chance, mouvement. Kaph veut dire la paume de la main, ouverte pour recevoir. Jupiter est l'astre de l'expansion et de la bonne fortune.","La Roue de Fortune dit que tout tourne : ce qui monte redescend, ce qui est perdu revient. La sagesse n'est pas d'arrêter la roue, mais de se tenir près de son centre, là où le mouvement est le plus calme."], tirage:"La Roue annonce un changement de cycle. Ouvre la main pour recevoir ce qui vient et laisse partir ce qui s'en va. Sur ce sentier, la question n'est pas « pourquoi moi ? » mais « que m'apprend ce tour de roue ? »"},
  justice:{voie:"l'Intelligence fidèle", txt:["Ce sentier relie Geburah, la Rigueur, au cœur de l'Arbre. La sévérité devient justesse : le jugement n'est plus une punition, mais la recherche de l'équilibre. Lamed veut dire l'aiguillon, le bâton du bouvier qui guide l'animal ; c'est la lettre la plus haute de l'alphabet, celle qui s'élève au-dessus de la ligne. La Balance est le signe de l'équilibre entre deux plateaux.","La Golden Dawn place ici La Justice et lui donne le numéro XI. Elle est la conscience qui pèse et qui corrige : elle tranche, mais au service du cœur."], tirage:"La Justice te demande d'être honnête avec toi-même : regarder les faits, peser, assumer les conséquences. Sur ce sentier, l'équilibre ne vient pas d'un compromis mou, mais d'une décision juste."},
  pendu:{voie:"l'Intelligence stable", txt:["Ce sentier descend le pilier de gauche, de Geburah à Hod, en traversant le Voile. Mem est une lettre mère : l'Eau, l'élément qui épouse toutes les formes et dissout ce qui est rigide. La force de Geburah s'y suspend : au lieu d'agir, elle se laisse porter.","Le Pendu est retourné, la tête en bas, les mains dans le dos : il ne peut rien faire, et c'est justement là qu'il comprend. Sur l'Arbre, c'est le sacrifice volontaire, l'abandon qui change le point de vue : ce qui semblait une défaite devient une nouvelle intelligence des choses."], tirage:"Le Pendu conseille d'arrêter de forcer. Accepte la pause, regarde la situation à l'envers : la solution est peut-être dans ce que tu refusais de voir. Sur ce sentier, lâcher prise n'est pas abandonner."},
  sansnom:{voie:"l'Intelligence imaginative", txt:["Ce sentier descend du cœur vers Netzach, le désir, en traversant le Voile. Ce que le cœur a compris doit maintenant transformer les émotions et les attachements. Nun veut dire le poisson, ce qui vit dans les profondeurs. Le Scorpion est le signe de la mort et de la renaissance, de la transformation profonde.","L'Arcane sans nom fauche, mais de la terre noire sortent des pousses neuves. Sur l'Arbre, c'est la mort de l'ancien moi, pour que le désir se purifie et que la vie reprenne sous une autre forme."], tirage:"L'Arcane sans nom annonce une fin nécessaire. Ce qui doit partir partira : laisse-le aller pour faire place au neuf. Sur ce sentier, la transformation fait peur, mais c'est elle qui libère."},
  temperance:{voie:"l'Intelligence probatoire", txt:["Ce sentier descend le pilier du milieu, du cœur à Yesod, l'imaginaire, en traversant le Voile. C'est la voie directe de l'âme vers la personnalité, celle qu'emprunte la conscience quand elle s'unifie. Samekh veut dire l'étai, le soutien. Le Sagittaire est l'archer qui vise loin, le chercheur de sens.","Tempérance verse un liquide d'un vase dans l'autre sans en perdre une goutte : c'est l'alchimie qui unit les contraires, le haut et le bas. Sur l'Arbre, c'est l'épreuve patiente qui mène à l'équilibre intérieur."], tirage:"Tempérance conseille la mesure et la patience. Mélange avec douceur ce qui semble opposé, donne du temps au temps. Sur ce sentier, la guérison vient du dosage juste plutôt que de l'excès."},
  diable:{voie:"l'Intelligence rénovatrice", txt:["Ce sentier descend du cœur vers Hod, l'intellect, en traversant le Voile. C'est là que la pensée peut enfermer le cœur dans ses propres constructions : croyances, peurs, désirs qui deviennent des chaînes. Ayin veut dire l'œil : voir clairement ce qui nous attache. Le Capricorne est le signe de la matière, de l'ambition et de la montagne à gravir.","Le Diable de l'Arbre n'est pas le mal absolu : c'est l'énergie brute, mal dirigée. Ses captifs ont la corde lâche autour du cou. La tradition appelle cette voie « rénovatrice » : reconnaître ses chaînes est le premier pas pour se renouveler."], tirage:"Le Diable te demande de regarder en face ce qui te tient : une habitude, une dépendance, une peur, une ambition. Tu as plus de liberté que tu ne crois. Sur ce sentier, l'énergie qui t'enchaîne peut aussi te porter si tu la reprends en main."},
  maisondieu:{voie:"l'Intelligence active", txt:["C'est le troisième sentier horizontal : il relie Netzach, les émotions, et Hod, l'intellect. Quand le cœur et la tête construisent chacun leur tour sans se parler, la foudre finit par tomber. Peh veut dire la bouche : la parole qui libère ou qui détruit. Mars est l'astre de l'énergie brutale, du combat, de la rupture.","La Maison Dieu est l'effondrement des constructions devenues trop rigides. Ce sentier traverse l'Arbre d'un pilier à l'autre au niveau de la personnalité : quand il s'ouvre, ce qui était faux tombe d'un coup."], tirage:"La Maison Dieu annonce une rupture ou une prise de conscience brusque. Ce qui s'écroule n'était pas solide. Sur ce sentier, la libération passe parfois par le choc : laisse tomber les murs, garde ce qui reste debout."},
  etoile:{voie:"l'Intelligence naturelle", txt:["Ce sentier descend de Netzach, le désir, vers Yesod, l'imaginaire. Après la foudre de la Maison Dieu, le désir s'apaise et devient espérance. Tzaddi veut dire l'hameçon, celui qui pêche dans les eaux profondes ; c'est aussi la lettre du juste, le tsaddik. Le Verseau est le signe du porteur d'eau, de l'idéal et de l'avenir.","L'Étoile verse ses eaux sur la terre et dans le fleuve, nue, confiante : elle ne cache plus rien. Sur l'Arbre, c'est l'inspiration qui vient du plus profond et qui guérit en nourrissant les rêves."], tirage:"L'Étoile t'invite à faire confiance et à te ressourcer. Tes rêves sont légitimes : arrose-les. Sur ce sentier, la générosité envers soi-même ouvre la voie à la générosité envers les autres."},
  lune:{voie:"l'Intelligence corporelle", txt:["Ce sentier descend de Netzach, les émotions, jusqu'à Malkuth, le monde concret. C'est le chemin par lequel les peurs, les rêves et l'instinct s'incarnent dans le corps. Qoph veut dire la nuque, l'arrière de la tête, siège de ce qui agit sans passer par la conscience. Les Poissons sont le signe de l'océan, de la dissolution et de l'intuition.","La Lune éclaire mal : les chiens aboient, l'écrevisse remonte du fond. Sur l'Arbre, c'est la traversée de la nuit, celle où il faut avancer sans tout voir, guidé par l'instinct plutôt que par la raison."], tirage:"La Lune conseille de ne pas prendre tes peurs pour la réalité. Ce qui remonte vient de loin : accueille-le sans t'y noyer. Sur ce sentier, le corps et les rêves savent des choses que la tête ignore."},
  soleil:{voie:"l'Intelligence collective", txt:["Ce sentier relie Hod, l'intelligence, à Yesod, l'imaginaire. La pensée éclaire les profondeurs : ce qui était confus devient clair. Resh veut dire la tête, ou le visage : la conscience qui regarde en face. Le Soleil est l'astre de la lumière, de la vie et de la joie.","Sur la lame, deux enfants se tiennent devant un mur, sous un soleil généreux. C'est la fraternité, la simplicité retrouvée, la conscience qui n'a plus peur d'elle-même. Sur l'Arbre, c'est la lumière qui unifie la personnalité."], tirage:"Le Soleil annonce la clarté, la réussite et la chaleur des liens. Sur ce sentier, ce qui était dans l'ombre devient visible : profite de cette lumière pour comprendre, partager, grandir."},
  jugement:{voie:"l'Intelligence perpétuelle", txt:["Ce sentier descend le pilier de gauche, de Hod à Malkuth. Shin est la troisième lettre mère : le Feu, celui qui purifie et qui éveille ; ses trois branches dessinent une flamme. La parole et la pensée de Hod descendent dans la matière pour la réveiller.","Sur la lame, l'ange sonne la trompette et les êtres se lèvent de leur tombe : c'est l'appel qui ressuscite ce qui dormait. Sur l'Arbre, c'est le premier grand éveil de celui qui commence à monter : entendre l'appel."], tirage:"Le Jugement annonce un appel, une renaissance, une bonne nouvelle. Réponds à ce qui t'appelle depuis longtemps. Sur ce sentier, il est temps de te lever et de te montrer tel que tu es devenu."},
  monde:{voie:"l'Intelligence administrative", txt:["C'est le sentier le plus bas, sur le pilier du milieu, entre Yesod, l'imaginaire, et Malkuth, le monde concret. Quand on descend l'Arbre, c'est le dernier pas, celui où tout s'incarne. Quand on le monte, c'est le premier : passer du monde visible au monde intérieur. Tav est la dernière lettre de l'alphabet, la marque, la signature. Saturne est l'astre du temps, des limites et de l'accomplissement.","Le Monde montre une figure qui danse dans une couronne, entourée des quatre éléments. Sur l'Arbre, elle est à la fois la fin et le seuil : la totalité accomplie, et la porte du voyage intérieur."], tirage:"Le Monde annonce un accomplissement : un cycle se termine bien. Sur ce sentier, la réussite est aussi un commencement : ce que tu as réalisé dans le monde t'ouvre maintenant un autre voyage."}
};
/* L'école française (Lévi, Papus, Wirth) : I = Aleph, et Le Mat entre XX et XXI */
const LETTRES_FR = {bateleur:"א Aleph", papesse:"ב Beth", imperatrice:"ג Gimel", empereur:"ד Daleth", pape:"ה Heh", amoureux:"ו Vav", chariot:"ז Zayin", justice:"ח Cheth", ermite:"ט Teth", roue:"י Yod", force:"כ Kaph", pendu:"ל Lamed", sansnom:"מ Mem", temperance:"נ Nun", diable:"ס Samekh", maisondieu:"ע Ayin", etoile:"פ Peh", lune:"צ Tzaddi", soleil:"ק Qoph", jugement:"ר Resh", mat:"ש Shin", monde:"ת Tav"};
const MERES = ["mat","pendu","jugement"], DOUBLES = ["bateleur","papesse","imperatrice","roue","maisondieu","soleil","monde"];
const lettreType = id => MERES.includes(id) ? "lettre mère" : DOUBLES.includes(id) ? "lettre double" : "lettre simple";
const lettreFamille = id => MERES.includes(id) ? "Une des trois lettres mères, qui donnent les éléments" : DOUBLES.includes(id) ? "Une des sept lettres doubles, qui donnent les planètes" : "Une des douze lettres simples, qui donnent les signes du zodiaque";
const PATH_ORDER = CARDS.map(c => c.id).sort((a,b) => LORE[a].gd.p - LORE[b].gd.p);

/* La forme d'un sentier, déduite de sa place sur l'Arbre */
const aFr = x => x.startsWith("le ") ? "au " + x.slice(3) : x.startsWith("les ") ? "aux " + x.slice(4) : "à " + x;
const deFr = fr => fr.startsWith("le ") ? "du " + fr.slice(3) : "de " + fr;
function sentierForme(id){
  const g = LORE[id].gd, A = SEFIROT[g.de], B = SEFIROT[g.to], [xa,ya] = TREE_POS[g.de], [xb,yb] = TREE_POS[g.to];
  let f;
  if(ya === yb) f = `C'est un sentier horizontal : il relie deux sefirot de même hauteur, sur deux piliers opposés. Il parle d'un équilibre à trouver entre ${A.fr} et ${B.fr}.`;
  else if(A.pil === B.pil) f = `C'est un sentier vertical, sur ${PILIERS[A.pil]} : la même qualité descend d'un étage, ${deFr(A.fr)} vers ${B.fr}.`;
  else f = `C'est un sentier en diagonale : il passe ${PILIERS[A.pil].replace(/^le /,"du ")} ${PILIERS[B.pil].replace(/^le /,"au ")}, ${deFr(A.fr)} vers ${B.fr}.`;
  const b = bandeOf(id);
  const pass = b === 1 ? " Il traverse l'Abîme, le vide qui sépare le monde de l'esprit du reste de l'Arbre." : b === 3 ? " Il traverse le Voile, la frontière entre l'âme et la personnalité." : "";
  return f + pass;
}

/* ---------- Affichage de l'Arbre ---------- */
const as = { sel:"tiphareth", kind:"sef", step:0 };
const TX = x => 24 + (x - 14) * 3.33, TY = y => 26 + (y - 8) * 3.05;
const PATH_T = {temperance:.38};
const pathMid = id => { const g = LORE[id].gd, [x1,y1] = TREE_POS[g.de], [x2,y2] = TREE_POS[g.to], t = PATH_T[id] || .5; return [TX(x1) + (TX(x2)-TX(x1))*t, TY(y1) + (TY(y2)-TY(y1))*t]; };
/* opts.mode : "explore" (interactif) ou une étape du guide ("all","sef","pil","etages","voies") */
function bigTreeSVG(opts = {mode:"explore"}){
  const mode = opts.mode, inter = mode === "explore";
  let deco = "", lines = "", labels = "", nodes = "";
  if(mode === "etages"){
    const band = (y1, y2, cls) => `<rect x="0" y="${y1}" width="288" height="${y2-y1}" rx="14" class="atb ${cls}"/>`;
    deco += band(TY(8)-30, TY(26)+30, "atb0") + band(TY(62)-30, TY(80)+30, "atb1") + band(TY(112)-30, TY(130)+30, "atb2") + band(TY(160)-30, TY(160)+30, "atb3");
    deco += `<line x1="4" x2="284" y1="${TY(44)}" y2="${TY(44)}" class="atveil"/><text x="144" y="${TY(44)-6}" class="atveil-t">l'Abîme</text>`;
    deco += `<line x1="4" x2="284" y1="${TY(97)}" y2="${TY(97)}" class="atveil"/><text x="252" y="${TY(97)-6}" class="atveil-t">le Voile</text>`;
  }
  if(mode === "pil"){
    [["gauche",14,"Rigueur"],["milieu",50,"Équilibre"],["droit",86,"Clémence"]].forEach(([k,x,l]) => {
      deco += `<rect x="${TX(x)-31}" y="8" width="62" height="514" rx="31" class="atp atp-${k}"/><text x="${TX(x)}" y="538" class="atp-t">${l}</text>`; });
  }
  CARDS.forEach(c => {
    const g = LORE[c.id].gd, [x1,y1] = TREE_POS[g.de], [x2,y2] = TREE_POS[g.to], [mx,my] = pathMid(c.id);
    const on = inter && (as.kind === "path" ? as.sel === c.id : (g.de === as.sel || g.to === as.sel));
    lines += `<line x1="${TX(x1)}" y1="${TY(y1)}" x2="${TX(x2)}" y2="${TY(y2)}" class="ap-line${on?" on":""}${mode==="voies"?" lit":""}"/>`;
    if(inter) labels += `<g class="ap-lab${on?" on":""}${as.kind==="path"&&as.sel===c.id?" sel":""}" data-ap="${c.id}" tabindex="0" role="button" aria-label="Sentier ${g.p}, ${g.n}, ${c.nom}"><line x1="${TX(x1)}" y1="${TY(y1)}" x2="${TX(x2)}" y2="${TY(y2)}" class="ap-hit"/><circle cx="${mx}" cy="${my}" r="11"/><text x="${mx}" y="${my+4.2}" class="heb" lang="he">${g.l}</text></g>`;
    else if(mode === "voies") labels += `<g class="ap-lab on"><circle cx="${mx}" cy="${my}" r="12.5"/><text x="${mx}" y="${my+4.2}" class="ap-rom">${c.n ? ROMAN[c.n] : "0"}</text></g>`;
  });
  Object.entries(SEFIROT).forEach(([k,S]) => { const [x,y] = TREE_POS[k], X = TX(x), Y = TY(y), on = inter && as.kind==="sef" && as.sel===k, hi = mode === "sef";
    const attrs = inter ? ` data-as="${k}" tabindex="0" role="button" aria-label="Sefira ${S.n}, ${S.nom}, ${S.fr}"` : "";
    nodes += `<g class="as-node as-${S.pil}${on||hi?" sel":""}"${attrs}><circle cx="${X}" cy="${Y}" r="25"/><text x="${X}" y="${Y-3}" class="as-n">${S.n}</text><text x="${X}" y="${Y+9}" class="as-t">${S.nom}</text></g>`; });
  const daath = `<circle cx="${TX(50)}" cy="${TY(44)}" r="13" class="as-daath"/>`;
  return `<svg viewBox="0 0 288 ${mode==="pil" ? 546 : 522}" class="atree${inter?"":" atree-mini"}" role="${inter?"group":"img"}" aria-label="${inter ? "L'Arbre de Vie : touche une sefira ou un sentier" : "L'Arbre de Vie"}">${deco}${daath}${lines}${labels}${nodes}</svg>`;
}

/* ---------- Le guide en cinq étapes ---------- */
const GUIDE = [
  {mode:"all", t:"Une carte de l'être", p:["Imagine une carte : dix villes reliées par vingt-deux routes. L'Arbre de Vie est une carte de ce genre, venue de la Kabbale, la tradition mystique juive. Il décrit comment l'infini se manifeste jusqu'au monde concret, et, dans l'autre sens, comment un être humain peut remonter vers sa source.","Les villes s'appellent des <em>sefirot</em> (au singulier, une sefira). Les routes s'appellent des <em>sentiers</em>. Depuis le XIXe siècle, les occultistes posent une lame du tarot sur chaque sentier : les 22 arcanes majeurs deviennent ainsi 22 étapes d'un voyage intérieur."]},
  {mode:"sef", t:"Les dix sefirot", p:["Chaque sefira est une qualité : la Couronne (1), la Sagesse (2), l'Intelligence (3), la Clémence (4), la Rigueur (5), la Beauté (6), la Victoire (7), la Gloire (8), le Fondement (9) et le Royaume (10).","On les numérote du haut vers le bas, dans l'ordre où l'énergie descend. En haut, l'unité et le sens ; en bas, le corps et la matière. Entre les deux, toute la vie intérieure : la générosité et la fermeté, le cœur, les émotions, la pensée, les rêves."]},
  {mode:"pil", t:"Les trois piliers", p:["L'Arbre se lit aussi en colonnes. À droite, le pilier de la Clémence : ce qui donne, s'étend et s'élance. À gauche, le pilier de la Rigueur : ce qui limite, structure et retient. Au milieu, le pilier de l'Équilibre, qui unit les deux.","Aucun des deux côtés n'est « bon » ou « mauvais » : trop de clémence disperse, trop de rigueur étouffe. Toute la sagesse de l'Arbre est de les accorder, et c'est pourquoi le cœur, Tiphareth, est au centre."]},
  {mode:"etages", t:"Les quatre mondes", p:["De haut en bas, l'Arbre traverse quatre mondes : l'esprit (les grands principes), l'âme (l'éthique et le cœur), la personnalité (émotions, pensée, rêves) et le monde concret.","Deux frontières les séparent : l'Abîme, sous les trois sefirot du haut, et le Voile, sous le cœur. Une lame qui traverse l'une de ces frontières parle toujours d'un passage important."]},
  {mode:"voies", t:"Descendre et monter", p:["Les 22 sentiers sont numérotés de 11 à 32 (les numéros 1 à 10 sont ceux des sefirot). Le Mat ouvre le sentier 11, tout en haut ; Le Monde ferme le sentier 32, tout en bas.","On peut lire l'Arbre dans les deux sens. En descendant, c'est la création qui prend forme, de l'idée au monde. En montant, c'est le chemin de celui qui cherche : on part du Monde, on traverse la Lune, le Jugement, le Soleil… jusqu'au Mat, l'esprit libre. Touche maintenant l'Arbre ci-dessous pour explorer chaque lame."]}
];
function guideHTML(){
  const s = GUIDE[as.step];
  return `<div class="ag-tree">${bigTreeSVG({mode:s.mode})}</div>
    <div class="ag-txt"><p class="eyebrow">Étape ${as.step+1} sur ${GUIDE.length}</p><h2 class="ag-h">${s.t}</h2>${s.p.map(p=>`<p>${p}</p>`).join("")}
      ${s.mode==="etages" ? `<ul class="ag-legend">${ETAGES.map((e,i)=>`<li><span class="ag-sw atb${i}"></span><strong>${e.t}</strong> · ${e.d}</li>`).join("")}</ul>` : ""}
      <div class="ag-nav"><button type="button" class="btn ghost" data-ag="-1" ${as.step===0?"disabled":""}>← Précédent</button>
        <span class="ag-dots" aria-hidden="true">${GUIDE.map((_,i)=>`<span class="${i===as.step?"on":""}"></span>`).join("")}</span>
        ${as.step < GUIDE.length-1 ? `<button type="button" class="btn" data-ag="1">Suivant →</button>` : `<button type="button" class="btn" data-ag-go>Explorer l'Arbre ↓</button>`}</div></div>`;
}

/* ---------- Le panneau d'exploration ---------- */
function arbrePanelHTML(){
  if(as.kind === "sef"){
    const S = SEFIROT[as.sel], ps = CARDS.filter(c => { const g = LORE[c.id].gd; return g.de===as.sel || g.to===as.sel; });
    return `<p class="eyebrow">Sefira ${S.n} · ${PILIERS[S.pil]} · ${ETAGES[S.et].t.toLowerCase()}</p><h3>${S.nom}, ${S.fr}</h3>
      <p>${S.txt}</p>
      <div class="ap-box"><p><strong>Dans ta vie :</strong> ${S.vie}</p><p><strong>La question à te poser :</strong> ${S.q}</p></div>
      <p class="ap-meta"><span>Astre : ${S.astre}</span><span>Arcanes mineurs : les ${["As","Deux","Trois","Quatre","Cinq","Six","Sept","Huit","Neuf","Dix"][S.n-1]}</span></p>
      <p class="help">Les quatre ${S.n === 1 ? "As" : RANKS[S.n]} du jeu vivent ici, un par élément :</p>
      <div class="ap-cards ap-min">${SUIT_ORDER.map(s => { const m = byId(s + S.n); return `<button type="button" class="ap-card" data-sheet="${m.id}"><span class="ap-card-art">${cardSVG(m)}</span><span>${m.nom}</span></button>`; }).join("")}</div>
      <p class="help">${ps.length} sentiers la relient au reste de l'Arbre. Touche une lame pour la découvrir :</p>
      <div class="ap-cards">${ps.map(c => `<button type="button" class="ap-card" data-ap="${c.id}"><span class="ap-card-art">${cardSVG(c)}</span><span>${LORE[c.id].gd.l} ${c.nom}</span></button>`).join("")}</div>`;
  }
  const c = byId(as.sel), g = LORE[c.id].gd, A = SEFIROT[g.de], B = SEFIROT[g.to], V = VOIES[c.id], i = PATH_ORDER.indexOf(c.id);
  const prev = PATH_ORDER[i-1], next = PATH_ORDER[i+1];
  return `<div class="ap-top"><button type="button" class="ap-big" data-sheet="${c.id}" aria-label="Ouvrir la fiche ${c.nom}">${cardSVG(c)}</button>
      <div><p class="eyebrow">Sentier ${g.p} sur 32 · ${BANDES[bandeOf(c.id)].t.toLowerCase()}</p><h3>${c.nom}</h3>
      <p class="ap-heb"><span class="heb" lang="he">${g.l}</span> ${g.n}, ${g.s}</p>
      <p class="ap-meta"><span>${g.a.charAt(0).toUpperCase()+g.a.slice(1)}</span><span>${lettreType(c.id)}</span></p></div></div>
    <div class="ap-sec"><h4>Sa place sur l'Arbre</h4><p>Le sentier relie <button type="button" class="linkbtn" data-as="${g.de}">${A.nom}, ${A.fr}</button> (${A.n}) à <button type="button" class="linkbtn" data-as="${g.to}">${B.nom}, ${B.fr}</button> (${B.n}). ${sentierForme(c.id)}</p>
      <p class="help">Son titre traditionnel : ${V.voie}.</p></div>
    <div class="ap-sec"><h4>Sa signification</h4>${V.txt.map(p=>`<p>${p}</p>`).join("")}</div>
    <div class="ap-sec"><h4>La lettre ${g.n}</h4><p>${lettreFamille(c.id)}. Son nom veut dire ${g.s} ; ici, elle est associée ${aFr(g.a)}. Dans l'école française (Lévi, Wirth), cette lame reçoit une autre lettre : ${LETTRES_FR[c.id]}.</p></div>
    <div class="ap-box"><h4>Quand elle sort dans un tirage</h4><p>${V.tirage}</p></div>
    <div class="ap-nav">${prev ? `<button type="button" class="btn ghost" data-ap="${prev}">← ${byId(prev).nom}</button>` : "<span></span>"}<button type="button" class="linkbtn" data-sheet="${c.id}">Fiche complète</button>${next ? `<button type="button" class="btn ghost" data-ap="${next}">${byId(next).nom} →</button>` : "<span></span>"}</div>`;
}

function arbreHTML(){
  const rows = CARDS.map(c => { const g = LORE[c.id].gd, A = SEFIROT[g.de], B = SEFIROT[g.to];
    return `<tr><td><button type="button" class="linkbtn" data-ap="${c.id}">${c.n?ROMAN[c.n]:"0"} · ${c.nom}</button></td><td><span class="heb" lang="he">${g.l}</span> ${g.n}</td><td>${g.a}</td><td>${g.p} : ${A.nom} – ${B.nom}</td><td>${LETTRES_FR[c.id]}</td></tr>`; }).join("");
  /* Sur téléphone, le tableau devient une liste de cartes : toutes les colonnes restent visibles */
  const items = CARDS.map(c => { const g = LORE[c.id].gd, A = SEFIROT[g.de], B = SEFIROT[g.to];
    return `<li><button type="button" class="ar-li" data-ap="${c.id}"><span class="ar-li-n">${c.n?ROMAN[c.n]:"0"}</span><span class="ar-li-b"><span class="ar-li-t">${c.nom}</span>
      <span class="ar-li-d"><span class="heb" lang="he">${g.l}</span> ${g.n} · ${g.a}</span><span class="ar-li-d">Sentier ${g.p} : ${A.nom} – ${B.nom}</span><span class="ar-li-d">École française : ${LETTRES_FR[c.id]}</span></span><span class="ar-li-go" aria-hidden="true">›</span></button></li>`; }).join("");
  return `${subtabsHTML("arbre")}<header class="sec-head"><h1>L'Arbre de Vie</h1><p>Dix sefirot, vingt-deux sentiers, vingt-deux lames. Commence par le guide en cinq étapes, puis explore l'Arbre lame par lame : chaque arcane y a sa place, son chemin et son sens.</p>${DECK_ID === "et" ? `<p class="help">Etteilla n'a pas relié ses cartes à l'Arbre de Vie : cette lecture vient de l'occultisme du XIXe siècle. Arcanes place chaque carte du Grand Etteilla sur le sentier de son équivalent au Marseille, et les textes de l'Arbre parlent de ces arcanes.</p>` : ""}</header>
  ${stocHTML("Sommaire de l'Arbre de Vie", [["ar-guide","Comprendre en 5 étapes"],["ar-tree","Explorer l'Arbre"],["ar-bandes","Les 22 lames"],["ar-montee","La montée"],["ar-quoi","Origines"],["ar-lettres","Les lettres"],["ar-table","Le tableau"],["ar-ecoles","Deux écoles"],["ar-lire","Pour lire"]])}
  <section class="ar-guide" id="ar-guide" aria-live="polite">${guideHTML()}</section>
  <h2 class="lsub" id="ar-tree-h">Explorer l'Arbre</h2>
  <section class="ar-explore" id="ar-tree">
    <div class="ar-svg">${bigTreeSVG()}<p class="help">Touche une sefira (les cercles) ou un sentier (les lettres hébraïques).</p></div>
    <div class="ar-panel" id="ar-panel" aria-live="polite">${arbrePanelHTML()}</div>
  </section>
  <div class="ar-train" role="note"><div><p class="eyebrow">S'entraîner</p><p class="ar-train-h">Place la lame sur l'Arbre</p><p class="help">Le quiz te montre une lame, tu touches son sentier. Le meilleur moyen de retenir l'Arbre.</p></div><button type="button" class="btn" data-go-placer>Commencer</button></div>
  <section class="ar-text" id="ar-bandes"><h2 class="lsub">Les 22 lames, de haut en bas</h2>
    <p>Pour s'y retrouver, on peut ranger les sentiers en six bandes, du monde de l'esprit jusqu'au monde concret. Touche une lame pour voir sa place sur l'Arbre et son explication complète.</p>
    ${BANDES.map((b,i) => `<div class="ar-bande${i%2?" cross":""}"><div class="ar-bande-h"><h3>${b.t}</h3><p>${b.d}</p></div><div class="ar-bande-c">${b.ids.map(id => { const c = byId(id), g = LORE[id].gd;
      return `<button type="button" class="ar-bc" data-ap="${id}"><span class="ar-bc-art">${cardSVG(c)}</span><span class="ar-bc-t">${c.nom}</span><span class="ar-bc-d"><span class="heb" lang="he">${g.l}</span> sentier ${g.p}</span></button>`; }).join("")}</div></div>`).join("")}</section>
  <section class="ar-text ar-montee" id="ar-montee" aria-live="polite">${monteeHTML()}</section>
  <section class="ar-text" id="ar-quoi"><h2 class="lsub">D'où vient l'Arbre de Vie</h2>
    <p>L'Arbre de Vie est un schéma de la Kabbale, la tradition mystique juive. Il représente les dix <em>sefirot</em>, les émanations par lesquelles l'infini (l'<em>Ein Sof</em>) se manifeste, depuis la Couronne jusqu'au Royaume. Ses racines textuelles sont le <em>Sefer Yetsirah</em>, le Livre de la Formation, un court traité ancien qui décrit la création par les dix nombres et les vingt-deux lettres de l'alphabet hébreu, puis le <em>Zohar</em>, rédigé en Espagne à la fin du XIIIe siècle.</p>
    <p>Le dessin utilisé ici, avec ses sentiers numérotés de 11 à 32, est celui que le jésuite Athanase Kircher publie en 1652 ; la Golden Dawn le reprend à la fin du XIXe siècle. Il existe d'autres agencements, plus anciens, dans la Kabbale juive.</p>
    <p>Le rapprochement avec le tarot vient d'une coïncidence que les occultistes ont trouvée trop belle : vingt-deux lettres, vingt-deux arcanes majeurs. Le comte de Mellet l'esquisse dès 1781, dans le livre de Court de Gébelin ; Éliphas Lévi l'établit en 1856, et la Golden Dawn en fait un système complet en 1888. <strong>Les cartiers qui ont dessiné le Marseille ne pensaient pas à la Kabbale</strong> : c'est une grille de lecture ajoutée au XIXe siècle, riche et cohérente, mais pas l'origine des cartes.</p>
    <p class="help">Entre la Couronne et le cœur s'ouvre une sefira cachée, Daath, la Connaissance, que l'on ne compte pas parmi les dix : c'est le cercle en pointillés sur l'Arbre.</p></section>
  <section class="ar-text" id="ar-lettres"><h2 class="lsub">Les vingt-deux lettres : mères, doubles et simples</h2>
    <p>Le <em>Sefer Yetsirah</em> classe les lettres en trois familles, et la Golden Dawn en déduit le rôle de chaque arcane.</p>
    <div class="ar-cols">
      <div class="ar-col"><h3>3 lettres mères, les éléments</h3><p>Aleph (l'Air), Mem (l'Eau) et Shin (le Feu). Elles vont au Mat, au Pendu et au Jugement : trois lames de passage, de suspension et d'éveil.</p></div>
      <div class="ar-col"><h3>7 lettres doubles, les planètes</h3><p>Beth, Gimel, Daleth, Kaph, Peh, Resh et Tav, qui ont deux prononciations. Elles vont au Bateleur (Mercure), à la Papesse (la Lune), à l'Impératrice (Vénus), à la Roue (Jupiter), à la Maison Dieu (Mars), au Soleil et au Monde (Saturne).</p></div>
      <div class="ar-col"><h3>12 lettres simples, les signes</h3><p>Les douze autres lettres vont aux douze signes du zodiaque, du Bélier (L'Empereur) aux Poissons (La Lune). Ce sont les lames de l'expérience humaine : choisir, avancer, juger, se transformer.</p></div>
    </div></section>
  <section class="ar-text" id="ar-table"><h2 class="lsub">Le tableau des correspondances</h2>
    <p class="help">Lettre, astre et sentier selon la Golden Dawn ; dernière colonne : la lettre de l'école française.</p>
    <div class="ar-tablewrap"><table class="ar-tab"><thead><tr><th>Lame</th><th>Lettre</th><th>Astre ou élément</th><th>Sentier</th><th>École française</th></tr></thead><tbody>${rows}</tbody></table></div>
    <ul class="ar-list" aria-label="Les correspondances, lame par lame">${items}</ul></section>
  <section class="ar-text" id="ar-ecoles"><h2 class="lsub">Deux écoles, deux attributions</h2>
    <div class="ar-cols">
      <div class="ar-col"><h3>L'école française</h3><p>Éliphas Lévi (1856), puis Papus et Oswald Wirth, donnent Aleph au Bateleur, la première lame numérotée, et suivent l'ordre des nombres. Le Mat, sans numéro, reçoit Shin et se place entre le Jugement et le Monde. C'est l'attribution des lettres imprimées sur le tarot de Wirth.</p></div>
      <div class="ar-col"><h3>L'école anglaise</h3><p>La Golden Dawn (1888) donne Aleph au Mat, le zéro, avant le Bateleur, et place chaque lame sur un sentier de l'Arbre. Elle échange La Force (VIII) et La Justice (XI) pour suivre l'ordre des signes, Lion puis Balance. Waite et Crowley la reprennent ; c'est celle qu'utilise Arcanes pour l'Arbre et les fiches.</p></div>
    </div>
    <p>Aucune des deux n'est « la vraie » : ce sont deux systèmes cohérents, nés de la même intuition. Crowley y ajoutera encore une variante en échangeant les lettres de l'Empereur et de l'Étoile.</p></section>
  <section class="ar-text" id="ar-lire"><h2 class="lsub">Lire le tarot avec l'Arbre</h2>
    <p>L'Arbre ne remplace pas la lecture des images : il ajoute une profondeur. Une lame posée sur un sentier dit <strong>ce qui relie deux forces</strong> de ta vie. Le Chariot, entre Binah et Geburah, est la volonté qui donne une direction à ce que l'on a compris ; L'Étoile, entre Netzach et Yesod, est l'espoir qui nourrit l'imaginaire.</p>
    <p>Trois questions simples pour lire une lame avec l'Arbre : <strong>où est-elle ?</strong> (dans quel monde, sur quel pilier) ; <strong>que relie-t-elle ?</strong> (les deux sefirot de son sentier) ; <strong>dans quel sens va-t-elle ?</strong> (descendre, c'est réaliser ; monter, c'est comprendre).</p>
    <p>Dans la Golden Dawn, les dix sefirot correspondent aussi aux cartes numérotées des arcanes mineurs, de l'As (Kether) au Dix (Malkuth), et les figures aux quatre mondes de la Kabbale. Arcanes les ajoutera avec les mineurs.</p>
    <p><button type="button" class="btn" id="ar-tirer">Faire le tirage de l'Arbre de Vie</button> <button type="button" class="btn ghost" data-sub="chemin">${DECK_ID === "et" ? "Le chemin d'Etteilla" : "Le chemin du Mat"}</button></p>
    <p class="help">Sources : Gershom Scholem, <em>Les Grands Courants de la mystique juive</em> ; William Wynn Westcott, <em>Sepher Yetzirah</em> (1887) ; Éliphas Lévi, <em>Dogme et rituel de la haute magie</em> ; Israel Regardie, <em>The Golden Dawn</em> ; Ronald Decker et Michael Dummett, <em>A History of the Occult Tarot</em>.</p></section>`;
}

function bindArbre(root){
  const scrollPanel = () => { const p = window.innerWidth <= 900 ? $("#ar-panel") : $("#ar-tree"); if(p) p.scrollIntoView({block:"start", behavior: reduceMotion() ? "auto" : "smooth"}); };
  const upd = (scroll) => { $("#ar-panel").innerHTML = deckText(arbrePanelHTML()); root.querySelector("#ar-tree .ar-svg svg").outerHTML = deckText(bigTreeSVG()); bindArbreDyn(root); if(scroll) scrollPanel(); };
  root._arbreUpd = upd;
  const bindGuide = () => {
    root.querySelectorAll("[data-ag]").forEach(b => b.onclick = () => { as.step = Math.max(0, Math.min(GUIDE.length-1, as.step + Number(b.dataset.ag))); $("#ar-guide").innerHTML = deckText(guideHTML()); bindGuide(); applyGloss($("#ar-guide")); });
    const go = root.querySelector("[data-ag-go]"); if(go) go.onclick = () => document.getElementById("ar-tree-h").scrollIntoView({block:"start", behavior: reduceMotion() ? "auto" : "smooth"});
  };
  bindGuide(); bindArbreDyn(root);
  root.querySelectorAll("#ar-table [data-ap], #ar-bandes [data-ap]").forEach(b => b.onclick = () => openArbreSheet(b.dataset.ap));
  const t = $("#ar-tirer"); if(t) t.onclick = () => { state.spread = "arbre"; state.step = "setup"; setView("tirer"); window.scrollTo({top:0}); };
  const pl = root.querySelector("[data-go-placer]"); if(pl) pl.onclick = startPlacer;
  bindMontee(); bindSheetLinks(root); bindStoc(root); applyGloss(root);
}
/* La place d'une lame dans l'Arbre, ouverte en fenêtre depuis le tableau ou les bandes :
   on reste là où on lisait, et l'Arbre explorable derrière suit la sélection. */
function openArbreSheet(id){
  const sh = $("#sheet"), root = $("#v-lames");
  as.kind = "path"; as.sel = id;
  if(state.view === "lames" && lamesSub === "arbre" && root && root._arbreUpd && $("#ar-panel")) root._arbreUpd(false);
  sh.querySelector(".sheet-body").innerHTML = deckText(`<p class="eyebrow">L'Arbre de Vie</p>
    <div class="ash"><div class="ash-tree">${bigTreeSVG({mode:"explore"})}<p class="help">Le sentier en couleur est celui de la lame. Touche un autre sentier ou une sefira pour changer.</p></div>
    <div class="ash-txt">${arbrePanelHTML()}</div></div>
    <p class="ash-go"><button type="button" class="btn ghost" data-ash-tree>Voir dans le grand Arbre</button></p>`);
  const toTree = (kind, sel) => { as.kind = kind; as.sel = sel; closeSheet();
    if(state.view === "lames" && lamesSub === "arbre" && root && root._arbreUpd && $("#ar-panel")) root._arbreUpd(false);
    else { lamesSub = "arbre"; if(state.view === "lames") renderLames(); else setView("lames"); }
    const p = window.innerWidth <= 900 ? $("#ar-panel") : document.getElementById("ar-tree-h"); if(p) p.scrollIntoView({block:"start"}); };
  sh.querySelectorAll("[data-ap]").forEach(el => { const go = () => openArbreSheet(el.dataset.ap); el.onclick = go; el.onkeydown = e => { if(e.key === "Enter" || e.key === " "){ e.preventDefault(); go(); } }; });
  sh.querySelectorAll("[data-as]").forEach(el => { const go = () => toTree("sef", el.dataset.as); el.onclick = go; el.onkeydown = e => { if(e.key === "Enter" || e.key === " "){ e.preventDefault(); go(); } }; });
  sh.querySelectorAll("[data-sheet]").forEach(b => b.onclick = () => openSheet(b.dataset.sheet));
  sh.querySelector("[data-ash-tree]").onclick = () => toTree("path", id);
  applyGloss(sh.querySelector(".sheet-body"));
  sh.hidden = false; document.body.classList.add("locked");
  sh.querySelector(".sheet-panel").scrollTop = 0;
  sh.querySelector(".sheet-close").focus();
}
function bindArbreDyn(root){
  const upd = root._arbreUpd;
  root.querySelectorAll("#ar-tree [data-ap]").forEach(el => { const fromPanel = !!el.closest("#ar-panel"); const go = () => { as.kind = "path"; as.sel = el.dataset.ap; upd(fromPanel || window.innerWidth <= 900); };
    el.onclick = go; el.onkeydown = e => { if(e.key === "Enter" || e.key === " "){ e.preventDefault(); go(); } }; });
  root.querySelectorAll("#ar-tree [data-as]").forEach(el => { const fromPanel = !!el.closest("#ar-panel"); const go = () => { as.kind = "sef"; as.sel = el.dataset.as; upd(fromPanel || window.innerWidth <= 900); };
    el.onclick = go; el.onkeydown = e => { if(e.key === "Enter" || e.key === " "){ e.preventDefault(); go(); } }; });
  bindSheetLinks($("#ar-panel")); applyGloss($("#ar-panel"));
}

/* ---------- Un Arbre « marqué » : sentiers colorés et numérotés (montée, tirage, quiz) ----------
   o.cls[id] : classe du sentier (done, next, hi, ok, ko) ; o.lab[id] : texte dans son cercle ;
   o.hit(id) : attributs qui rendent le sentier touchable, ou "" ; o.label : description pour les lecteurs d'écran. */
function markTreeSVG(o = {}){
  const cls = o.cls || {}, lab = o.lab || {};
  let lines = "", marks = "", nodes = "";
  CARDS.forEach(c => {
    const g = LORE[c.id].gd, [x1,y1] = TREE_POS[g.de], [x2,y2] = TREE_POS[g.to], [mx,my] = pathMid(c.id), k = cls[c.id] || "", L = lab[c.id], hit = o.hit ? o.hit(c.id) : "";
    const seg = `x1="${TX(x1)}" y1="${TY(y1)}" x2="${TX(x2)}" y2="${TY(y2)}"`;
    lines += `<line ${seg} class="ap-line mk-${k||"no"}"/>`;
    if(hit) marks += `<g class="mk-hit mk-${k||"no"}" ${hit}><line ${seg} class="ap-hit"/><circle cx="${mx}" cy="${my}" r="${L ? 11 : 7.5}"/>${L ? `<text x="${mx}" y="${my+3.6}" class="mk-t">${L}</text>` : ""}</g>`;
    else if(L) marks += `<g class="mk-lab mk-${k||"no"}"><circle cx="${mx}" cy="${my}" r="11"/><text x="${mx}" y="${my+3.6}" class="mk-t">${L}</text></g>`;
  });
  Object.entries(SEFIROT).forEach(([key,S]) => { const [x,y] = TREE_POS[key], X = TX(x), Y = TY(y);
    nodes += `<g class="as-node as-${S.pil}"><circle cx="${X}" cy="${Y}" r="25"/><text x="${X}" y="${Y-3}" class="as-n">${S.n}</text><text x="${X}" y="${Y+9}" class="as-t">${S.nom}</text></g>`; });
  return `<svg viewBox="0 0 288 522" class="atree atree-mini atree-mark" role="${o.hit ? "group" : "img"}" aria-label="${esc(o.label || "L'Arbre de Vie")}"><circle cx="${TX(50)}" cy="${TY(44)}" r="13" class="as-daath"/>${lines}${nodes}${marks}</svg>`;
}
const listFR = a => a.length < 2 ? (a[0] || "") : a.slice(0,-1).join(", ") + " et " + a[a.length-1];
const BANDE_LIEU = ["dans le monde de l'esprit", "à travers l'Abîme, de l'esprit vers l'âme", "dans le monde de l'âme", "à travers le Voile, de l'âme vers la personnalité", "dans le monde de la personnalité", "vers le monde concret"];

/* ---------- La montée de l'Arbre : 22 étapes, du Monde (sentier 32) au Mat (sentier 11) ---------- */
const MONTEE = [...PATH_ORDER].reverse();
let monteeConfirm = false;
function monteeHTML(){
  const M = learn.montee || {}, n = MONTEE.filter(id => M[id]).length, next = MONTEE.find(id => !M[id]);
  const doneToday = Object.values(M).some(x => x && x.d === todayKey());
  const cls = {}, lab = {}; MONTEE.forEach(id => { if(M[id]) cls[id] = "done"; }); if(next){ cls[next] = "next"; lab[next] = byId(next).n ? ROMAN[byId(next).n] : "0"; }
  const tree = markTreeSVG({cls, lab, label:`Ta montée de l'Arbre : ${n} sentier${n>1?"s":""} sur 22`,
    hit: id => M[id] || id === next ? `data-arbre-sheet="${id}" tabindex="0" role="button" aria-label="${esc(`Sentier ${LORE[id].gd.p}, ${byId(id).nom}`)}"` : ""});
  let step;
  if(next){
    const c = byId(next), g = LORE[next].gd, from = SEFIROT[g.to], to = SEFIROT[g.de];
    step = `<div class="mt-step"><div class="mt-art">${cardSVG(c)}</div><div class="mt-body">
      <p class="eyebrow">Étape ${n+1} sur 22 · sentier ${g.p}</p><h3>${c.nom}</h3>
      <p>Tu montes de ${from.nom}, ${from.fr}, vers ${to.nom}, ${to.fr}, ${BANDE_LIEU[bandeOf(next)]}.</p>
      <ol class="mt-ex"><li><button type="button" class="linkbtn" data-arbre-sheet="${next}">Lis le sentier ${deNom(c.nom)}</button> : sa place, son sens, sa lettre.</li>
        <li>Regarde la lame une minute, sans rien chercher. Note le détail qui t'attire.</li>
        <li>Réponds par écrit à la question de l'étape : <strong>« ${to.q} »</strong></li></ol>
      <label class="mt-lab" for="mt-note">Ce que je retiens (facultatif, gardé sur ce téléphone)</label>
      <textarea id="mt-note" rows="3" maxlength="600" placeholder="Un mot, une image, une réponse…"></textarea>
      ${doneToday ? `<p class="help">Tu as déjà gravi un sentier aujourd'hui. L'Arbre se monte mieux lentement, une étape par jour, mais tu peux continuer si tu le veux.</p>` : ""}
      <div class="actions"><button type="button" class="btn" id="mt-ok">Valider l'étape ${n+1}</button></div></div></div>`;
  } else {
    step = `<div class="mt-end"><h3>Tu as gravi tout l'Arbre</h3><p>Du Monde jusqu'au Mat, tu as parcouru les vingt-deux sentiers. La tradition dit que le voyage recommence alors, mais qu'on ne le refait jamais de la même façon : relis tes notes, et regarde ce qui a changé.</p></div>`;
  }
  const list = MONTEE.filter(id => M[id]).map(id => { const c = byId(id), e = M[id];
    const when = e.t ? new Date(e.t).toLocaleDateString("fr-FR", {day:"numeric", month:"long"}) : "";
    return `<li><button type="button" class="linkbtn" data-arbre-sheet="${id}">${c.n ? ROMAN[c.n] : "0"} · ${c.nom}</button>${when ? ` <span class="mt-when">${when}</span>` : ""}${e.note ? `<p class="mt-note">${esc(e.note)}</p>` : ""}</li>`; }).join("");
  return `<h2 class="lsub">La montée de l'Arbre</h2>
    <p>Un parcours en vingt-deux étapes, du Monde, en bas de l'Arbre, jusqu'au Mat, tout en haut : le chemin de celui qui cherche, tel que le décrit la Golden Dawn. Une étape par jour : lire le sentier, regarder la lame, répondre à une question.</p>
    <div class="mt-grid"><div class="mt-tree">${tree}<p class="mt-count"><strong>${n}</strong> / 22 sentiers</p><div class="mt-bar" role="progressbar" aria-label="Progression de la montée" aria-valuemin="0" aria-valuemax="22" aria-valuenow="${n}"><span style="width:${Math.round(n/22*100)}%"></span></div></div>
      <div>${step}
      ${n ? `<details class="mt-list"><summary>Mes étapes (${n})</summary><ol>${list}</ol></details>
        <p class="mt-reset">${monteeConfirm ? `<button type="button" class="btn ghost" id="mt-reset-ok">Oui, tout effacer</button> <button type="button" class="linkbtn" id="mt-reset-no">Annuler</button>` : `<button type="button" class="linkbtn" id="mt-reset">Recommencer la montée</button>`}</p>` : ""}</div></div>`;
}
function bindMontee(){
  const sec = $("#ar-montee"); if(!sec) return;
  const re = () => { sec.innerHTML = deckText(monteeHTML()); bindMontee(); applyGloss(sec); };
  const ok = $("#mt-ok"); if(ok) ok.onclick = () => { const id = MONTEE.find(x => !(learn.montee || {})[x]); if(!id) return;
    learn.montee = learn.montee || {}; learn.montee[id] = {d: todayKey(), t: Date.now(), note: ($("#mt-note").value || "").trim().slice(0, 600)};
    saveLearn(); buzz(12); re(); const h = sec.querySelector(".mt-step h3, .mt-end h3"); if(h){ h.setAttribute("tabindex","-1"); h.focus({preventScroll:true}); } };
  const r = $("#mt-reset"); if(r) r.onclick = () => { monteeConfirm = true; re(); const y = $("#mt-reset-ok"); if(y) y.focus(); };
  const rn = $("#mt-reset-no"); if(rn) rn.onclick = () => { monteeConfirm = false; re(); };
  const ry = $("#mt-reset-ok"); if(ry) ry.onclick = () => { learn.montee = {}; saveLearn(); monteeConfirm = false; re(); };
}

/* ---------- Le tirage posé sur l'Arbre ---------- */
function arbreTirHTML(rd){
  const seen = new Set(), C = rd.cards.map((c,i) => ({id:c.id, i})).filter(c => LORE[c.id] && !seen.has(c.id) && seen.add(c.id));
  if(C.length < 2) return "";
  const ids = C.map(c => c.id), n = ids.length, cls = {}, lab = {};
  C.forEach(c => { cls[c.id] = "hi"; lab[c.id] = String(c.i + 1); });
  const lvl = [0,0,0]; ids.forEach(id => lvl[Math.floor(bandeOf(id)/2)]++);
  const max = Math.max(...lvl), top = lvl.indexOf(max), tie = lvl.filter(x => x === max).length > 1;
  const LV = ["en haut de l'Arbre, dans le monde de l'esprit", "au milieu de l'Arbre, autour du cœur", "en bas de l'Arbre, près du monde concret"];
  const LVT = ["parle de sens, de principes et de grandes orientations, plus que des détails du quotidien.", "parle de tes valeurs : ce que tu choisis, ce que tu donnes, ce que tu transformes.", "parle de ce que tu vis, ressens et fais en ce moment : des émotions et des situations bien réelles."];
  const ps = [];
  if(tie){ const parts = [[lvl[0],"en haut"],[lvl[1],"au milieu"],[lvl[2],"en bas"]].filter(x => x[0]).map(([k,w]) => `${k} ${w}`);
    ps.push(`Tes lames se répartissent sur plusieurs étages de l'Arbre (${listFR(parts)}) : ta question touche à la fois au sens, au cœur et au concret.`); }
  else ps.push(`${max === n ? (n === 2 ? "Tes deux lames se trouvent" : `Tes ${n} lames se trouvent`) : `${max} lame${max>1?"s":""} sur ${n} ${max>1?"se trouvent":"se trouve"}`} ${LV[top]} : ton tirage ${LVT[top]}`);
  let dr = 0, ga = 0; ids.forEach(id => { const g = LORE[id].gd, s = [SEFIROT[g.de].pil, SEFIROT[g.to].pil]; if(s.includes("droit")) dr++; if(s.includes("gauche")) ga++; });
  if(dr - ga >= 2) ps.push("Le côté de la Clémence domine : l'élan, la générosité, l'expansion. Pense aussi à poser des limites.");
  else if(ga - dr >= 2) ps.push("Le côté de la Rigueur domine : la structure, l'effort, les renoncements. Pense aussi à t'accorder de la douceur.");
  else if(!dr && !ga) ps.push("Toutes tes lames sont sur le pilier du milieu : le tirage parle d'unité, de ce qui relie le haut et le bas de ta vie.");
  else ps.push("La Clémence et la Rigueur s'équilibrent dans ton tirage : ce que tu donnes et ce que tu retiens se répondent.");
  const ab = ids.filter(id => bandeOf(id) === 1).map(id => byId(id).nom), vo = ids.filter(id => bandeOf(id) === 3).map(id => byId(id).nom);
  if(ab.length) ps.push(`${listFR(ab)} ${ab.length>1?"traversent":"traverse"} l'Abîme : un enjeu de fond, qui touche à ce qui fonde ta vie.`);
  if(vo.length) ps.push(`${listFR(vo)} ${vo.length>1?"traversent":"traverse"} le Voile : une transformation est en cours, entre ce que tu es au fond et ce que tu montres.`);
  const hY = id => { const g = LORE[id].gd; return TREE_POS[g.de][1] + TREE_POS[g.to][1]; }, byP = [...ids].sort((a,b) => hY(b) - hY(a)), lo = byId(byP[0]), hi = byId(byP[byP.length-1]);
  ps.push(`En lisant l'Arbre de bas en haut, ton chemin part ${deNom(lo.nom)} (sentier ${LORE[lo.id].gd.p}) et monte vers ${hi.nom} (sentier ${LORE[hi.id].gd.p}) : la première lame montre d'où tu pars, la seconde vers quoi tu tends.`);
  const tree = markTreeSVG({cls, lab, label:`Ton tirage sur l'Arbre de Vie : ${n} sentiers allumés`,
    hit: id => cls[id] ? `data-arbre-sheet="${id}" tabindex="0" role="button" aria-label="${esc(`${byId(id).nom}, sentier ${LORE[id].gd.p}`)}"` : ""});
  return `<details class="atir"><summary>Voir ton tirage sur l'Arbre de Vie</summary><div class="atir-in"><div class="atir-tree">${tree}<p class="help">Les numéros sont ceux des positions. Touche un sentier pour lire sa place.</p></div>
    <div class="atir-txt">${ps.map(p => `<p>${p}</p>`).join("")}
      <ul class="atir-list">${C.map(c => { const k = byId(c.id), g = LORE[c.id].gd; return `<li><span class="atir-n">${c.i+1}</span><span><button type="button" class="linkbtn" data-arbre-sheet="${c.id}">${k.nom}</button><span class="atir-d">Sentier ${g.p}, ${BANDE_LIEU[bandeOf(c.id)]}</span></span></li>`; }).join("")}</ul></div></div></details>`;
}

/* Les fenêtres de l'Arbre s'ouvrent de partout (tirages, montée) par simple délégation */
document.addEventListener("click", e => { const b = e.target.closest && e.target.closest("[data-arbre-sheet]"); if(b) openArbreSheet(b.dataset.arbreSheet); });
document.addEventListener("keydown", e => { if(e.key !== "Enter" && e.key !== " ") return; const b = e.target.closest && e.target.closest("[data-arbre-sheet]"); if(b && b.tagName !== "BUTTON"){ e.preventDefault(); openArbreSheet(b.dataset.arbreSheet); } });

/* ===== Le glossaire en un toucher : les mots difficiles s'expliquent dans une bulle ===== */
const GLOSS = [
  {k:"sefira", re:"[Ss]efir(?:a|ot)", t:"Sefira (pluriel : sefirot)", d:"Une des dix sphères de l'Arbre de Vie : une qualité par laquelle l'infini se manifeste, de la Couronne (1) au Royaume (10). Le mot vient d'une racine hébraïque qui veut dire « compter »."},
  {k:"abime", re:"Abîme", t:"L'Abîme", d:"La frontière qui sépare les trois sefirot du haut, le monde de l'esprit, du reste de l'Arbre. Daath, la connaissance cachée, s'y tient. Une lame qui la traverse parle d'un enjeu de fond."},
  {k:"voile", re:"Voile", t:"Le Voile", d:"La frontière entre l'âme, autour du cœur (Tiphareth), et la personnalité. La Golden Dawn l'appelle Paroketh, du nom du rideau du Temple. Les lames qui le traversent parlent de transformations profondes."},
  {k:"daath", re:"Daath", t:"Daath, la Connaissance", d:"Une sefira cachée, entre la Couronne et le cœur, au milieu de l'Abîme. On ne la compte pas parmi les dix ; on la dessine en pointillés."},
  {k:"kabbale", re:"Kabbale", t:"La Kabbale", d:"La tradition mystique juive, qui cherche le sens caché des textes sacrés et de la création. L'Arbre de Vie est l'un de ses schémas. Des savants chrétiens la reprennent à la Renaissance, puis les occultistes au XIXe siècle."},
  {k:"gd", re:"Golden Dawn", t:"La Golden Dawn", d:"L'Ordre hermétique de l'Aube dorée, fondé à Londres en 1888. Il fixe le système qui relie chaque arcane majeur à une lettre hébraïque, un astre et un sentier de l'Arbre. Waite et Crowley en viennent."},
  {k:"einsof", re:"Ein Sof", t:"Ein Sof", d:"« Sans fin » : l'infini, Dieu avant toute manifestation. On ne peut rien en dire ; l'Arbre décrit la façon dont il se manifeste."},
  {k:"yetsirah", re:"Sefer Yetsirah", t:"Le Sefer Yetsirah", d:"Le « Livre de la Formation », court traité hébreu ancien. Il décrit la création par les dix nombres et les vingt-deux lettres de l'alphabet, qu'il range en lettres mères, doubles et simples."},
  {k:"zohar", re:"Zohar", t:"Le Zohar", d:"Le « Livre de la Splendeur », grand texte de la Kabbale, rédigé en Espagne à la fin du XIIIe siècle et attribué à Moïse de León."},
  {k:"mere", re:"lettres? mères?", t:"Les lettres mères", d:"Aleph, Mem et Shin : les trois lettres qui donnent les éléments (l'Air, l'Eau, le Feu). Dans la Golden Dawn, elles vont au Mat, au Pendu et au Jugement."},
  {k:"double", re:"lettres? doubles?", t:"Les lettres doubles", d:"Sept lettres qui ont deux prononciations ; elles donnent les sept planètes de l'astrologie ancienne. Elles vont au Bateleur, à la Papesse, à l'Impératrice, à la Roue, à la Maison Dieu, au Soleil et au Monde."},
  {k:"simple", re:"lettres? simples?", t:"Les lettres simples", d:"Les douze dernières lettres, qui donnent les douze signes du zodiaque, du Bélier (L'Empereur) aux Poissons (La Lune)."},
  {k:"pilier", re:"piliers?", t:"Les trois piliers", d:"Les trois colonnes de l'Arbre : à droite la Clémence (ce qui donne et s'étend), à gauche la Rigueur (ce qui limite et structure), au milieu l'Équilibre, qui unit les deux."},
  {k:"mineurs", re:"arcanes mineurs", t:"Les arcanes mineurs", d:"Les 56 cartes à couleurs du tarot : Bâtons, Coupes, Épées et Deniers. Sur l'Arbre, les As à Dix vont aux dix sefirot, et les quatre couleurs aux quatre mondes."},
  {k:"ecolefr", re:"école française", t:"L'école française", d:"Éliphas Lévi, Papus et Oswald Wirth donnent Aleph au Bateleur et placent Le Mat entre le Jugement et le Monde. C'est l'attribution des lettres imprimées sur le tarot de Wirth."},
  {k:"kircher", re:"Kircher", t:"Athanase Kircher (1602-1680)", d:"Jésuite allemand, savant universel. En 1652, dans son Œdipe égyptien, il publie le dessin de l'Arbre aux sentiers numérotés que la Golden Dawn reprendra."},
  ...Object.entries(SEFIROT).map(([k,S]) => ({k, re:S.nom, t:`${S.nom}, ${S.fr}`, d:`Sefira ${S.n}, sur ${PILIERS[S.pil]}. ${S.txt}`}))
].map(g => ({...g, rx: new RegExp(`(?<![\\p{L}])(?:${g.re})(?![\\p{L}])`, "u")}));
const GL_SKIP = "button, a, svg, h1, h2, h3, h4, h5, h6, summary, label, textarea, input, select, .eyebrow, .gl, .heb, .stoc, th, figcaption, .chip, .tag, .mots, .qopt, .quiz-q, #glbub, .ar-li, .ap-meta, .mt-when";
const GL_BLOCK = "p, li, dd, td";
/* Une seule bulle par terme et par bloc (paragraphe, élément de liste…) : le texte reste lisible */
function applyGloss(root){
  if(!root || !root.ownerDocument) return;
  const tw = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {acceptNode: n => { const p = n.parentElement; return n.nodeValue.trim().length > 2 && p && !p.closest(GL_SKIP) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT; }});
  const nodes = []; while(tw.nextNode()) nodes.push(tw.currentNode);
  const usedIn = new Map(), sectionUse = new Map();
  nodes.forEach(n0 => {
    const block = n0.parentElement.closest(GL_BLOCK) || n0.parentElement, sec = n0.parentElement.closest("section, details, .ap-sec, .ap-box, .ag-txt, .ash-txt, .sheet-body") || root;
    if(!usedIn.has(block)) usedIn.set(block, new Set(block.querySelectorAll ? [...block.querySelectorAll(".gl")].map(b => b.dataset.gl) : []));
    if(!sectionUse.has(sec)) sectionUse.set(sec, new Set(sec.querySelectorAll ? [...sec.querySelectorAll(".gl")].map(b => b.dataset.gl) : []));
    const used = usedIn.get(block), sused = sectionUse.get(sec);
    let n = n0;
    for(let guard = 0; n && guard < 6; guard++){
      let best = null;
      for(const g of GLOSS){ if(used.has(g.k) || sused.has(g.k)) continue; const m = g.rx.exec(n.nodeValue); if(m && (!best || m.index < best.m.index)) best = {g, m}; }
      if(!best) break;
      const mid = n.splitText(best.m.index), rest = mid.splitText(best.m[0].length);
      const b = document.createElement("button"); b.type = "button"; b.className = "gl"; b.dataset.gl = best.g.k; b.textContent = mid.nodeValue;
      b.setAttribute("aria-haspopup", "dialog"); b.setAttribute("aria-expanded", "false");
      mid.replaceWith(b); used.add(best.g.k); sused.add(best.g.k); n = rest;
    }
  });
}
let glOpen = null;
function glClose(){ const bub = $("#glbub"); if(bub) bub.hidden = true; if(glOpen){ glOpen.setAttribute("aria-expanded","false"); glOpen = null; } }
function glShow(btn){
  const g = GLOSS.find(x => x.k === btn.dataset.gl); if(!g) return;
  let bub = $("#glbub");
  if(!bub){ bub = document.createElement("div"); bub.id = "glbub"; bub.className = "glbub"; bub.setAttribute("role","dialog"); bub.setAttribute("aria-labelledby","glbub-t");
    bub.innerHTML = `<p class="glbub-t" id="glbub-t"></p><p class="glbub-d"></p><button type="button" class="glbub-x" aria-label="Fermer la définition">Fermer</button>`;
    document.body.appendChild(bub); bub.querySelector(".glbub-x").onclick = () => { const o = glOpen; glClose(); if(o) o.focus(); }; }
  if(glOpen === btn){ glClose(); return; }
  glClose();
  bub.querySelector(".glbub-t").textContent = g.t; bub.querySelector(".glbub-d").textContent = g.d;
  bub.hidden = false; glOpen = btn; btn.setAttribute("aria-expanded","true");
  glPlace();
}
/* La bulle suit son mot quand la page défile, et se ferme quand le mot sort de l'écran */
function glPlace(){
  const bub = $("#glbub"), btn = glOpen; if(!bub || !btn) return;
  const r = btn.getBoundingClientRect(), navH = innerWidth <= 720 ? 86 : 0;
  if(!btn.isConnected || r.bottom < 0 || r.top > innerHeight - navH){ glClose(); return; }
  const w = Math.min(340, innerWidth - 24); bub.style.width = w + "px";
  const left = Math.max(12, Math.min(innerWidth - w - 12, r.left + r.width/2 - w/2)), h = bub.offsetHeight;
  const below = r.bottom + 8 + h <= innerHeight - navH;
  bub.style.left = left + "px"; bub.style.top = (below ? r.bottom + 8 : Math.max(8, r.top - h - 8)) + "px";
}
document.addEventListener("click", e => { const b = e.target.closest && e.target.closest(".gl"); if(b){ e.preventDefault(); glShow(b); return; } if(glOpen && !e.target.closest("#glbub")) glClose(); });
document.addEventListener("keydown", e => { if(e.key === "Escape" && glOpen){ const o = glOpen; glClose(); o.focus(); e.stopPropagation(); } }, true);
document.addEventListener("scroll", () => { if(glOpen) glPlace(); }, true);
window.addEventListener("resize", () => { if(glOpen) glClose(); });

