/* ---------- L'explorateur ---------- */
const xs = { id:null, i:0, zoom:false, back:null };
function exploreHTML(){
  const k = byId(xs.id), P = HOT[DECK_ID][xs.id], p = P[xs.i], D = deck();
  return `<div class="xp-panel" role="dialog" aria-modal="true" aria-labelledby="xp-h">
    <div class="xp-head"><div><p class="eyebrow">Explorer la lame · ${D.nom}</p><h2 id="xp-h">${k.nom}</h2></div>
      <div class="xp-tools"><button type="button" class="btn ghost xp-zoom" aria-pressed="${xs.zoom}">${xs.zoom ? "Vue entière" : "Agrandir"}</button><button type="button" class="sheet-close xp-close">Fermer</button></div></div>
    <div class="xp-body">
      <div class="xp-stage${xs.zoom ? " zoom" : ""}" id="xp-stage"><div class="xp-img">
        <img src="${D.src(xs.id)}" alt="${esc(k.nom)}, ${esc(k.symb)}" draggable="false">
        ${P.map((q, j) => `<button type="button" class="xp-dot${j === xs.i ? " on" : ""}" style="left:${q[0]}%;top:${q[1]}%" data-xp="${j}" aria-label="${j+1}. ${esc(q[2])}" aria-pressed="${j === xs.i}"><span>${j+1}</span></button>`).join("")}
      </div></div>
      <div class="xp-side">
        <div class="xp-cur" aria-live="polite"><p class="eyebrow">Symbole ${xs.i+1} sur ${P.length}</p><h3>${p[2]}</h3><p>${p[3]}</p>
          <div class="xp-nav"><button type="button" class="btn ghost" data-xpstep="-1" ${xs.i === 0 ? "disabled" : ""}>← Précédent</button><button type="button" class="btn" data-xpstep="1" ${xs.i === P.length-1 ? "disabled" : ""}>Suivant →</button></div></div>
        <details class="xp-all"><summary>Tous les symboles (${P.length})</summary><ol>${P.map((q, j) => `<li><button type="button" class="linkbtn${j === xs.i ? " on" : ""}" data-xp="${j}">${q[2]}</button></li>`).join("")}</ol></details>
        <p class="help xp-src">${HOT_SRC[DECK_ID]}</p>
      </div></div></div>`;
}
function openExplore(id, i = 0){
  if(!HOT[DECK_ID] || !HOT[DECK_ID][id]) return;
  let o = $("#explore");
  if(!o){ o = document.createElement("div"); o.id = "explore"; o.className = "xp"; document.body.appendChild(o);
    o.addEventListener("click", e => { if(e.target.id === "explore") closeExplore(); }); }
  if(!xs.id) xs.back = document.activeElement;
  xs.id = id; xs.i = i; renderExplore(true);
  o.hidden = false; document.body.classList.add("locked");
}
function renderExplore(first){
  const o = $("#explore"), keepAll = o.querySelector(".xp-all") && o.querySelector(".xp-all").open, sc = o.querySelector("#xp-stage");
  const pos = sc ? [sc.scrollLeft, sc.scrollTop] : null;
  o.innerHTML = deckText(exploreHTML());
  if(keepAll) o.querySelector(".xp-all").open = true;
  const st = o.querySelector("#xp-stage"); st.style.setProperty("--stw", Math.max(200, st.clientWidth - 32) + "px"); if(pos && !first){ st.scrollLeft = pos[0]; st.scrollTop = pos[1]; }
  o.querySelectorAll("[data-xp]").forEach(b => b.onclick = () => { xs.i = +b.dataset.xp; renderExplore(); focusDot(); });
  o.querySelectorAll("[data-xpstep]").forEach(b => b.onclick = () => { const P = HOT[DECK_ID][xs.id]; xs.i = Math.max(0, Math.min(P.length-1, xs.i + +b.dataset.xpstep)); renderExplore(); centerDot(); const nb = o.querySelector(`[data-xpstep="${b.dataset.xpstep}"]`); if(nb && !nb.disabled) nb.focus(); else o.querySelector(".xp-dot.on").focus(); });
  o.querySelector(".xp-close").onclick = closeExplore;
  o.querySelector(".xp-zoom").onclick = () => { xs.zoom = !xs.zoom; renderExplore(true); centerDot(); o.querySelector(".xp-zoom").focus(); };
  if(first) (o.querySelector(".xp-dot.on") || o.querySelector(".xp-close")).focus();
}
function focusDot(){ const d = $("#explore .xp-dot.on"); if(d){ d.focus({preventScroll:true}); centerDot(); } }
function centerDot(){ const st = $("#xp-stage"), d = st && st.querySelector(".xp-dot.on"); if(!st || !d || !xs.zoom) return;
  const r = d.getBoundingClientRect(), sr = st.getBoundingClientRect();
  st.scrollTo({left: st.scrollLeft + r.left - sr.left - sr.width/2, top: st.scrollTop + r.top - sr.top - sr.height/2, behavior: reduceMotion() ? "auto" : "smooth"}); }
function closeExplore(){ const o = $("#explore"); if(!o) return; o.hidden = true; xs.id = null; xs.zoom = false;
  if($("#sheet").hidden) document.body.classList.remove("locked");
  if(xs.back && xs.back.isConnected) xs.back.focus(); }
document.addEventListener("keydown", e => {
  const o = $("#explore"); if(!o || o.hidden) return;
  if(e.key === "Escape"){ e.stopImmediatePropagation(); closeExplore(); return; }
  if(e.key === "ArrowRight" || e.key === "ArrowLeft"){ const P = HOT[DECK_ID][xs.id]; const n = Math.max(0, Math.min(P.length-1, xs.i + (e.key === "ArrowRight" ? 1 : -1))); if(n !== xs.i){ xs.i = n; renderExplore(); focusDot(); e.preventDefault(); } }
  if(e.key === "Tab"){ const f = [...o.querySelectorAll("button:not([disabled]), summary")].filter(x => x.offsetParent !== null); if(!f.length) return;
    if(e.shiftKey && document.activeElement === f[0]){ e.preventDefault(); f[f.length-1].focus(); } else if(!e.shiftKey && document.activeElement === f[f.length-1]){ e.preventDefault(); f[0].focus(); } }
}, true);

