function reduceTo22(total){
  const steps = [total]; let s = total;
  while(s > 22){ s = String(s).split("").reduce((a,d)=>a+Number(d),0); steps.push(s); }
  return {card: CARDS.find(c => c.n === (s===22 ? 0 : s)), steps};
}
function birthCalc(iso, year){
  const [Y,M,D] = iso.split("-").map(Number);
  const y = year || Y;
  const digits = (String(D).padStart(2,"0") + String(M).padStart(2,"0") + String(y)).split("").map(Number);
  const total = digits.reduce((a,b)=>a+b,0);
  const r = reduceTo22(total);
  let calc = digits.join(" + ") + " = " + total;
  for(let i=1;i<r.steps.length;i++) calc += ", puis " + String(r.steps[i-1]).split("").join(" + ") + " = " + r.steps[i];
  if(r.steps[r.steps.length-1] === 22) calc += ` (XXII, ${byId("mat").nom})`;
  return {card:r.card, calc};
}
function validBirth(iso){ if(!/^\d{4}-\d{2}-\d{2}$/.test(iso||"")) return false; const d = new Date(iso+"T12:00:00"); const y = d.getFullYear(); return !isNaN(d) && y >= 1900 && d <= new Date(); }
function niceDate(iso){ return new Date(iso+"T12:00:00").toLocaleDateString("fr-FR",{day:"numeric", month:"long", year:"numeric"}); }
function lowerArt(nom){ return nom.replace(/^Le /,"le ").replace(/^La /,"la ").replace(/^L'/,"l'"); }

