/* ---------- Petits effets : vibration et son ---------- */
function buzz(ms){ try{ if(navigator.vibrate) navigator.vibrate(ms); }catch(e){} }
let actx = null;
function sfx(type){
  if(!prefs.sound) return;
  try{
    actx = actx || new (window.AudioContext || window.webkitAudioContext)();
    if(actx.state === "suspended") actx.resume();
    const dur = type === "shuffle" ? .55 : type === "cut" ? .22 : .15, sr = actx.sampleRate;
    const buf = actx.createBuffer(1, Math.floor(sr*dur), sr), d = buf.getChannelData(0);
    for(let i=0;i<d.length;i++){ const p = i/d.length;
      const env = type === "shuffle" ? Math.pow(1-p,1.2)*(.55+.45*Math.abs(Math.sin(p*38))) : Math.pow(1-p, type==="cut"?2:3.2);
      d[i] = (Math.random()*2-1)*env; }
    const src = actx.createBufferSource(); src.buffer = buf;
    const f = actx.createBiquadFilter(); f.type = "bandpass"; f.frequency.value = type==="flip" ? 2600 : type==="cut" ? 1500 : 2000; f.Q.value = .9;
    const g = actx.createGain(); g.gain.value = type==="shuffle" ? .22 : .3;
    src.connect(f); f.connect(g); g.connect(actx.destination); src.start();
  }catch(e){}
}

/* ---------- Aujourd'hui ---------- */
let jourJustDrawn = null;
function greeting(){ const h = new Date().getHours(); return h < 5 ? "Bonne nuit" : h < 12 ? "Bonjour" : h < 18 ? "Bon après-midi" : "Bonsoir"; }
function todayReading(){ return journal.find(e => e.spread==="jour" && todayKey(e.date)===todayKey()); }
function dailyFact(){
  const steps = HISTORY.filter(h => !h.era), d = new Date(), doy = Math.floor((d - new Date(d.getFullYear(),0,0)) / DAY);
  const h = steps[doy % steps.length], first = h.p[0].split(/(?<=\.)\s/)[0];
  return {h, first};
}
