/* Petites cartes pour les nouveaux tirages et les tirages personnels */
const _miniMap = miniMap;
miniMap = function(k){
  const r = (x,y,rot=0,w=5,h=8) => `<rect x="${(x-w/2).toFixed(1)}" y="${(y-h/2).toFixed(1)}" width="${w}" height="${h}" rx="1"${rot?` transform="rotate(${rot} ${x} ${y})"`:""}/>`;
  let s = null;
  if(k==="decision") s = r(9,9)+r(9,21)+r(31,9)+r(31,21)+r(20,9)+`<rect class="soft" x="17.5" y="17" width="5" height="8" rx="1"/>`;
  if(k==="pasmat") s = r(9,20)+r(20,15)+r(31,10) + `<line x1="4" y1="27" x2="36" y2="27"/>`;
  if(k==="lune" || k==="lune_c" || k==="lune_d") s = r(10,19)+r(20,19)+r(30,19) + `<circle cx="20" cy="6.5" r="3.6"/>`;
  const L = LAYOUTS[k];
  if(!s && SPREADS[k] && SPREADS[k].custom && L){ const h = 100/L.ar, sc = Math.min(34/100, 26/h), ox = 20 - 50*sc, oy = 15 - h/2*sc;
    const cw = L.w*sc, chh = cw/CARD_AR;
    s = L.slots.map(([x,y,rot=0]) => r(ox + x*sc, oy + y/L.ar*sc, rot, Math.max(2.2,cw), Math.max(3.4,chh))).join(""); }
  return s ? `<svg viewBox="0 0 40 30" class="mini-map" aria-hidden="true">${s}</svg>` : _miniMap(k);
};

/* Sections propres à certains tirages */
function extraHTML(rd){
  const C = rd.cards.map(c => ({...c, k:byId(c.id)}));
  const yn = c => YESNO[c.id][c.rev?1:0];
  if(rd.spread === "decision"){
    const nA = rd.opts && rd.opts[0] ? `le chemin A (${esc(rd.opts[0])})` : "le chemin A", nB = rd.opts && rd.opts[1] ? `le chemin B (${esc(rd.opts[1])})` : "le chemin B";
    const sA = yn(C[1]) - Math.max(0, yn(C[2])) / 2 + (C[2].rev ? -.5 : 0), sB = yn(C[3]) - Math.max(0, yn(C[4])) / 2 + (C[4].rev ? -.5 : 0);
    const rA = [C[1],C[2]].filter(c=>c.rev).length, rB = [C[3],C[4]].filter(c=>c.rev).length;
    let verdict;
    if(Math.abs(sA - sB) < 1) verdict = `Les lames ne tranchent pas : les deux chemins se valent. Ce qui compte, c'est la façon dont tu avances, et le conseil ${deNom(C[5].k.nom)} prend ici toute sa place.`;
    else { const win = sA > sB ? "A" : "B", w = win === "A" ? [C[1],C[2]] : [C[3],C[4]];
      verdict = `Les lames penchent vers ${win === "A" ? nA : nB}. Ce qu'il t'apporte, ${w[0].k.nom}, pèse plus lourd que ce qu'il te coûte. Garde en tête le prix à payer : ${w[1].k.noyau[w[1].rev?1:0]}.`; }
    return `<section class="extra"><h3>Les deux chemins</h3><p>${verdict}</p>
      <p class="help">${rA ? `${rA} lame${rA>1?"s":""} retournée${rA>1?"s":""} du côté A` : "Aucune lame retournée du côté A"}, ${rB ? `${rB} du côté B` : "aucune du côté B"}. Une lame retournée signale ce qui coince sur ce chemin.</p></section>`;
  }
  if(rd.spread === "pasmat"){
    const c = C[0], k = c.k, first = LORE[k.id].chemin.split(/(?<=\.)\s/).slice(0,2).join(" ");
    return `<section class="extra"><h3>Ta place sur le chemin ${deNom(byId("mat").nom)}</h3>
      <p>${k.id === "mat" ? "Tu es au départ du voyage, ou à son retour : tout reste ouvert." : `Tu te trouves au pas ${ROMAN[k.n]} du chemin, là où le Mat devient ${lowerArt(k.nom)}.`} ${first}</p>
      <p><button type="button" class="linkbtn" data-go-chemin2="${k.id}">Voir cette étape du chemin</button></p></section>`;
  }
  if(rd.spread === "lune_c" || rd.spread === "lune_d"){
    const f = rd.moonF != null ? rd.moonF : moonInfo().f, idx = Math.floor(f*8 + .5) % 8;
    return `<section class="extra"><h3>${MOON[idx][0]}</h3><p>${rd.spread === "lune_c" ? "Tirage fait en lune croissante, du premier croissant à la pleine lune : le temps de semer et de commencer." : "Tirage fait en lune décroissante, de la pleine lune au dernier croissant : le temps de récolter, de faire le tri et de laisser partir."} ${MOON[idx][1]}</p></section>`;
  }
  return "";
}

/* ---------- Les tirages personnels ---------- */
const CUSTOM_STORE = "arcanes.custom.v1";
function loadCustom(){ try{ const v = JSON.parse(localStorage.getItem(CUSTOM_STORE) || "[]"); return Array.isArray(v) ? v : []; }catch(e){ return []; } }
function saveCustom(){ try{ localStorage.setItem(CUSTOM_STORE, JSON.stringify(customSpreads)); }catch(e){} }
let customSpreads = loadCustom();
GROUPS.push("Mes tirages");
const ED = { ar:1.25, cw:12 };
const escl = s => String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
function edExt(p){ const chH = ED.cw / CARD_AR * ED.ar; return p.rot ? [chH/ED.ar/2, ED.cw*ED.ar/2] : [ED.cw/2, chH/2]; }

function registerCustom(c){
  const n = c.pos.length, keys = c.pos.map((p,i) => `${c.id}_${i}`);
  keys.forEach((k,i) => { const nm = escl(c.pos[i].name || `Lame ${i+1}`); POSLABEL[k] = nm;
    FRAMES[k] = customFrames(nm); });
  /* Cadre de lecture ajusté aux lames, avec une marge */
  const pts = c.pos.map(p => { const [hx, hy] = edExt(p); return {x:p.x, y:p.y/ED.ar, hx, hy:hy/ED.ar, rot:p.rot}; });
  const pad = 3, minX = Math.min(...pts.map(p=>p.x-p.hx)) - pad, maxX = Math.max(...pts.map(p=>p.x+p.hx)) + pad;
  const minY = Math.min(...pts.map(p=>p.y-p.hy)) - pad, maxY = Math.max(...pts.map(p=>p.y+p.hy)) + pad;
  const bw = maxX - minX, bh = maxY - minY;
  const slots = pts.map(p => [((p.x-minX)/bw*100), ((p.y-minY)/bh*100), p.rot ? 90 : 0].map(v=>+v.toFixed(2)));
  const w = +(ED.cw / bw * 100).toFixed(2);
  LAYOUTS[c.id] = {ar:+(bw/bh).toFixed(3), w, max: Math.round(Math.min(760, 150 * 100 / w)), slots};
  SPREADS[c.id] = {label: escl(c.label), count:n, desc:`${n} lame${n>1?"s":""} · ${escl(c.desc || "ton tirage personnel")}`, group: c.deleted ? -1 : 3, pos:keys, layout:c.id, custom:true, sens:c.pos.map(p => escl(p.sens || ""))};
  /* Voisins pour la lecture des regards : même rangée, la plus proche à gauche et à droite */
  const nb = {}, pairs = [], tol = (ED.cw / CARD_AR) * .55;
  pts.forEach((p,i) => { if(p.rot) return;
    const side = dir => { let best = null, bd = 1e9; pts.forEach((q,j) => { if(j===i || q.rot || Math.abs(q.y-p.y) > tol) return; const d = (q.x - p.x) * dir; if(d > 0 && d < bd){ bd = d; best = j; } }); return best; };
    nb[i] = [side(-1), side(1)]; });
  Object.keys(nb).forEach(i => { const r = nb[i][1]; if(r !== null && nb[r] && nb[r][0] === Number(i)) pairs.push([Number(i), r]); });
  NEIGHBORS[c.id] = nb; SIDE_PAIRS[c.id] = pairs;
}
customSpreads.forEach(registerCustom);

/* Dispositions de départ */
function presetPositions(kind, n){
  const out = [], P = (x,y) => out.push([x,y]);
  if(kind === "croix"){ const base = [[50,50],[26,50],[74,50],[50,18],[50,82]], extra = Math.max(0, n-5); for(let i=0;i<n;i++){ if(i < 5) P(...base[i]); else P(93, extra === 1 ? 50 : 16 + (i-5)*(68/(extra-1))); } }
  else if(kind === "arc"){ for(let i=0;i<n;i++){ const t = n===1 ? Math.PI/2 : Math.PI*i/(n-1); P(50 - 42*Math.cos(t), 22 + 56*Math.sin(t)); } }
  else if(kind === "colonnes"){ const rows = Math.ceil(n/2); for(let i=0;i<n;i++){ const r = Math.floor(i/2); P(i%2 ? 68 : 32, rows === 1 ? 50 : 16 + r*(68/(rows-1))); } }
  else if(kind === "cercle"){ for(let i=0;i<n;i++){ const a = -Math.PI/2 + i*2*Math.PI/n; P(50 + 38*Math.cos(a), 50 + 34*Math.sin(a)); } }
  else { const rows = n <= 7 ? 1 : 2, per = Math.ceil(n/rows); for(let i=0;i<n;i++){ const r = Math.floor(i/per), inRow = Math.min(per, n - r*per), col = i - r*per, span = Math.min(84, (inRow-1)*13.5); P(inRow === 1 ? 50 : 50 - span/2 + col*span/(inRow-1), rows === 1 ? 50 : 30 + r*40); } }
  return out;
}
function clampPos(p){ const [hx, hy] = edExt(p); p.x = Math.min(100-hx, Math.max(hx, p.x)); p.y = Math.min(100-hy, Math.max(hy, p.y)); return p; }
const snap = v => Math.round(v/2.5)*2.5;

let ed = null;
function openEditor(id){
  const c = id ? customSpreads.find(x=>x.id===id) : null;
  ed = c ? {id:c.id, label:c.label, desc:c.desc||"", pos:c.pos.map(p=>({...p}))} : {id:null, label:"", desc:"", pos:presetPositions("ligne",3).map(([x,y]) => ({name:"", sens:"", x, y, rot:0}))};
  ed.sel = 0; ed.err = "";
  state.step = "editor"; renderTirer(); window.scrollTo({top:0});
}
function editorHTML(){
  const n = ed.pos.length;
  const card = (p,i) => `<button type="button" class="ed-card${i===ed.sel?" sel":""}${p.rot?" ed-rot":""}" data-ec="${i}" style="left:${p.x}%;top:${p.y}%;width:${ED.cw}%" aria-label="Lame ${i+1}${p.name ? ", " + escl(p.name) : ""}. Glisse pour la déplacer, ou utilise les flèches du clavier."><span class="ed-face"><b>${i+1}</b><span class="ed-nm">${escl(p.name || "Lame " + (i+1))}</span></span></button>`;
  const row = (p,i) => `<div class="ed-row${i===ed.sel?" sel":""}" data-er="${i}">
      <div class="ed-row-top"><span class="ed-n">${i+1}</span><input class="ed-name" data-i="${i}" maxlength="40" value="${escl(p.name)}" placeholder="Nom de la place" aria-label="Nom de la lame ${i+1}">
        <span class="ed-tools"><button type="button" class="ed-ico" data-up="${i}" ${i===0?"disabled":""} aria-label="Monter">↑</button><button type="button" class="ed-ico" data-down="${i}" ${i===n-1?"disabled":""} aria-label="Descendre">↓</button><button type="button" class="ed-ico danger" data-rm="${i}" ${n===1?"disabled":""} aria-label="Retirer la lame ${i+1}">✕</button></span></div>
      <textarea class="ed-sens" data-i="${i}" rows="2" maxlength="220" placeholder="Le sens de cette place : ce qu'elle interroge (facultatif)" aria-label="Sens de la lame ${i+1}">${escl(p.sens)}</textarea>
      <div class="ed-orient" role="group" aria-label="Orientation de la lame ${i+1}"><button type="button" class="${p.rot?"":"on"}" data-rot="${i}" data-v="0" aria-pressed="${!p.rot}"><span class="o-ico"></span>Droite</button><button type="button" class="${p.rot?"on":""}" data-rot="${i}" data-v="1" aria-pressed="${!!p.rot}"><span class="o-ico o-rot"></span>Couchée</button></div>
    </div>`;
  return `<section class="editor">
    <p class="crumb"><button type="button" class="linkbtn" id="ed-cancel">← Tous les tirages</button></p>
    <header class="sec-head"><h1>${ed.id ? "Modifier mon tirage" : "Créer mon tirage"}</h1><p>Choisis le nombre de lames, donne un sens à chaque place, puis dispose-les comme tu veux : droites ou couchées.</p></header>
    <div class="ed-meta"><label><span>Nom du tirage</span><input id="ed-label" maxlength="50" value="${escl(ed.label)}" placeholder="Ex. Mon tirage du dimanche"></label>
      <label><span>Description <em>(facultatif)</em></span><input id="ed-desc" maxlength="90" value="${escl(ed.desc)}" placeholder="Ex. Pour faire le point sur ma semaine"></label></div>
    <div class="ed-grid">
      <div class="ed-left">
        <div class="ed-bar"><span class="ed-count"><strong>${n}</strong> lame${n>1?"s":""}</span><button type="button" class="btn small" id="ed-add" ${n>=12?"disabled":""}>+ Ajouter une lame</button></div>
        <div class="ed-board" id="ed-board" style="aspect-ratio:${ED.ar}">${ed.pos.map(card).join("")}</div>
        <div class="ed-presets"><span>Disposer :</span>${[["ligne","En ligne"],["croix","En croix"],["arc","En arc"],["colonnes","Deux colonnes"],["cercle","En cercle"]].map(([k,l])=>`<button type="button" class="chip small" data-preset="${k}">${l}</button>`).join("")}</div>
        <p class="help">Fais glisser les lames sur la grille. Touche une lame pour la modifier dans la liste.</p>
      </div>
      <div class="ed-list" id="ed-list">${ed.pos.map(row).join("")}</div>
    </div>
    <p class="ed-err" id="ed-err" aria-live="polite">${ed.err}</p>
    <div class="actions"><button type="button" class="btn big" id="ed-save">${ed.id ? "Enregistrer mon tirage" : "Créer mon tirage"}</button><button type="button" class="btn ghost" id="ed-cancel2">Annuler</button></div>
  </section>`;
}
function edRerender(){ const y = window.scrollY; renderTirer(); window.scrollTo({top:y}); }
function edSelect(i, scrollRow){
  ed.sel = i;
  document.querySelectorAll(".ed-card").forEach((c,j)=>c.classList.toggle("sel", j===i));
  document.querySelectorAll(".ed-row").forEach((r,j)=>r.classList.toggle("sel", j===i));
  if(scrollRow){ const r = document.querySelector(`.ed-row[data-er="${i}"]`); if(r && isMobile() === false) r.scrollIntoView({block:"nearest", behavior: reduceMotion() ? "auto" : "smooth"}); }
}
function bindEditor(){
  const board = $("#ed-board"); if(!board) return;
  $("#ed-label").oninput = e => ed.label = e.target.value;
  $("#ed-desc").oninput = e => ed.desc = e.target.value;
  const cancel = () => { ed = null; state.step = "choose"; renderTirer(); const m = $("#mine"); if(m) m.scrollIntoView({block:"start"}); };
  $("#ed-cancel").onclick = cancel; $("#ed-cancel2").onclick = cancel;
  $("#ed-add").onclick = () => { if(ed.pos.length >= 12) return; const p = clampPos({name:"", sens:"", x:snap(50 + (ed.pos.length%5)*4 - 8), y:snap(50 + (ed.pos.length%3)*6 - 6), rot:0}); ed.pos.push(p); ed.sel = ed.pos.length-1; edRerender(); const nm = document.querySelector(`.ed-name[data-i="${ed.sel}"]`); if(nm) nm.focus({preventScroll:true}); };
  document.querySelectorAll("[data-preset]").forEach(b => b.onclick = () => { presetPositions(b.dataset.preset, ed.pos.length).forEach(([x,y],i) => { ed.pos[i].x = x; ed.pos[i].y = y; if(b.dataset.preset !== "croix") ed.pos[i].rot = 0; clampPos(ed.pos[i]); }); edRerender(); });
  document.querySelectorAll(".ed-name").forEach(inp => { inp.oninput = () => { const i = Number(inp.dataset.i); ed.pos[i].name = inp.value; const lab = board.querySelector(`[data-ec="${i}"] .ed-nm`); if(lab) lab.textContent = inp.value || "Lame " + (i+1); }; inp.onfocus = () => edSelect(Number(inp.dataset.i)); });
  document.querySelectorAll(".ed-sens").forEach(t => { t.oninput = () => ed.pos[Number(t.dataset.i)].sens = t.value; t.onfocus = () => edSelect(Number(t.dataset.i)); });
  document.querySelectorAll("[data-rot]").forEach(b => b.onclick = () => { const i = Number(b.dataset.rot); ed.pos[i].rot = b.dataset.v === "1" ? 1 : 0; clampPos(ed.pos[i]); ed.sel = i; edRerender(); });
  document.querySelectorAll("[data-up]").forEach(b => b.onclick = () => { const i = Number(b.dataset.up); [ed.pos[i-1], ed.pos[i]] = [ed.pos[i], ed.pos[i-1]]; ed.sel = i-1; edRerender(); });
  document.querySelectorAll("[data-down]").forEach(b => b.onclick = () => { const i = Number(b.dataset.down); [ed.pos[i+1], ed.pos[i]] = [ed.pos[i], ed.pos[i+1]]; ed.sel = i+1; edRerender(); });
  document.querySelectorAll("[data-rm]").forEach(b => b.onclick = () => { if(ed.pos.length <= 1) return; ed.pos.splice(Number(b.dataset.rm), 1); ed.sel = Math.max(0, Math.min(ed.sel, ed.pos.length-1)); edRerender(); });
  document.querySelectorAll(".ed-row").forEach(r => r.addEventListener("pointerdown", () => edSelect(Number(r.dataset.er))));
  /* Glisser-déposer des lames sur la grille */
  board.querySelectorAll(".ed-card").forEach(el => {
    const i = Number(el.dataset.ec); let drag = null;
    el.addEventListener("pointerdown", e => { e.preventDefault(); const r = board.getBoundingClientRect(), p = ed.pos[i];
      drag = {id:e.pointerId, ox: e.clientX - (r.left + p.x/100*r.width), oy: e.clientY - (r.top + p.y/100*r.height), sx:e.clientX, sy:e.clientY, moved:false};
      try{ el.setPointerCapture(e.pointerId); }catch(x){} el.classList.add("drag"); edSelect(i, true); });
    el.addEventListener("pointermove", e => { if(!drag || e.pointerId !== drag.id) return; const r = board.getBoundingClientRect(), p = ed.pos[i];
      if(Math.abs(e.clientX-drag.sx) + Math.abs(e.clientY-drag.sy) > 3) drag.moved = true;
      p.x = snap((e.clientX - drag.ox - r.left) / r.width * 100); p.y = snap((e.clientY - drag.oy - r.top) / r.height * 100); clampPos(p);
      el.style.left = p.x + "%"; el.style.top = p.y + "%"; });
    const end = () => { if(!drag) return; drag = null; el.classList.remove("drag"); };
    el.addEventListener("pointerup", end); el.addEventListener("pointercancel", end);
    el.addEventListener("keydown", e => { const d = {ArrowLeft:[-2.5,0], ArrowRight:[2.5,0], ArrowUp:[0,-2.5], ArrowDown:[0,2.5]}[e.key]; if(!d) return; e.preventDefault(); const p = ed.pos[i]; p.x += d[0]; p.y += d[1]*ED.ar; clampPos(p); el.style.left = p.x + "%"; el.style.top = p.y + "%"; edSelect(i); });
    el.addEventListener("click", () => edSelect(i, true));
  });
  $("#ed-save").onclick = () => {
    ed.label = $("#ed-label").value.trim(); ed.desc = $("#ed-desc").value.trim();
    if(!ed.label){ ed.err = "Donne un nom à ton tirage."; $("#ed-err").textContent = ed.err; $("#ed-label").focus(); return; }
    const pos = ed.pos.map((p,i) => ({name: p.name.trim() || `Lame ${i+1}`, sens: p.sens.trim(), x:+p.x.toFixed(2), y:+p.y.toFixed(2), rot: p.rot ? 1 : 0}));
    let id = ed.id;
    if(id){ const old = customSpreads.find(c=>c.id===id);
      if(journal.some(e => e.spread === id)){ old.deleted = true; registerCustom(old); id = null; }   /* garde l'ancienne version pour les lectures déjà faites */
      else customSpreads = customSpreads.filter(c=>c.id!==id); }
    const c = {id: id || "c" + Date.now().toString(36) + rand32().toString(36).slice(0,3), label:ed.label, desc:ed.desc, pos, created: new Date().toISOString()};
    customSpreads.push(c); saveCustom(); registerCustom(c);
    ed = null; state.step = "choose"; state.justCreated = c.id; renderTirer();
    const m = $("#mine"); if(m) m.scrollIntoView({block:"start", behavior: reduceMotion() ? "auto" : "smooth"});
  };
}
function myGroupHTML(tile){
  const list = customSpreads.filter(c => !c.deleted);
  return `<section class="tgroup2 mine" id="mine"><h2 class="tg-h">Mes tirages</h2>
    <p class="help mine-help">${list.length ? "Tes tirages personnels, enregistrés sur cet appareil." : "Invente tes propres tirages : autant de lames que tu veux, le sens de chaque place, et la disposition de ton choix."}</p>
    <div class="carousel">${list.map(c => `<div class="stile-wrap${state.justCreated===c.id?" new":""}">${tile([c.id, SPREADS[c.id]])}
      <div class="stile-acts" data-acts="${c.id}"><button type="button" class="linkbtn" data-cedit="${c.id}">Modifier</button><button type="button" class="linkbtn" data-cdup="${c.id}">Dupliquer</button><button type="button" class="linkbtn danger" data-cdel="${c.id}">Supprimer</button></div></div>`).join("")}
      <button type="button" class="stile stile-new tilt" id="cnew"><span class="stile-art"><span class="plus" aria-hidden="true">+</span></span><span class="stile-n">L'éditeur</span><span class="stile-name">Créer un tirage</span><span class="stile-desc">Le nombre de lames, le sens de chaque place, et leur disposition.</span></button></div></section>`;
}
function bindMine(root){
  const nw = $("#cnew"); if(nw) nw.onclick = () => openEditor(null);
  root.querySelectorAll("[data-cedit]").forEach(b => b.onclick = () => openEditor(b.dataset.cedit));
  root.querySelectorAll("[data-cdup]").forEach(b => b.onclick = () => { const c = customSpreads.find(x=>x.id===b.dataset.cdup); const d = {...JSON.parse(JSON.stringify(c)), id:"c"+Date.now().toString(36)+rand32().toString(36).slice(0,3), label: c.label + " (copie)"}; delete d.deleted; customSpreads.push(d); saveCustom(); registerCustom(d); state.justCreated = d.id; renderTirer(); const m = $("#mine"); if(m) m.scrollIntoView({block:"start"}); });
  root.querySelectorAll("[data-cdel]").forEach(b => b.onclick = () => { const id = b.dataset.cdel, wrap = root.querySelector(`[data-acts="${id}"]`);
    wrap.innerHTML = `<span class="confirm">Supprimer ce tirage ?</span><button type="button" class="linkbtn danger" data-yes>Oui</button><button type="button" class="linkbtn" data-no>Non</button>`;
    wrap.querySelector("[data-yes]").onclick = () => { const c = customSpreads.find(x=>x.id===id);
      if(journal.some(e=>e.spread===id)){ c.deleted = true; registerCustom(c); } else { customSpreads = customSpreads.filter(x=>x.id!==id); delete SPREADS[id]; }
      saveCustom(); renderTirer(); const m = $("#mine"); if(m) m.scrollIntoView({block:"start"}); };
    wrap.querySelector("[data-no]").onclick = () => { renderTirer(); const m = $("#mine"); if(m) m.scrollIntoView({block:"start"}); }; });
  if(state.justCreated){ setTimeout(()=>{ state.justCreated = null; }, 50); }
}

/* ===== Phrases de position, en 6 formulations ou plus par place et par sens =====
   {nom} = nom de la lame, {noyau} = son sens résumé (« un élan neuf et… »), {mois} = mois du tirage de l'année.
   Règles : jamais « de {nom} » ni « à {nom} » (on aurait « de Le Mat »), jamais « de {noyau} »,
   pas de pronom qui renvoie à la lame (son genre change), pas d'adjectif accordé avec « tu ». */
const AB = (X, up, rev) => ({up: up.map(s => s.replaceAll("{X}", X)), rev: rev.map(s => s.replaceAll("{X}", X))});
const PLUS_UP = ["Ce que t'apporterait le chemin {X} : {nom}, avec {noyau}.","Si tu prends le chemin {X}, {nom} t'offre {noyau}.","Le meilleur du chemin {X} : {nom}, avec {noyau}.","Côté {X}, la promesse : {nom}, avec {noyau}.","Choisir {X}, c'est gagner ce que montre {nom} : {noyau}.","Le chemin {X} a un vrai atout : {nom}, avec {noyau}."];
const PLUS_REV = ["Le chemin {X} promet moins qu'il n'y paraît : {nom}, avec {noyau}.","Si tu prends le chemin {X}, le bénéfice reste fragile : {nom}, avec {noyau}.","Le meilleur du chemin {X} est voilé : {nom}, avec {noyau}.","Côté {X}, la promesse est en demi-teinte : {nom}, avec {noyau}.","Choisir {X} rapporterait moins que prévu : {nom}, avec {noyau}.","Le chemin {X} a un atout, mais abîmé : {nom}, avec {noyau}."];
const MOINS_UP = ["Ce que te coûterait le chemin {X} : {nom}. Même {noyau} demande un effort.","Le prix du chemin {X} : {nom}. Même {noyau} se paie.","Côté {X}, l'effort à fournir : {nom}, avec {noyau}.","Le chemin {X} demande quelque chose en retour : {nom}. Même {noyau} a son revers.","Ce que le chemin {X} exigerait de toi : {nom}, avec {noyau}.","Si tu prends le chemin {X}, il faudra porter ce que montre {nom} : {noyau}."];
