/* Phrases d'un tirage perso : la place porte le nom choisi par l'utilisateur */
function customFrames(nm){
  return {up:[`${nm} : {nom}, avec {noyau}.`, `Pour « ${nm} », c'est {nom} qui répond, avec {noyau}.`, `À cette place, « ${nm} », {nom} : {noyau}.`, `« ${nm} » : {nom} y apporte {noyau}.`, `Ici, pour « ${nm} », {nom} montre {noyau}.`, `${nm}, selon {nom} : {noyau}.`],
          rev:[`${nm} : {nom}, à l'envers, avec {noyau}.`, `Pour « ${nm} », {nom} répond à l'envers : {noyau}.`, `« ${nm} » : {nom} y signale {noyau}.`, `Ici, pour « ${nm} », {nom} prévient : {noyau}.`, `${nm}, selon {nom} à l'envers : {noyau}.`, `À cette place, « ${nm} », {nom} demande de regarder {noyau}.`]};
}

/* ----- Éviter de répéter les mêmes phrases d'un tirage à l'autre -----
   À la création, chaque place reçoit un numéro de formulation. Pour une même place et un même sens,
   les formulations utilisées le plus récemment (la moitié du stock) sont écartées, et on tire au sort
   parmi les autres : jamais deux fois de suite la même phrase, sans tomber dans un cycle prévisible. */
function chooseVariants(rd){
  const pos = SPREADS[rd.spread].pos, uses = new Map();
  const note = (key, v) => { if(!uses.has(key)) uses.set(key, []); uses.get(key).push(v); };
  journal.slice(0, 30).forEach(e => { const sp = SPREADS[e.spread]; if(!sp || !Array.isArray(e.fv)) return;
    e.fv.forEach((v,i) => { const p = sp.pos[i], c = e.cards[i]; if(p && c && v != null) note(p + (c.rev?"/r":"/u"), v); });
    if(e.iv != null) note("intro/" + e.theme, e.iv); });
  const choose = (n, key) => {
    const recent = (uses.get(key) || []).slice(0, Math.floor(n/2));
    let free = [...Array(n).keys()].filter(v => !recent.includes(v));
    if(!free.length) free = [...Array(n).keys()];
    const v = free[Math.floor(randFloat() * free.length)];
    uses.set(key, [v, ...(uses.get(key) || [])]);   /* une même place répétée dans un tirage (les mois) */
    return v;
  };
  rd.fv = rd.cards.map((c,i) => { const f = FRAMES[pos[i]]; return f ? choose(f[c.rev?"rev":"up"].length, pos[i] + (c.rev?"/r":"/u")) : null; });
  if(INTROS[rd.theme]) rd.iv = choose(INTROS[rd.theme].length, "intro/" + rd.theme);
}

